INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('eae55b7e-51d9-5dde-94d8-32cb482d75ff', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 10, 10, 'A door swings open through an angle of 75°. Convert this angle to radians.', NULL, 1, 'numeric'::answer_type, '1.309', 'rad', false, NULL, false, NULL, 'θ in radians = 75 × π ÷ 180 = 1.31 rad. Mark scheme (1 mark). A1: θ = 1.31 rad.', 1),
('640ed90d-f705-580e-8e10-9fd2e580b8d1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 11, 11, 'Between 1 o''clock and 8 o''clock the hour hand of a clock turns through 210°. Express this angle in radians.', NULL, 1, 'numeric'::answer_type, '3.665', 'rad', false, NULL, false, NULL, 'θ = 210 × π ÷ 180 = 3.67 rad (7π/6). Mark scheme (1 mark). A1: θ = 3.67 rad.', 1),
('44483dd4-9f8d-5d77-ab93-b5e69b8a5497', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 12, 12, 'A radar dish is rotated through 1.20 rad to track an aircraft. What is this angle in degrees?', NULL, 1, 'numeric'::answer_type, '68.75', '°', false, NULL, false, NULL, 'angle in degrees = 1.20 × 180 ÷ π = 68.8°. Mark scheme (1 mark). A1: angle = 68.8°.', 1),
('6be8c1ed-8ead-56fa-b2e3-7e559bf22080', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 13, 13, 'The arm of a metronome swings through 0.35 rad from one side to the other. Find the angle in degrees.', NULL, 1, 'numeric'::answer_type, '20.05', '°', false, NULL, false, NULL, 'angle = 0.35 × 180 ÷ π = 20°. Mark scheme (1 mark). A1: angle = 20°.', 1),
('5f9ac3fa-9f0b-5462-85f9-90f2fae62483', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 14, 14, 'A pendulum bob hangs on a string of length 0.80 m. It swings through an angle of 0.25 rad. Calculate the length of the arc it moves along.', NULL, 1, 'numeric'::answer_type, '0.2', 'm', false, NULL, false, NULL, 'Arc length s = rθ (θ in radians) = 0.80 × 0.25 = 0.20 m. Mark scheme (2 marks). C1: s = rθ with θ in radians. A1: s = 0.20 m.', 2),
('e9fd28c9-ab32-577f-bc28-a595ea58568e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 15, 15, 'The valve on a bicycle wheel is 0.34 m from the axle. It moves 0.85 m along its circular path. Through what angle, in radians, has the wheel turned?', NULL, 1, 'numeric'::answer_type, '2.5', 'rad', false, NULL, false, NULL, 'θ = s/r = 0.85 ÷ 0.34 = 2.5 rad. Mark scheme (2 marks). C1: θ = s/r. A1: θ = 2.5 rad.', 2),
('82a444d5-fbc4-57cd-a13d-e76dfab413f9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 16, 16, 'A ceiling fan completes one revolution every 0.40 s. Calculate its angular speed.', NULL, 1, 'numeric'::answer_type, '15.71', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.40 = 15.7 rad s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T. A1: ω = 15.7 rad s⁻¹.', 2),
('52bd56af-f9e2-589f-a764-1cb0284b1f87', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 17, 17, 'A computer hard-disk platter is rated at 7200 rev min⁻¹. Express this as an angular speed in rad s⁻¹.', NULL, 1, 'numeric'::answer_type, '754', 'rad s⁻¹', false, NULL, false, NULL, '7200 ÷ 60 = 120 revolutions per second. ω = 2π × 7200 ÷ 60 = 754 rad s⁻¹. Mark scheme (2 marks). C1: ÷ 60 and × 2π. A1: ω = 754 rad s⁻¹.', 2),
('209dbba6-1d77-5141-89ce-618bd3cfb007', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 18, 18, 'A playground roundabout turns with an angular speed of 2.1 rad s⁻¹. How long does it take to go round once?', NULL, 1, 'numeric'::answer_type, '2.992', 's', false, NULL, false, NULL, 'T = 2π/ω = 2π ÷ 2.1 = 3.0 s. Mark scheme (2 marks). C1: T = 2π/ω. A1: T = 3.0 s.', 2),
('adab4363-e4ac-5f2c-b550-43a756b7efc6', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 19, 19, 'Which statement defines the radian?', NULL, 1, 'multiple_choice'::answer_type, 'The angle subtended at the centre of a circle by an arc equal in length to the radius', NULL, false, NULL, false, NULL, 'One radian is the angle at the centre of a circle when the arc length equals the radius, so θ = s/r. A full circle is 2π rad = 360°. The other options describe 2 rad, one degree and the angular speed. Mark scheme (1 mark). B1: C (The angle subtended at the centre of a circle by an arc equal in length to the radius).', 1),
('eaf444c7-c726-559c-a815-75496aae2ae9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 20, 20, 'How many radians are there in one complete revolution?', NULL, 1, 'multiple_choice'::answer_type, '2π', NULL, false, NULL, false, NULL, 'The circumference is 2πr, so the angle for a full circle is s/r = 2πr/r = 2π rad (= 360°). Mark scheme (1 mark). B1: A (2π).', 1),
('ce938cf5-3550-5806-8340-886d9100cf38', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 21, 21, 'A potter''s wheel rotates steadily at 90 rev min⁻¹. Calculate the angle, in radians, that it turns through in 2.5 s.', NULL, 2, 'numeric'::answer_type, '23.56', 'rad', false, NULL, false, NULL, 'ω = 2π × 90 ÷ 60 = 9.42 rad s⁻¹. θ = ωt = 9.42 × 2.5 = 23.6 rad. Mark scheme (3 marks). C1: ω = 2π × (rev per min) ÷ 60. C1: θ = ωt. A1: θ = 23.6 rad. Common mistake: using the revolutions per minute directly as ω, without converting minutes to seconds and revolutions to radians.', 3),
('79d0fe0c-5aca-505d-911b-4e33b4f8ac42', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 22, 22, 'A turntable plays a record at 33 rev min⁻¹. A dust particle sits on the record. How many degrees does it turn through in 4.0 s?', NULL, 2, 'numeric'::answer_type, '792', '°', false, NULL, false, NULL, 'ω = 2π × 33 ÷ 60 = 3.46 rad s⁻¹. θ = ωt = 3.46 × 4.0 = 13.8 rad. In degrees: 13.8 × 180 ÷ π = 792°. Mark scheme (3 marks). C1: ω in rad s⁻¹. C1: θ = ωt. C1: conversion to degrees.', 3),
('1c4229d9-279d-5df8-8260-a168a4d31af9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 23, 23, 'The Earth turns once on its axis every 24.0 h. Its equatorial radius is 6.37 × 10⁶ m. Calculate the speed of a point on the Equator due to this rotation.', NULL, 2, 'numeric'::answer_type, '463.2', 'm s⁻¹', false, NULL, false, NULL, 'T = 24.0 × 3600 = 86400 s. ω = 2π ÷ 86400 = 7.27 × 10⁻⁵ rad s⁻¹. v = ωr = 7.27 × 10⁻⁵ × 6.37 × 10⁶ = 463 m s⁻¹. Mark scheme (3 marks). C1: ω = 2π/T with T in seconds. C1: v = ωr. A1: v = 463 m s⁻¹.', 3),
('237342af-5173-50a0-ad06-c51bd82bcef5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 24, 24, 'The blades of a large wind turbine are 45 m long and turn once every 4.2 s. Calculate the speed of a blade tip.', NULL, 2, 'numeric'::answer_type, '67.32', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 4.2 = 1.50 rad s⁻¹. v = ωr = 1.50 × 45 = 67.3 m s⁻¹. Mark scheme (3 marks). C1: ω = 2π/T. C1: v = ωr. A1: v = 67.3 m s⁻¹.', 3),
('8f59c33f-ae55-51aa-98f7-eefb4100470e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 25, 25, 'A rigid disc rotates at a steady rate. Point X is 4.0 cm from the axis and point Y is 12.0 cm from the axis. Which row compares their angular speeds ω and their speeds v?', NULL, 2, 'multiple_choice'::answer_type, 'ω the same for both; v of Y is three times v of X', NULL, false, NULL, false, NULL, 'Every point on a rigid rotating body turns through the same angle in the same time, so ω is the same. v = ωr, so v ∝ r: Y is 3 times as far from the axis and moves 3 times as fast. Mark scheme (3 marks). C1: all points on a rigid body have the same ω. C1: v = ωr so v is proportional to r. A1: D (ω the same for both; v of Y is three times v of X). Common mistake: thinking the outer point turns "faster" in angle. It covers more distance, not more angle.', 3),
('99cfeeca-f880-5526-a83f-d5ff0a92c806', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 26, 26, 'A car travels round a roundabout. Its front-left and front-right wheels have the same diameter. The left wheels are on the inside of the bend. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The right wheels have the larger angular speed about their axles', NULL, false, NULL, false, NULL, 'The outer (right) wheels travel round a larger circle in the same time, so they cover a greater distance and have a higher linear speed. For a rolling wheel v = ωr with the same wheel radius, so the right wheels must spin faster about their axles. (This is why a car needs a differential.). Mark scheme (3 marks). C1: outer wheels cover a larger circle in the same time, so larger v. C1: v = ωr for rolling, same r so larger ω. A1: B (The right wheels have the larger angular speed about their axles).', 3),
('ab2b6901-9580-518f-ae36-f03b4781fd3b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 27, 27, 'An athlete running round the curved end of a track covers 62 m while her direction of motion turns through 150°. Calculate the radius of the curve.', NULL, 2, 'numeric'::answer_type, '23.68', 'm', false, NULL, false, NULL, 'θ = 150 × π ÷ 180 = 2.62 rad. r = s/θ = 62 ÷ 2.62 = 23.7 m. Mark scheme (3 marks). C1: θ converted to radians. C1: r = s/θ. A1: r = 23.7 m. Common mistake: dividing the arc length by the angle in degrees.', 3),
('3baf8163-6073-547c-83ef-b13130e85111', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 28, 28, 'A railway curve has a radius of 1.8 km. Along the curve the direction of the track changes by 24°. Calculate the length of track on the curve.', NULL, 2, 'numeric'::answer_type, '754', 'm', false, NULL, false, NULL, 'θ = 24 × π ÷ 180 = 0.419 rad. s = rθ = 1800 × 0.419 = 754 m. Mark scheme (3 marks). C1: angle in radians. C1: s = rθ with r in m. A1: s = 754 m.', 3),
('69c7fed7-20c6-5b28-a8e2-c2b7fb2f4fd8', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 29, 29, 'Calculate the ratio (angular speed of the minute hand of a clock) / (angular speed of the hour hand).', NULL, 2, 'numeric'::answer_type, '12', NULL, false, NULL, false, NULL, 'Minute hand: T = 3600 s. Hour hand: T = 12 h = 43200 s. ω = 2π/T, so the ratio = (2π/3600)/(2π/43200) = 12. Mark scheme (3 marks). C1: period of hour hand is 12 h, of minute hand 1 h. C1: ω ∝ 1/T. A1: ratio = 12. Common mistake: taking the hour hand period as 24 h — it goes round twice a day.', 3),
('6b8ba197-748d-5a5a-b45d-c061ad17b6a4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 30, 30, 'A laboratory centrifuge spins at 420 rad s⁻¹ for 30 s. How many revolutions does it make?', NULL, 2, 'numeric'::answer_type, '2005', NULL, false, 0.02, false, NULL, 'Angle = ωt = 420 × 30 = 12600 rad. Revolutions = 12600 ÷ 2π = 2010. Mark scheme (3 marks). C1: θ = ωt. C1: number of revolutions = θ/2π. A1: number of revolutions = 2010.', 3),
('8bd1968f-7a1e-5feb-90cc-892db3997d4b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 31, 31, 'A flywheel turning at 95 rad s⁻¹ is used to store energy. Calculate the time it takes to complete 18 revolutions.', NULL, 2, 'numeric'::answer_type, '1.19', 's', false, NULL, false, NULL, '18 revolutions = 18 × 2π = 113 rad. t = θ/ω = 36π ÷ 95 = 1.19 s. Mark scheme (3 marks). C1: angle = 2π × number of revolutions. C1: t = θ/ω. A1: t = 1.19 s.', 3),
('3f1b6408-7ade-51c3-8348-c950edccba98', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 32, 32, 'Two towns lie on the same line of longitude, at latitudes 32° N and 47° N. Treat the Earth as a sphere of radius 6.37 × 10⁶ m. Calculate the distance between them measured along the Earth''s surface.', NULL, 2, 'numeric'::answer_type, '1.668e6', 'm', false, NULL, false, NULL, 'Angle at the Earth''s centre = 47 − 32 = 15° = 15 × π ÷ 180 = 0.262 rad. s = rθ = 6.37 × 10⁶ × 0.262 = 1.67 × 10⁶ m. Mark scheme (4 marks). C1: angle at centre is the difference in latitude. C1: conversion to radians. C1: s = rθ. A1: s = 1.67 × 10⁶ m.', 4),
('92bbfc76-307b-58b7-a30d-5b42b38be7ab', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 33, 33, 'A ship sails due north along a line of longitude, from latitude 5° S to latitude 12° N. The Earth''s radius is 6.37 × 10⁶ m. How far does the ship sail?', NULL, 2, 'numeric'::answer_type, '1.89e6', 'm', false, NULL, false, NULL, 'The positions are on opposite sides of the Equator, so the angle at the centre is 5 + 12 = 17° = 0.297 rad. s = rθ = 6.37 × 10⁶ × 0.297 = 1.89 × 10⁶ m. Mark scheme (4 marks). C1: angle 17° (latitudes added across the Equator). C1: conversion to radians. C1: s = rθ. A1: s = 1.89 × 10⁶ m. Common mistake: subtracting 5 from 12: the two positions are on opposite sides of the Equator.', 4),
('f0073cab-f081-51a5-a62a-f6c9171694e8', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 34, 34, 'A bicycle chain links a front sprocket of radius 10.0 cm to a rear sprocket of radius 4.0 cm. The rider turns the pedals (and the front sprocket) at 1.5 rev s⁻¹. Calculate the angular speed of the rear sprocket.', NULL, 2, 'numeric'::answer_type, '23.56', 'rad s⁻¹', false, NULL, false, NULL, 'ω₁ = 2π × 1.5 = 9.42 rad s⁻¹. The chain moves at the same speed round both sprockets, so ω₁r₁ = ω₂r₂ and ω₂ = ω₁r₁/r₂ = 9.42 × 10.0 ÷ 4.0 = 23.6 rad s⁻¹. Mark scheme (4 marks). C1: ω₁ = 2πf. C1: same chain speed at both sprockets. C1: ω₂ = ω₁r₁/r₂. A1: ω₂ = 23.6 rad s⁻¹. Common mistake: assuming the two sprockets have the same angular speed.', 4),
('fb6adeb1-2c8a-5056-8974-320bb89d00e0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 35, 35, 'In a workshop, a belt runs without slipping round a motor pulley of radius 2.5 cm and a lathe pulley of radius 15 cm. The motor pulley makes 24 revolutions every second. Find the angular speed of the lathe pulley.', NULL, 2, 'numeric'::answer_type, '25.13', 'rad s⁻¹', false, NULL, false, NULL, 'ω_motor = 2π × 24 = 151 rad s⁻¹. Same belt speed: ω_lathe = ω_motor × r_motor/r_lathe = 151 × 2.5 ÷ 15 = 25.1 rad s⁻¹. Mark scheme (4 marks). C1: ω = 2πf. C1: v the same at both pulleys. C1: ratio of radii. A1: ω = 25.1 rad s⁻¹.', 4),
('eaaa0138-6147-57aa-899e-dcb5085909be', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 36, 36, 'A gymnast does a complete somersault (one full turn) in 0.80 s. A diver does 2½ somersaults in 1.6 s. Which statement about their average angular speeds is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The diver''s average angular speed is 1.25 times the gymnast''s', NULL, false, NULL, false, NULL, 'Gymnast: ω = 2π ÷ 0.80 = 7.85 rad s⁻¹. Diver: ω = 2.5 × 2π ÷ 1.6 = 9.82 rad s⁻¹. Ratio = 9.82 ÷ 7.85 = 1.25. Mark scheme (3 marks). C1: ω = θ/t for each. C1: ratio. A1: C (The diver''s average angular speed is 1.25 times the gymnast''s).', 3),
('5814b914-d626-51d6-b3ed-c7d7100fb8c8', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 37, 37, 'A golfer''s club swings through 0.60 rad in 0.15 s just before it hits the ball. The club head is 1.1 m from the golfer''s shoulders, the centre of the swing. Estimate the speed of the club head, assuming steady rotation.', NULL, 2, 'numeric'::answer_type, '4.4', 'm s⁻¹', false, NULL, false, NULL, 'ω = θ/t = 0.60 ÷ 0.15 = 4.00 rad s⁻¹. v = ωr = 4.00 × 1.1 = 4.4 m s⁻¹. Mark scheme (3 marks). C1: ω = θ/t. C1: v = ωr. A1: v = 4.4 m s⁻¹.', 3),
('fc2bb68f-3a91-5f4f-90ad-9fb246ca79c0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 38, 38, 'A wheel of radius 0.30 m rotates at 4.0 rad s⁻¹. A student says the rim moves at 4.0 × 0.30 × 2π m s⁻¹. What is wrong with this?', NULL, 2, 'multiple_choice'::answer_type, 'The factor 2π should not be there: v = ωr already gives the speed in m s⁻¹ when ω is in rad s⁻¹', NULL, false, NULL, false, NULL, 'The radian is defined by s = rθ, so v = rω directly gives 1.2 m s⁻¹. The 2π belongs only in converting revolutions to radians (ω = 2πf). Mark scheme (3 marks). C1: v = ωr with ω in rad s⁻¹. C1: 2π only converts revolutions to radians. A1: A (The factor 2π should not be there: v = ωr already gives the speed in m s⁻¹ when ω is in rad s⁻¹).', 3),
('a56efaf5-0776-5d00-886d-055599a29da5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 39, 39, 'London is at latitude 51.5° N. The Earth (radius 6.37 × 10⁶ m) rotates once every 24.0 hours. (a) Calculate the angular speed of the Earth. (b) Explain why London moves in a circle of radius R cos 51.5°, and calculate this radius. (c) Calculate the speed of London due to the Earth''s rotation. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '288.4', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π/T = 2π ÷ 86400 = 7.27 × 10⁻⁵ rad s⁻¹. (b) The point circles the Earth''s axis, so its radius is its perpendicular distance from the axis, R cos(latitude) = 6.37 × 10⁶ × cos 51.5 = 3.97 × 10⁶ m. (c) v = ωr = 7.27 × 10⁻⁵ × 3.97 × 10⁶ = 288 m s⁻¹. Mark scheme (5 marks). C1: T = 86 400 s. A1: ω = 7.27 × 10⁻⁵ rad s⁻¹. B1: r = R cos(latitude), perpendicular distance to the axis. C1: v = ωr. A1: v = 288 m s⁻¹. Common mistake: using the Earth''s radius R as the radius of the circle. Only a point on the Equator moves in a circle of radius R.', 5),
('a95c99e5-86ac-54ba-b309-270908754581', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 40, 40, 'A rocket launch site is chosen close to the Equator because the Earth''s spin gives a rocket a "free" eastward speed. Compare a site at latitude 30.0° N. (a) Show that the Earth''s angular speed is 7.27 × 10⁻⁵ rad s⁻¹ (period 24.0 h). (b) Find the distance of the 30.0° N site from the Earth''s axis (Earth radius 6.37 × 10⁶ m). (c) Calculate the eastward speed the site has because of the rotation. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '401.2', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π/T = 2π ÷ 86400 = 7.27 × 10⁻⁵ rad s⁻¹. (b) The point circles the Earth''s axis, so its radius is its perpendicular distance from the axis, R cos(latitude) = 6.37 × 10⁶ × cos 30.0 = 5.52 × 10⁶ m. (c) v = ωr = 7.27 × 10⁻⁵ × 5.52 × 10⁶ = 401 m s⁻¹. Mark scheme (5 marks). C1: T = 86 400 s. A1: ω = 7.27 × 10⁻⁵ rad s⁻¹. B1: r = R cos(latitude), perpendicular distance to the axis. C1: v = ωr. A1: v = 401 m s⁻¹. Common mistake: using the Earth''s radius R as the radius of the circle. Only a point on the Equator moves in a circle of radius R.', 5),
('e9242cf0-bbd8-5a8f-809a-91ca1a4319bb', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 41, 41, 'A car travels at a steady 25 m s⁻¹ on a motorway. Each wheel has diameter 0.62 m and rolls without slipping. (a) Calculate the angular speed of a wheel. (b) Express this angular speed in rev min⁻¹. (c) Calculate the number of revolutions a wheel makes while the car travels 1.0 km. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '770.1', 'rev min⁻¹', false, NULL, false, NULL, '(a) r = 0.62 ÷ 2 = 0.310 m. ω = v/r = 25 ÷ 0.310 = 80.6 rad s⁻¹. (b) in rev min⁻¹: 80.6 × 60 ÷ (2π) = 770 rev min⁻¹. (c) circumference = 2πr = 1.95 m, so revolutions = 1000 ÷ 1.948 = 513. Mark scheme (5 marks). C1: r = half the diameter. A1: ω value. C1: × 60 ÷ 2π. A1: 770 rev min⁻¹. B1: (c) distance ÷ circumference. Common mistake: using the diameter instead of the radius in v = ωr, which halves ω.', 5),
('670112df-ab9d-52e9-9355-f80c0a278e79', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 42, 42, 'A rider on a motorbike travels 500 m at 13.5 m s⁻¹. The motorbike''s wheels have diameter 0.70 m. (a) Calculate the time taken. (b) Calculate the angular speed of the wheels. (c) Use your answers to find the number of revolutions each wheel makes. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '227.4', NULL, false, 0.02, false, NULL, '(a) t = 500 ÷ 13.5 = 37.0 s. (b) ω = v/r = 13.5 ÷ 0.35 = 38.6 rad s⁻¹. (c) angle = ωt = 38.6 × 37.0 = 1430 rad, revolutions = 1429 ÷ 2π = 227. Mark scheme (5 marks). A1: t. C1: ω = v/r with r = d/2. A1: revolutions = 227. C1: θ = ωt. C1: ÷ 2π.', 5),
('2fd4b799-c884-573c-8228-1ae72bd68136', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 43, 43, 'A student films a turntable and records the angle θ turned at time t: t = 0, 0.5, 1.0, 1.5, 2.0 s; θ = 0, 1.6, 3.1, 4.7, 6.3 rad. (a) Describe the graph of θ against t and state what it shows about the motion. (b) Determine the angular speed from the gradient. (c) A coin sits 0.15 m from the axis. Calculate its speed. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.4725', 'm s⁻¹', false, NULL, false, NULL, '(a) A straight line through the origin: θ ∝ t, so the angular speed is constant. (b) gradient = Δθ/Δt = 6.3 ÷ 2.0 = 3.15 rad s⁻¹. (c) v = ωr = 3.15 × 0.15 = 0.47 m s⁻¹. Mark scheme (5 marks). B1: straight line through origin. B1: constant angular speed. C1: gradient = Δθ/Δt. A1: v = 0.47 m s⁻¹. C1: v = ωr. Common mistake: using one reading without checking the graph is a straight line through the origin.', 5),
('16006987-b369-58a7-aedd-d78dda47eba3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 44, 44, 'A rotating platform at a science museum is timed. Its angular position is: at 0 s, 0 rad; at 2.0 s, 1.1 rad; at 4.0 s, 2.3 rad; at 6.0 s, 3.4 rad; at 8.0 s, 4.5 rad. (a) Show that the platform rotates at an approximately constant rate. (b) Use the data to find the period of rotation. (c) A visitor stands 2.4 m from the axis. Calculate the visitor''s speed. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.35', 'm s⁻¹', false, 0.05, false, NULL, '(a) Each 2.0 s interval adds about 1.1 rad, so Δθ/Δt is constant. (b) ω = 4.5 ÷ 8.0 = 0.562 rad s⁻¹, T = 2π/ω = 11.2 s. (c) v = ωr = 0.562 × 2.4 = 1.3 m s⁻¹. Mark scheme (5 marks). B1: equal increases in equal times. C1: ω from the data. A1: T. C1: v = ωr. A1: v = 1.3 m s⁻¹.', 5),
('a36b4571-2d55-5902-a629-359689b12b46', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 45, 45, 'The minute hand of the clock on a town hall is 1.2 m long. (a) Show that its angular speed is about 1.7 × 10⁻³ rad s⁻¹. (b) Calculate the speed of the tip of the hand. (c) Calculate the angle, in degrees, the hand turns through in 10 s. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.002094', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π/T = 2π ÷ 3600 = 0.00175 rad s⁻¹ ≈ 1.7 × 10⁻³ rad s⁻¹. (b) v = ωr = 0.00175 × 1.2 = 0.00209 m s⁻¹. (c) angle = ωt = 0.00175 × 10 = 0.0175 rad = 1.00°. Mark scheme (5 marks). M1: ω = 2π/T with T = 3600 s. A1: ω shown to more s.f. than given. C1: v = ωr. A1: v = 0.00209 m s⁻¹. B1: (c) angle in degrees.', 5),
('965a177b-7ccc-5bbb-9200-03b2270eedbb', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 46, 46, 'Mars moves in an approximately circular orbit of radius 2.28 × 10¹¹ m around the Sun with an orbital period of 687 days. (a) Calculate the angular speed of Mars in its orbit. (b) Calculate the distance Mars travels along its orbit in one day. (c) Explain why Mars is accelerating even though its speed is constant. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.085e9', 'm', false, NULL, false, NULL, '(a) T = 687 × 86400 = 5.94 × 10⁷ s, ω = 2π/T = 2π ÷ 5.94 × 10⁷ = 1.06 × 10⁻⁷ rad s⁻¹. (b) In one day it turns through ωt = 1.06 × 10⁻⁷ × 86400 = 0.00915 rad, so s = rθ = 2.28 × 10¹¹ × 0.00915 = 2.09 × 10⁹ m. (c) Its direction of motion changes continuously, so its velocity changes: there is an acceleration towards the Sun. Mark scheme (5 marks). C1: T in seconds. A1: ω value. C1: θ = ωt for one day. A1: s = 2.09 × 10⁹ m. B1: velocity direction changes, so acceleration.', 5),
('33cf2f4f-e947-52b0-9c25-c50d632ed772', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 47, 47, 'Venus orbits the Sun in a circle of radius 1.08 × 10¹¹ m with period 225 days. (a) Calculate its angular speed. (b) Calculate its orbital speed. (c) Calculate how many days it takes Venus to move a quarter of the way round its orbit, and explain why equal angles would take unequal times if the orbit were an ellipse. Give only the number of days in (c).', NULL, 3, 'numeric'::answer_type, '56.25', 'days', false, NULL, false, NULL, '(a) ω = 2π ÷ (225 × 86400) = 3.23 × 10⁻⁷ rad s⁻¹. (b) v = ωr = 3.23 × 10⁻⁷ × 1.08 × 10¹¹ = 3.49 × 10⁴ m s⁻¹. (c) For a circle the angular speed is constant, so t = (π/2) ÷ ω = 4.86 × 10⁶ s = 4.86 × 10⁶ ÷ 86400 = 56.2 days. In an ellipse ω is not constant, so equal angles take unequal times. Mark scheme (5 marks). A1: ω. C1: v = ωr. A1: t = 56.2 days. C1: t = θ/ω with θ = π/2. B1: angular speed varies in an ellipse.', 5),
('da2ea463-02db-5e36-92b5-299af2b0fe56', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 48, 48, 'A motor turns a small pulley of radius 3.0 cm at a frequency of 50 Hz. A belt connects it, without slipping, to a large pulley of radius 9.0 cm. (a) Calculate the angular speed of the small pulley. (b) Calculate the speed of the belt. (c) Calculate the angular speed of the large pulley. (d) Calculate the time taken for the large pulley to make 60 revolutions. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '3.6', 's', false, NULL, false, NULL, '(a) ω₁ = 2πf = 2π × 50 = 314 rad s⁻¹. (b) v = ω₁r₁ = 314 × 0.030 = 9.42 m s⁻¹. (c) ω₂ = v/r₂ = 9.42 ÷ 0.090 = 105 rad s⁻¹. (d) 60 revolutions = 120π rad, t = 120π ÷ 104.7 = 3.60 s. Mark scheme (6 marks). C1: ω₁ = 2πf. C1: v = ω₁r₁. C1: belt speed the same at both pulleys. C1: ω₂ = v/r₂. C1: angle for 60 revolutions = 120π rad. A1: t = 3.60 s.', 6),
('824061d5-4acb-59df-affd-e6fe23149553', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 49, 49, 'A tape drive uses two reels. The tape leaves a full reel of outer radius 20.0 cm and is wound onto an empty hub of radius 5.0 cm at the same tape speed. The hub turns at 12 Hz. (a) Calculate the tape speed. (b) Calculate the frequency of the full reel. (c) Explain what happens to the frequency of the hub as tape builds up on it, if the tape speed stays constant. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3', 'Hz', false, NULL, false, NULL, '(a) v = ωr = 2π × 12 × 0.050 = 3.77 m s⁻¹. (b) f = v/(2πr) = 3.770 ÷ (2π × 0.200) = 3.00 Hz. (c) As the radius of tape on the hub grows, f = v/2πr falls: the hub slows down. Mark scheme (6 marks). C1: v = ωr = 2πfr. A1: v. C1: same v at both reels. A1: f = 3.00 Hz. B1: f ∝ 1/r. B1: hub slows as r increases.', 6),
('9e3516eb-75bd-5088-ba9d-47e1f27f1584', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 50, 50, 'A simple pendulum of length 1.50 m is pulled aside until the string makes 12.0° with the vertical, and released. (a) Convert 12.0° to radians. (b) Calculate the length of the arc the bob travels from release to the lowest point. (c) Calculate the straight-line (chord) distance between those two positions and comment on the difference. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.3142', 'm', false, NULL, false, NULL, '(a) θ = 12.0 × π ÷ 180 = 0.209 rad. (b) s = rθ = 1.50 × 0.209 = 0.314 m. (c) chord = 2r sin(θ/2) = 2 × 1.50 × sin 6.0 = 0.314 m: shorter by only about 0.2 %, so for small angles the arc and chord are almost equal. Mark scheme (5 marks). C1: θ in radians. A1: 0.209 rad. C1: s = rθ. A1: s = 0.314 m. B1: (c) chord = 2r sin(θ/2) and comparison.', 5),
('f41d7cba-01a2-53ce-85ae-606a5ed20b3c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '16.2', '9702 coursebook 16.2 · Radians and angular speed', 51, 51, 'The Moon orbits the Earth at a distance of 3.84 × 10⁸ m with a period of 27.3 days. (a) Calculate the angular speed of the Moon. (b) Calculate the angle, in degrees, the Moon moves round its orbit in one day. (c) Calculate the orbital speed of the Moon. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1023', 'm s⁻¹', false, NULL, false, NULL, '(a) T = 27.3 × 86400 = 2.36 × 10⁶ s. ω = 2π ÷ 2.36 × 10⁶ = 2.66 × 10⁻⁶ rad s⁻¹. (b) 360 ÷ 27.3 = 13.2° per day. (c) v = ωr = 2.66 × 10⁻⁶ × 3.84 × 10⁸ = 1020 m s⁻¹. Mark scheme (5 marks). C1: T in seconds. A1: ω. B1: angle per day. C1: v = ωr. A1: v = 1020 m s⁻¹.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('1452406a-7457-5789-b72d-e6d98f7ab146', 'adab4363-e4ac-5f2c-b550-43a756b7efc6', 'The angle subtended at the centre of a circle by an arc equal in length to the diameter', 'A', false, 0),
('1317d208-4a5c-5acd-a9b5-c8d13844eb62', 'adab4363-e4ac-5f2c-b550-43a756b7efc6', 'One three-hundred-and-sixtieth of a complete revolution', 'B', false, 1),
('5a7152d2-d8c2-5b7a-9960-03c25b36892b', 'adab4363-e4ac-5f2c-b550-43a756b7efc6', 'The angle subtended at the centre of a circle by an arc equal in length to the radius', 'C', true, 2),
('081f6896-b975-5d36-899b-1cd5c885432d', 'adab4363-e4ac-5f2c-b550-43a756b7efc6', 'The angle turned through in one second by an object moving in a circle', 'D', false, 3),
('5dcecea1-6272-5d66-890f-6043f559538b', 'eaf444c7-c726-559c-a815-75496aae2ae9', '2π', 'A', true, 0),
('f668eccf-c124-5d18-9557-0b9f4ecfba82', 'eaf444c7-c726-559c-a815-75496aae2ae9', 'π', 'B', false, 1),
('5c47a6a7-2af2-59d5-ab95-50bcc6f08cc0', 'eaf444c7-c726-559c-a815-75496aae2ae9', '360', 'C', false, 2),
('68b43678-b8f9-5077-ba05-0597eb60ff80', 'eaf444c7-c726-559c-a815-75496aae2ae9', 'π/2', 'D', false, 3),
('6721ee45-85d7-5775-921a-34f138f8aa5d', '8f59c33f-ae55-51aa-98f7-eefb4100470e', 'ω of Y is three times ω of X; v the same for both', 'A', false, 0),
('529b4b1f-83c5-50cb-b9c4-22bbbc5daaf9', '8f59c33f-ae55-51aa-98f7-eefb4100470e', 'ω the same for both; v the same for both', 'B', false, 1),
('4c897445-ae4c-5205-9d68-6cadf616a525', '8f59c33f-ae55-51aa-98f7-eefb4100470e', 'ω of X is three times ω of Y; v of Y is three times v of X', 'C', false, 2),
('63514989-edf4-5faa-95f0-2838c2d36409', '8f59c33f-ae55-51aa-98f7-eefb4100470e', 'ω the same for both; v of Y is three times v of X', 'D', true, 3),
('e1d8dde4-88dd-5ade-b3dc-52db420cde28', '99cfeeca-f880-5526-a83f-d5ff0a92c806', 'The left wheels have the larger angular speed about their axles', 'A', false, 0),
('12f9cd21-a880-5359-b1be-b83e1d914f20', '99cfeeca-f880-5526-a83f-d5ff0a92c806', 'The right wheels have the larger angular speed about their axles', 'B', true, 1),
('dbeb5510-f1b3-5c00-84ce-f4beb27d2ca8', '99cfeeca-f880-5526-a83f-d5ff0a92c806', 'Both have the same angular speed because the wheels are identical', 'C', false, 2),
('5e6a400a-6822-5dcc-89a5-81c7fa6a789b', '99cfeeca-f880-5526-a83f-d5ff0a92c806', 'Both have the same linear speed because they are on the same car', 'D', false, 3),
('22e0ad23-3a55-511b-8a7e-42213931973f', 'eaaa0138-6147-57aa-899e-dcb5085909be', 'The gymnast''s average angular speed is 1.25 times the diver''s', 'A', false, 0),
('4ea44bfd-b14a-5e3b-bbb7-a2417254f3f8', 'eaaa0138-6147-57aa-899e-dcb5085909be', 'They have the same average angular speed', 'B', false, 1),
('471f4f88-f304-538f-90a2-525f55480fd4', 'eaaa0138-6147-57aa-899e-dcb5085909be', 'The diver''s average angular speed is 1.25 times the gymnast''s', 'C', true, 2),
('6da684b5-3474-5163-866d-10499e7faaf0', 'eaaa0138-6147-57aa-899e-dcb5085909be', 'The diver''s average angular speed is 2.5 times the gymnast''s', 'D', false, 3),
('b2daacc1-270e-5a4a-b1cd-4cbca6f159ca', 'fc2bb68f-3a91-5f4f-90ad-9fb246ca79c0', 'The factor 2π should not be there: v = ωr already gives the speed in m s⁻¹ when ω is in rad s⁻¹', 'A', true, 0),
('bb3274d3-cfba-51df-85cf-a54277602b9a', 'fc2bb68f-3a91-5f4f-90ad-9fb246ca79c0', 'Nothing: v = 2πωr', 'B', false, 1),
('d4b4ddc7-7a1a-532e-8140-efa57e9f8100', 'fc2bb68f-3a91-5f4f-90ad-9fb246ca79c0', 'The radius should be squared', 'C', false, 2),
('1d8fcbfe-d447-5cfb-bcfc-981e84dccc7e', 'fc2bb68f-3a91-5f4f-90ad-9fb246ca79c0', 'The speed should be ω/r', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('c4ca3345-9cd1-51bc-ac82-c13237acb0f3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 7, 7, 'An object moves in a circle at constant speed. Which quantity is constant?', NULL, 1, 'multiple_choice'::answer_type, 'Its kinetic energy', NULL, false, NULL, false, NULL, 'Speed is constant, so ½mv² is constant. Velocity, momentum and acceleration are vectors whose directions change continuously round the circle. Mark scheme (1 mark). B1: C (Its kinetic energy).', 1),
('be2c020b-194a-5255-9870-12a7b37712cd', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 8, 8, 'A stone is whirled in a horizontal circle at constant speed. In which direction is its acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'Towards the centre of the circle', NULL, false, NULL, false, NULL, 'The velocity changes direction, so there is an acceleration. It points in the direction of the change in velocity, which is towards the centre (centripetal). Mark scheme (1 mark). B1: A (Towards the centre of the circle).', 1),
('1732e2fb-d6b0-54ae-91e5-8591ee5761e7', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 9, 9, 'At any instant, what is the direction of the velocity of a body moving in a circle?', NULL, 1, 'multiple_choice'::answer_type, 'Along the tangent to the circle', NULL, false, NULL, false, NULL, 'The velocity is always along the tangent, at 90° to the radius. If the centripetal force were removed, the body would carry on along this tangent. Mark scheme (1 mark). B1: D (Along the tangent to the circle).', 1),
('cdecc92d-0325-5533-858b-763a07b07f4f', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 10, 10, 'A car drives round a circular track at a steady 20 m s⁻¹. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The car is accelerating because its direction of motion is changing', NULL, false, NULL, false, NULL, 'Acceleration is the rate of change of velocity. Velocity is a vector, so a change of direction alone is a change of velocity. The car accelerates towards the centre. There is a resultant force, so it is not in equilibrium. Mark scheme (1 mark). B1: B (The car is accelerating because its direction of motion is changing).', 1),
('f76ce2bd-81d5-5335-a1e2-00cd8221490b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 11, 11, 'The string holding a ball moving in a horizontal circle breaks. Ignoring gravity, how does the ball move immediately afterwards?', NULL, 1, 'multiple_choice'::answer_type, 'In a straight line along the tangent at the point where the string broke', NULL, false, NULL, false, NULL, 'Once the string breaks there is no centripetal force, so by Newton''s first law the ball continues with the velocity it had at that instant: along the tangent. Mark scheme (1 mark). B1: C (In a straight line along the tangent at the point where the string broke).', 1),
('2b6927ed-d7e8-58e2-bc1a-b1b2570533e0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 12, 12, 'Which statement about a body moving in a circle at constant speed is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The resultant force on it is perpendicular to its velocity', NULL, false, NULL, false, NULL, 'The resultant force is centripetal: towards the centre, at right angles to the velocity. Because it is perpendicular to the motion it does no work, so the speed stays constant. Mark scheme (1 mark). B1: A (The resultant force on it is perpendicular to its velocity).', 1),
('aea1581b-1f3a-5782-943d-a66f3177b599', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 13, 13, 'Why does the centripetal force on a body in uniform circular motion do no work on it?', NULL, 1, 'multiple_choice'::answer_type, 'The force is always perpendicular to the direction of motion', NULL, false, NULL, false, NULL, 'Work = Fs cos θ and θ = 90° between the force and the displacement at every instant, so no work is done and the kinetic energy (and speed) stays constant. Mark scheme (1 mark). B1: D (The force is always perpendicular to the direction of motion).', 1),
('519dbc79-b339-5ce8-9ab8-5b8ba72b31ec', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 14, 14, 'Sparks fly off a grinding wheel that spins at constant speed. In which direction does each spark leave the wheel?', NULL, 1, 'multiple_choice'::answer_type, 'Along the tangent to the rim at the point where it leaves', NULL, false, NULL, false, NULL, 'A spark that breaks free has no centripetal force on it, so it carries on with the velocity it had: along the tangent. Mark scheme (1 mark). B1: B (Along the tangent to the rim at the point where it leaves).', 1),
('124606f8-eb07-5942-9ade-f509d3fc41b2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 15, 15, 'A ball on a string moves in a horizontal circle at a constant speed of 6.0 m s⁻¹. Calculate the magnitude of its change in velocity between two points on opposite sides of the circle.', NULL, 1, 'numeric'::answer_type, '12', 'm s⁻¹', false, NULL, false, NULL, 'Half a revolution apart, the velocities are equal in size and opposite in direction. Δv = v − (−v) = 2v = 2 × 6.0 = 12 m s⁻¹. Mark scheme (2 marks). C1: velocities are opposite in direction. A1: Δv = 12 m s⁻¹. Common mistake: answering zero because the speed is unchanged.', 2),
('a0d9050b-d3c5-579e-b2f5-37673bc8f20b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 16, 16, 'A model aeroplane flies in a circle on a control line at a steady 8.0 m s⁻¹. What is the size of its change in velocity during a quarter of a lap?', NULL, 1, 'numeric'::answer_type, '11.31', 'm s⁻¹', false, 0.05, false, NULL, 'After a quarter turn the velocity has turned through 90°. The two velocity vectors are at right angles, so |Δv| = √(8.0² + 8.0²) = 11 m s⁻¹. Mark scheme (2 marks). C1: velocities at 90°, so use Pythagoras. A1: |Δv| = 11 m s⁻¹.', 2),
('1bfe75bf-9c34-5dda-a280-5d04c522acc5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 17, 17, 'A cyclist rides round a circular track of radius 30 m at a steady 12 m s⁻¹. Calculate the time for one lap.', NULL, 1, 'numeric'::answer_type, '15.71', 's', false, 0.05, false, NULL, 'One lap is 2πr. T = 2πr/v = 2π × 30 ÷ 12 = 16 s. Mark scheme (2 marks). C1: distance = 2πr. A1: T = 16 s.', 2),
('e3779ea2-66e8-569f-a932-849743dcc162', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 18, 18, 'The International Space Station moves at about 7.7 km s⁻¹ and completes an orbit in 92 minutes. Estimate the radius of its orbit.', NULL, 1, 'numeric'::answer_type, '6.765e6', 'm', false, NULL, false, NULL, 'v = 2πr/T, so r = vT/2π = 7700 × 5520 ÷ 2π = 6.76 × 10⁶ m. Mark scheme (2 marks). C1: v = 2πr/T with SI units. A1: r = 6.76 × 10⁶ m.', 2),
('0dda69d3-00fe-50c2-b2e3-067ae46463f3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 19, 19, 'A toy train goes round a circular track of radius 0.20 m once every 1.5 s. Calculate its speed.', NULL, 1, 'numeric'::answer_type, '0.8378', 'm s⁻¹', false, NULL, false, NULL, 'v = 2πr/T = 2π × 0.20 ÷ 1.5 = 0.84 m s⁻¹. Mark scheme (2 marks). C1: v = 2πr/T. A1: v = 0.84 m s⁻¹.', 2),
('fc02bf80-8543-513f-b03c-edce9401222d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 20, 20, 'A body moves in a circle at a constant speed. Through what angle does its velocity turn while it travels half way round?', NULL, 1, 'multiple_choice'::answer_type, '180°', NULL, false, NULL, false, NULL, 'The velocity is always along the tangent, so it turns through the same angle as the radius: half a revolution, 180°. Mark scheme (1 mark). B1: C (180°).', 1),
('41ee3243-b08b-53f8-a32b-03a2e0e8acdf', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 21, 21, 'Which describes the motion of a satellite in a circular orbit?', NULL, 1, 'multiple_choice'::answer_type, 'Constant speed, changing velocity', NULL, false, NULL, false, NULL, 'In a circular orbit the speed is constant, but the direction changes all the time, so the velocity changes. Mark scheme (1 mark). B1: A (Constant speed, changing velocity).', 1),
('e7f4df70-7cd2-5534-b2e2-bb871d3ed4d4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 22, 22, 'A child on a roundabout moves at a steady 3.0 m s⁻¹. Calculate the size of the change in velocity when the child has moved through 60° around the centre.', NULL, 1, 'numeric'::answer_type, '3', 'm s⁻¹', false, NULL, false, NULL, 'The velocity turns through 60°. Two sides of length 3.0 with 60° between them form an equilateral triangle, so |Δv| = 2 × 3.0 × sin 30 = 3.0 m s⁻¹. Mark scheme (2 marks). C1: vector triangle with 60° between the velocities. A1: |Δv| = 3.0 m s⁻¹.', 2),
('8d81711c-9575-5eca-a3cd-3d60e86492bd', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 23, 23, 'A racing car drives round a circular track at 20 m s⁻¹. Calculate the magnitude of its change in velocity as it moves round an arc that subtends 120° at the centre of the track.', NULL, 2, 'numeric'::answer_type, '34.64', 'm s⁻¹', false, NULL, false, NULL, 'The velocity turns through 120°. The vector triangle has two sides of 20 m s⁻¹, so |Δv| = 2v sin(θ/2) = 2 × 20 × sin 60 = 34.6 m s⁻¹. Mark scheme (3 marks). C1: velocity turns through the same angle as the radius. C1: vector triangle: |Δv| = 2v sin(θ/2) or cosine rule. A1: |Δv| = 34.6 m s⁻¹. Common mistake: subtracting the speeds and getting zero.', 3),
('e79dbec1-e312-5e26-87d4-aa86a234b6d7', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 24, 24, 'A fairground horse on a carousel moves at 2.4 m s⁻¹. By how much does its velocity change while it turns through 30° about the axis?', NULL, 2, 'numeric'::answer_type, '1.242', 'm s⁻¹', false, NULL, false, NULL, '|Δv| = 2v sin(θ/2) = 2 × 2.4 × sin 15 = 1.24 m s⁻¹. (The cosine rule, √(2.4² + 2.4² − 2 × 2.4 × 2.4 × cos 30), gives the same.). Mark scheme (3 marks). C1: angle between velocities = 30°. C1: vector triangle. A1: |Δv| = 1.24 m s⁻¹.', 3),
('d7b5336a-8c7c-50d6-9dab-74f055f141a5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 25, 25, 'A skater glides at a steady 4.0 m s⁻¹ round a circle of radius 2.0 m. (a) Find the time to travel a quarter of the circle. (b) Calculate the magnitude of the average acceleration over that quarter circle. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '7.203', 'm s⁻²', false, NULL, false, NULL, '(a) T = 2πr/v = 2π × 2.0 ÷ 4.0 = 3.14 s, so a quarter takes 0.785 s. (b) |Δv| = √2 × 4.0 = 5.66 m s⁻¹, average acceleration = 5.66 ÷ 0.785 = 7.20 m s⁻². (The instantaneous value v²/r = 8.0 m s⁻² is close.). Mark scheme (4 marks). C1: time for quarter = T/4. C1: |Δv| = √2 v. C1: average a = Δv/Δt. A1: a = 7.20 m s⁻². Common mistake: using the change in speed (zero) instead of the change in velocity.', 4),
('37898cc7-d4dd-56c2-85b2-191d9126c730', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 26, 26, 'A ball on a string moves anticlockwise in a horizontal circle, viewed from above. At the moment it is due north of the centre it is moving west. In which direction is the change in its velocity over a very short time at that moment?', NULL, 2, 'multiple_choice'::answer_type, 'South', NULL, false, NULL, false, NULL, 'The change in velocity points in the direction of the acceleration, which is towards the centre: the ball is due north of the centre, so the centre is due south of the ball. Mark scheme (3 marks). C1: change in velocity is in the direction of the acceleration. C1: acceleration is towards the centre. A1: D (South).', 3),
('2dc23296-9506-505f-bba1-77b048dd0fa2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 27, 27, 'A body moves round a circle at constant speed. Which pair of graphs would be correct for one revolution?', NULL, 2, 'multiple_choice'::answer_type, 'Speed–time graph a horizontal line; magnitude of acceleration–time graph a horizontal line', NULL, false, NULL, false, NULL, 'The speed is constant, so its graph is horizontal. The acceleration has constant magnitude v²/r (only its direction rotates), so its magnitude also gives a horizontal line. It is not zero. Mark scheme (3 marks). C1: speed constant. C1: acceleration constant in magnitude, changing in direction. A1: B (Speed–time graph a horizontal line; magnitude of acceleration–time graph a horizontal line).', 3),
('e152be49-57fc-596d-b066-45d043195b31', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 28, 28, 'A 0.40 kg ball moves round a horizontal circle at 9.0 m s⁻¹. Calculate the magnitude of the change in its momentum over a quarter of a revolution.', NULL, 2, 'numeric'::answer_type, '5.091', 'kg m s⁻¹', false, NULL, false, NULL, '|Δv| = √2 × 9.0 = 12.7 m s⁻¹. |Δp| = m|Δv| = 0.40 × 12.7 = 5.09 kg m s⁻¹. Mark scheme (3 marks). C1: momentum is a vector, velocity changes direction. C1: |Δv| from vector triangle. A1: |Δp| = 5.09 kg m s⁻¹. Common mistake: concluding that momentum does not change because the speed is constant.', 3),
('a36cc31b-ecb4-59d4-83a0-b31913f7e30d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 29, 29, 'A 1.2 kg hammer head is swung round in a circle at a steady 14 m s⁻¹. What is the size of the change in its momentum between one instant and half a revolution later?', NULL, 2, 'numeric'::answer_type, '33.6', 'kg m s⁻¹', false, NULL, false, NULL, 'Half a turn later the velocity is reversed: |Δv| = 2 × 14 = 28 m s⁻¹. |Δp| = 1.2 × 28 = 33.6 kg m s⁻¹. Mark scheme (3 marks). C1: velocity reversed after half a turn. C1: Δp = mΔv. A1: |Δp| = 33.6 kg m s⁻¹.', 3),
('e71a5cee-b638-5c01-a386-ce4475f2c779', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 30, 30, 'A bead slides at a steady 0.60 m s⁻¹ round a circular wire, completing a lap every 0.80 s. Calculate (a) its angular speed and (b) the radius of the wire loop. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '0.07639', 'm', false, NULL, false, NULL, '(a) ω = 2π/T = 2π ÷ 0.80 = 7.85 rad s⁻¹. (b) r = v/ω = 0.60 ÷ 7.854 = 0.0764 m. Mark scheme (3 marks). C1: ω = 2π/T. C1: v = ωr rearranged. A1: r = 0.0764 m.', 3),
('761f6d5b-d682-5c2f-b171-51063fe641ef', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 31, 31, 'An aircraft circles an airport at a steady 25 m s⁻¹, taking 18 s for each complete circle. Calculate the radius of its circle and the angle its velocity turns through each second, in degrees. Give the radius.', NULL, 2, 'numeric'::answer_type, '71.62', 'm', false, NULL, false, NULL, 'r = vT/2π = 25 × 18 ÷ 2π = 71.6 m. The velocity turns through 360° every 18 s, i.e. 20° each second. Mark scheme (3 marks). C1: v = 2πr/T. C1: angle per second. A1: r = 71.6 m.', 3),
('3b9fdf12-9c31-52f4-a6d7-0d9300e97f90', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 32, 32, 'A satellite moves in a circular orbit at constant speed. A student says: "The satellite has no acceleration because no work is done on it." Which is the best response?', NULL, 2, 'multiple_choice'::answer_type, 'Work is zero because the force is perpendicular to the velocity, but the force still changes the direction of the velocity, so there is an acceleration', NULL, false, NULL, false, NULL, 'No work is done because the gravitational force is at 90° to the motion, so the speed (and kinetic energy) is constant. A force perpendicular to the velocity still changes its direction, so the velocity changes and the satellite accelerates towards the Earth. Mark scheme (3 marks). C1: force perpendicular to velocity does no work. C1: but changes the direction of velocity, so acceleration. A1: C (Work is zero because the force is perpendicular to the velocity, but the force still changes the direction of the velocity, so there is an acceleration).', 3),
('99ec93a2-0245-5a86-883d-b27b950d3869', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 33, 33, 'An object moves round a circle at a steady speed. Its speed is then doubled while the radius stays the same. What happens to the size of the change in velocity over a quarter of a revolution, and to the time taken for that quarter?', NULL, 2, 'multiple_choice'::answer_type, 'Change in velocity doubles; time halves', NULL, false, NULL, false, NULL, '|Δv| = √2 v, so it doubles when v doubles. The quarter circle has the same length, so the time halves. (The average acceleration |Δv|/t therefore rises by a factor of 4, matching a = v²/r.). Mark scheme (3 marks). C1: |Δv| ∝ v. C1: t ∝ 1/v. A1: A (Change in velocity doubles; time halves).', 3),
('17dd2f71-6580-5f5b-be36-774843f451d5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 34, 34, 'A conker on a string moves round a circle of diameter 0.90 m at a steady 3.0 m s⁻¹. (a) Calculate the time to go halfway round. (b) Calculate the average acceleration of the conker over this half circle. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '12.73', 'm s⁻²', false, NULL, false, NULL, '(a) half the circumference = πr = π × 0.45 = 1.41 m, so t = 1.41 ÷ 3.0 = 0.471 s. (b) |Δv| = 2v = 6.0 m s⁻¹, average acceleration = 6.0 ÷ 0.471 = 12.7 m s⁻². Mark scheme (4 marks). C1: half circumference = πr with r = d/2. C1: Δv = 2v for half a revolution. C1: average a = Δv/t. A1: a = 12.7 m s⁻².', 4),
('d4c7a604-7218-59c9-b12a-7eb248d4682b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 35, 35, 'A toy car runs round a circular track at a steady speed. It is moved to a track of half the radius and runs at the same speed. What happens to the angle its velocity turns through each second?', NULL, 2, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'The velocity turns at the same rate as the radius: the angular speed ω = v/r. With v the same and r halved, ω doubles. Mark scheme (3 marks). C1: velocity turns at the rate ω. C1: ω = v/r. A1: D (It doubles).', 3),
('b95b4ff7-7f69-5e09-9e04-bdc518a7fe9e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 36, 36, 'Which of the following is NOT an example of a body moving with constant speed but changing velocity?', NULL, 2, 'multiple_choice'::answer_type, 'A ball rolling at a steady speed along a straight, level corridor', NULL, false, NULL, false, NULL, 'In a straight line at steady speed both the speed and direction are constant, so the velocity is constant. The other three all change direction. Mark scheme (3 marks). C1: velocity changes if direction changes. C1: identifies the straight-line motion. A1: B (A ball rolling at a steady speed along a straight, level corridor).', 3),
('51c202ff-0535-54e8-a85b-9a5761f789f0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 37, 37, 'A car is driving round a circular bend at a steady 15 m s⁻¹. At one instant it is heading due east. 3.0 s later it is heading 40° north of east. Calculate the magnitude of the average acceleration over these 3.0 s.', NULL, 2, 'numeric'::answer_type, '3.42', 'm s⁻²', false, NULL, false, NULL, '|Δv| = 2v sin(θ/2) = 2 × 15 × sin 20 = 10.3 m s⁻¹. Average acceleration = 10.3 ÷ 3.0 = 3.42 m s⁻². Mark scheme (4 marks). C1: angle between velocities 40°. C1: |Δv| from vector triangle. C1: a = Δv/Δt. A1: a = 3.42 m s⁻².', 4),
('88bf03b3-8e11-59e5-b73d-d855ee0f13f0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 38, 38, 'A ladybird walks at a steady 0.35 m s⁻¹ round the rim of a jar lid of radius 0.12 m. (a) How long does one lap take? (b) Through what angle does its velocity turn in 1.0 s? Give only the angle in (b), in radians.', NULL, 2, 'numeric'::answer_type, '2.917', 'rad', false, NULL, false, NULL, '(a) T = 2πr/v = 2π × 0.12 ÷ 0.35 = 2.15 s. (b) The velocity turns at the angular speed ω = v/r = 0.35 ÷ 0.12 = 2.92 rad s⁻¹, so in 1.0 s it turns 2.92 rad. Mark scheme (3 marks). C1: T = 2πr/v. C1: velocity turns at the rate ω = v/r. A1: angle = 2.92 rad.', 3),
('e7cb4148-cdb7-504f-a055-c262b0e1b80d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 39, 39, 'Two cars go round the same roundabout at the same constant speed, one on the inner lane and one on the outer lane. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The inner car''s velocity changes direction faster, so it has the larger acceleration', NULL, false, NULL, false, NULL, 'a = v²/r. With equal v, the smaller radius gives the larger acceleration: the inner car''s direction turns through more angle each second (ω = v/r is larger). Mark scheme (3 marks). C1: a = v²/r with v the same. C1: smaller r gives larger a. A1: C (The inner car''s velocity changes direction faster, so it has the larger acceleration).', 3),
('1d06572c-8bc0-5310-a233-d1c23e64f7fd', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 40, 40, 'An airliner in a holding pattern flies at a steady 150 m s⁻¹ round a circle. It turns from heading north to heading east in 50 s. (a) Calculate the size of the change in velocity. (b) Calculate the average acceleration. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '4.243', 'm s⁻²', false, NULL, false, NULL, '(a) The heading turns through 90°, so |Δv| = √(150² + 150²) = 212 m s⁻¹. (b) average a = 212 ÷ 50 = 4.24 m s⁻². Mark scheme (4 marks). C1: velocities at 90°. C1: |Δv| by Pythagoras. C1: a = Δv/Δt. A1: a = 4.24 m s⁻².', 4),
('c9d5296c-18ce-5d9b-86c1-da9762a59d2d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 41, 41, 'A ball of mass 0.20 kg moves in a horizontal circle of radius 1.5 m at a constant speed of 6.0 m s⁻¹. (a) Calculate the period. (b) Find the magnitude of the change in velocity as it moves through 60° round the circle. (c) Calculate the average acceleration over this 60° arc and compare it with v²/r. Give only the average acceleration in (c).', NULL, 3, 'numeric'::answer_type, '22.92', 'm s⁻²', false, NULL, false, NULL, '(a) T = 2πr/v = 2π × 1.5 ÷ 6.0 = 1.57 s. (b) The velocity turns through 60°: |Δv| = 2v sin 30° = 6.0 m s⁻¹ (an equilateral vector triangle). (c) The arc takes T/6 = 0.262 s, so average a = 6.0 ÷ 0.262 = 22.9 m s⁻². v²/r = 24 m s⁻²: the average over a finite arc is a little smaller and approaches v²/r as the arc shrinks. Mark scheme (5 marks). C1: T = 2πr/v. C1: |Δv| = 2v sin 30° = v. C1: time for 60° = T/6. A1: a = 22.9 m s⁻². B1: comparison with v²/r.', 5),
('2687d83f-31d2-5524-9b9f-e6339d2f7cb5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 42, 42, 'A puck on frictionless ice is tied by a string to a pin and moves in a circle of radius 2.0 m at 3.0 m s⁻¹. The string breaks when the puck is due east of the pin and moving north. (a) State the direction of the velocity just after the string breaks. (b) Describe the path of the puck afterwards. (c) Calculate how far the puck is from the pin 2.0 s after the string breaks. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '6.325', 'm', false, NULL, false, NULL, '(a) North, along the tangent. (b) A straight line at constant speed (no horizontal force on frictionless ice). (c) In 2.0 s it moves 3.0 × 2.0 = 6.0 m north from a point 2.0 m east of the pin. Distance = √(2.0² + 6.0²) = 6.32 m. Mark scheme (6 marks). B1: north / along the tangent. B1: straight line. B1: constant speed. C1: displacement 6.0 m along the tangent. C1: Pythagoras with the radius. A1: 6.3 m. Common mistake: expecting the puck to fly radially outwards.', 6),
('fc6c8af9-2f53-54f9-81b4-d6a29308381b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 43, 43, 'A point on a spinning disc moves at a steady 2.0 m s⁻¹ in a circle of radius 0.50 m. (a) Calculate the angle, in radians, through which its velocity turns in a time interval of 0.010 s. (b) Use the vector triangle to calculate the magnitude of the change in velocity in this interval. (c) Hence estimate the acceleration and show that it is close to v²/r. Give only your estimate in (c).', NULL, 3, 'numeric'::answer_type, '7.999', 'm s⁻²', false, NULL, false, NULL, '(a) The arc length is vΔt = 0.020 m, so θ = s/r = 0.020 ÷ 0.50 = 0.0400 rad. (b) |Δv| = 2v sin(θ/2) ≈ vθ = 2.0 × 0.0400 = 0.0800 m s⁻¹. (c) a ≈ |Δv|/Δt = 0.0800 ÷ 0.010 = 8.00 m s⁻², and v²/r = 8.0 m s⁻²: almost identical, because the interval is short. Mark scheme (6 marks). C1: θ = vΔt/r. A1: θ. C1: |Δv| = 2v sin(θ/2) or ≈ vθ. C1: a = Δv/Δt. A1: a = 8.00 m s⁻². B1: compares with v²/r.', 6),
('723127f6-ac9e-5ae3-98e6-068183b50236', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 44, 44, 'A motorcyclist rides round a circular test track of radius 40 m at a steady 16 m s⁻¹. A data logger records the velocity every 0.10 s. (a) Show that the velocity direction changes by 0.040 rad between readings. (b) Calculate the size of the change in velocity between readings. (c) Use your answer to estimate the motorcyclist''s acceleration, and state its direction. Give only the size of the acceleration in (c).', NULL, 3, 'numeric'::answer_type, '6.4', 'm s⁻²', false, NULL, false, NULL, '(a) θ = vΔt/r = 16 × 0.10 ÷ 40 = 0.040 rad. (b) |Δv| ≈ vθ = 16 × 0.040 = 0.640 m s⁻¹. (c) a ≈ 0.640 ÷ 0.10 = 6.40 m s⁻², towards the centre of the track (v²/r = 6.4 m s⁻²). Mark scheme (6 marks). M1: θ = vΔt/r. A1: 0.040 rad. C1: |Δv| ≈ vθ. C1: a = Δv/Δt. A1: a = 6.40 m s⁻². B1: towards the centre.', 6),
('c422e6f8-ea60-53a5-8e6a-c5ae25b393c4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 45, 45, 'A remote-controlled car drives anticlockwise round a circular track at a steady 10.0 m s⁻¹. At time t₁ it is moving due north. Later, at time t₂, it is moving north-west. (a) State the two velocities and the angle between them. (b) Calculate the magnitude of the change in velocity. (c) State the direction of the change in velocity. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '7.654', 'm s⁻¹', false, NULL, false, NULL, '(a) 10.0 m s⁻¹ north and 10.0 m s⁻¹ north-west: 45° apart. Δv = v₂ − v₁, the third side of an isosceles triangle. (b) |Δv| = 2v sin(θ/2) = 2 × 10.0 × sin 22.5 = 7.65 m s⁻¹. (c) Roughly west-south-west: towards the centre of the arc between the two positions. Mark scheme (5 marks). B1: angle between velocities 45°. C1: Δv = v₂ − v₁ as a vector. C1: 2v sin(θ/2) or cosine rule. A1: |Δv| = 7.65 m s⁻¹. B1: direction towards the centre.', 5),
('2179421b-2520-5b32-a65c-ff48d82b8d11', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 46, 46, 'A chair on a fairground ride moves at a steady 4.5 m s⁻¹ in a horizontal circle of radius 0.75 m. (a) Explain why the chair is accelerating. (b) Calculate its angular speed. (c) Calculate the number of revolutions it makes in 10 s. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '9.549', NULL, false, NULL, false, NULL, '(a) Its direction changes continuously, so its velocity changes: it accelerates towards the centre. (b) ω = v/r = 4.5 ÷ 0.75 = 6.00 rad s⁻¹. (c) T = 2π/ω = 1.05 s, number of revolutions = 10 ÷ 1.047 = 9.55. Mark scheme (5 marks). B1: velocity direction changes. B1: acceleration towards centre. C1: ω = v/r. C1: T = 2π/ω or n = ωt/2π. A1: n = 9.55.', 5),
('69ab4663-340a-5eb9-874d-cff0b833af0e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 47, 47, 'A particle moves anticlockwise round a circle of radius 0.50 m at a constant 2.0 m s⁻¹. Take the centre as origin. At t = 0 it is at (0.50 m, 0). (a) State its velocity components at t = 0. (b) Calculate the time it takes to reach (0, 0.50 m). (c) State its velocity components there. (d) Calculate the magnitude of the average acceleration between these two points. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '7.203', 'm s⁻²', false, NULL, false, NULL, '(a) vₓ = 0, v_y = +2.0 m s⁻¹. (b) A quarter circle: t = (π × 0.50 ÷ 2) ÷ 2.0 = 0.393 s. (c) vₓ = −2.0 m s⁻¹, v_y = 0. (d) Δv = (−2.0, −2.0), |Δv| = √(2.0² + 2.0²) = 2.83 m s⁻¹, average a = 2.83 ÷ 0.393 = 7.20 m s⁻². Mark scheme (6 marks). B1: (0, +2.0). C1: time for quarter circle. B1: (−2.0, 0). C1: Δv components. C1: average a = |Δv|/t. A1: a = 7.20 m s⁻².', 6),
('b012b83a-3d62-5b18-967b-8de46b2ea94b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 48, 48, 'A 0.10 kg ball on a string is whirled in a horizontal circle of radius 0.25 m, once every 0.50 s. (a) Calculate its speed. (b) Calculate its kinetic energy. (c) Explain why its kinetic energy stays constant but its momentum does not, and calculate the magnitude of the change in momentum over half a revolution. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.6283', 'kg m s⁻¹', false, NULL, false, NULL, '(a) v = 2πr/T = 2π × 0.25 ÷ 0.50 = 3.14 m s⁻¹. (b) Ek = ½mv² = 0.5 × 0.10 × 3.14² = 0.493 J. (c) Ek depends only on speed (a scalar); momentum is a vector and reverses direction after half a turn: |Δp| = 2mv = 2 × 0.10 × 3.14 = 0.628 kg m s⁻¹. Mark scheme (5 marks). C1: v = 2πr/T. A1: Ek. B1: Ek scalar, p vector. C1: Δp = 2mv. A1: |Δp| = 0.628 kg m s⁻¹.', 5),
('b4446dc9-619c-5630-bbff-bec64750c8d1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 49, 49, 'A small satellite moves in a circular orbit at 7.5 km s⁻¹. Ground controllers observe that its velocity direction changes by 1.2° every 15 s. (a) Calculate the angular speed of the satellite in rad s⁻¹. (b) Calculate the radius of its orbit. (c) Calculate its centripetal acceleration, and state its direction. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '5.371e6', 'm', false, NULL, false, NULL, '(a) ω = Δθ/Δt = (1.2 × π ÷ 180) ÷ 15 = 0.00140 rad s⁻¹. (b) r = v/ω = 7500 ÷ 0.001396 = 5.37 × 10⁶ m. (c) a = vω = 7500 × 0.001396 = 10.5 m s⁻², towards the Earth''s centre. Mark scheme (6 marks). C1: angle in radians. A1: ω. C1: r = v/ω. A1: r = 5.37 × 10⁶ m. B1: a = vω towards the centre. B1: direction.', 6),
('5d4f16a9-57ee-54d5-8126-a17917818975', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '2cb349de-a9e0-4b56-84d7-768b4df0ca9e', 'a-level', '16.3', '9702 coursebook 16.3 · Steady speed, changing velocity', 50, 50, 'A long-exposure photograph shows a light on a fairground arm tracing a circular arc of length 2.4 m during a 0.50 s exposure. The arm is 3.0 m long and rotates steadily. (a) Calculate the speed of the light. (b) Calculate the angle, in degrees, that its velocity turned through during the exposure. (c) Calculate the size of the change in velocity during the exposure. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.738', 'm s⁻¹', false, NULL, false, NULL, '(a) v = 2.4 ÷ 0.50 = 4.8 m s⁻¹. (b) θ = s/r = 2.4 ÷ 3.0 = 0.80 rad = 45.8°. (c) |Δv| = 2v sin(θ/2) = 2 × 4.8 × sin 22.9 = 3.74 m s⁻¹. Mark scheme (5 marks). C1: v = s/t. C1: θ = s/r. A1: θ in degrees. C1: |Δv| = 2v sin(θ/2). A1: |Δv| = 3.74 m s⁻¹.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('e3bcc037-f04f-5272-914c-98985dcaadca', 'c4ca3345-9cd1-51bc-ac82-c13237acb0f3', 'Its velocity', 'A', false, 0),
('55e96fb4-84e3-58e2-a9bb-b74d3da2e994', 'c4ca3345-9cd1-51bc-ac82-c13237acb0f3', 'Its momentum', 'B', false, 1),
('bc6b151a-dac2-54ba-b9a4-8afcaff75caa', 'c4ca3345-9cd1-51bc-ac82-c13237acb0f3', 'Its kinetic energy', 'C', true, 2),
('5550567f-aa4d-5264-974b-b13bc54323cb', 'c4ca3345-9cd1-51bc-ac82-c13237acb0f3', 'Its acceleration', 'D', false, 3),
('8dd2aae4-c21d-5f68-a2f6-d05cf2ecb178', 'be2c020b-194a-5255-9870-12a7b37712cd', 'Towards the centre of the circle', 'A', true, 0),
('d7645008-2936-577b-956a-b7cae5b6320e', 'be2c020b-194a-5255-9870-12a7b37712cd', 'Along the tangent, in the direction of motion', 'B', false, 1),
('f9034de1-c5aa-5dd0-a5f7-b19dde9e3855', 'be2c020b-194a-5255-9870-12a7b37712cd', 'Outwards, away from the centre', 'C', false, 2),
('5ecf11c7-6818-5fb5-9639-3e7f9fce1daf', 'be2c020b-194a-5255-9870-12a7b37712cd', 'Zero, because the speed is constant', 'D', false, 3),
('920a6bc3-e7fb-527d-91df-859d2c9a3d86', '1732e2fb-d6b0-54ae-91e5-8591ee5761e7', 'Towards the centre of the circle', 'A', false, 0),
('6230da49-af55-5b71-a2eb-698bb95f8cf7', '1732e2fb-d6b0-54ae-91e5-8591ee5761e7', 'Away from the centre of the circle', 'B', false, 1),
('f35c794d-52cd-5e58-a2c6-881c0e6c5bc4', '1732e2fb-d6b0-54ae-91e5-8591ee5761e7', 'Along the radius, in the direction of rotation', 'C', false, 2),
('16af9560-c75e-5f11-a5b3-27e681302ec6', '1732e2fb-d6b0-54ae-91e5-8591ee5761e7', 'Along the tangent to the circle', 'D', true, 3),
('91cd2279-65e5-59d6-bb19-7b26478192ec', 'cdecc92d-0325-5533-858b-763a07b07f4f', 'The car is not accelerating because its speed is constant', 'A', false, 0),
('31972c75-2dc6-5e83-9136-f0be54db0d8e', 'cdecc92d-0325-5533-858b-763a07b07f4f', 'The car is accelerating because its direction of motion is changing', 'B', true, 1),
('ac877078-449a-5e01-8f79-589c815e08b9', 'cdecc92d-0325-5533-858b-763a07b07f4f', 'The car is accelerating because its speed is increasing', 'C', false, 2),
('1ca708d5-798a-5ad1-8638-3699806efbea', 'cdecc92d-0325-5533-858b-763a07b07f4f', 'The car is in equilibrium because the forces on it balance', 'D', false, 3),
('783a1589-da30-596a-b0e4-cd860e36f5bc', 'f76ce2bd-81d5-5335-a1e2-00cd8221490b', 'In a straight line directly away from the centre', 'A', false, 0),
('24a45876-37ca-5b31-8fdf-41e3285fdf96', 'f76ce2bd-81d5-5335-a1e2-00cd8221490b', 'In a curved path of larger radius', 'B', false, 1),
('701e9a10-9fdb-5b8f-869a-2f89ca87d36c', 'f76ce2bd-81d5-5335-a1e2-00cd8221490b', 'In a straight line along the tangent at the point where the string broke', 'C', true, 2),
('d2c4a8cc-e097-5a58-8f86-8b8dc8a6e3f2', 'f76ce2bd-81d5-5335-a1e2-00cd8221490b', 'In a straight line towards the centre', 'D', false, 3),
('115d7e82-44f9-53da-a4c2-a4cfcc3707a5', '2b6927ed-d7e8-58e2-bc1a-b1b2570533e0', 'The resultant force on it is perpendicular to its velocity', 'A', true, 0),
('ea304d3e-eaed-500a-970b-ab03e6352416', '2b6927ed-d7e8-58e2-bc1a-b1b2570533e0', 'The resultant force on it is in the direction of its velocity', 'B', false, 1),
('adada8ed-f2b8-56c2-8b3f-76bd21528460', '2b6927ed-d7e8-58e2-bc1a-b1b2570533e0', 'The resultant force on it is zero', 'C', false, 2),
('c575e06c-b122-5d2d-abb0-a7487dae1e26', '2b6927ed-d7e8-58e2-bc1a-b1b2570533e0', 'The resultant force on it points away from the centre', 'D', false, 3),
('f8a0a584-23d3-5091-bf5a-e6114c4749f6', 'aea1581b-1f3a-5782-943d-a66f3177b599', 'The force is too small to do work', 'A', false, 0),
('00dab66c-7c5c-5df5-96a8-ca9e52686233', 'aea1581b-1f3a-5782-943d-a66f3177b599', 'The body returns to its starting point after each revolution', 'B', false, 1),
('04c35c62-175c-50ba-babf-9c5f8bda591c', 'aea1581b-1f3a-5782-943d-a66f3177b599', 'The force is balanced by an outward centrifugal force', 'C', false, 2),
('fc45f898-6a75-56d3-a182-82dd0832c767', 'aea1581b-1f3a-5782-943d-a66f3177b599', 'The force is always perpendicular to the direction of motion', 'D', true, 3),
('27184b37-6cd3-5a0d-9a1a-618fdd1a7716', '519dbc79-b339-5ce8-9ab8-5b8ba72b31ec', 'Radially outwards from the centre', 'A', false, 0),
('cf75262e-2d8d-53c6-91a8-d5197d901322', '519dbc79-b339-5ce8-9ab8-5b8ba72b31ec', 'Along the tangent to the rim at the point where it leaves', 'B', true, 1),
('b33c122c-5e98-59f0-bb66-8ffd0953ae31', '519dbc79-b339-5ce8-9ab8-5b8ba72b31ec', 'Towards the centre of the wheel', 'C', false, 2),
