('103fe527-3f5e-57df-8fc1-c8279db562f2', '2dc23296-9506-505f-bba1-77b048dd0fa2', 'Speed–time graph a horizontal line; magnitude of acceleration–time graph a sine curve', 'D', false, 3),
('c678dd34-ff15-5fea-a7b4-fbf072d43b2b', '3b9fdf12-9c31-52f4-a6d7-0d9300e97f90', 'The student is correct: no work means no change in velocity', 'A', false, 0),
('14549fa5-8cac-5b59-8188-677fce7be06d', '3b9fdf12-9c31-52f4-a6d7-0d9300e97f90', 'Work is done on the satellite, so its speed must change', 'B', false, 1),
('da721a0b-edd8-5717-bf88-4520d78fe23f', '3b9fdf12-9c31-52f4-a6d7-0d9300e97f90', 'Work is zero because the force is perpendicular to the velocity, but the force still changes the direction of the velocity, so there is an acceleration', 'C', true, 2),
('2a48e4d9-1e22-5310-9db0-51b53670e7ce', '3b9fdf12-9c31-52f4-a6d7-0d9300e97f90', 'There is no force on the satellite, so it has no acceleration', 'D', false, 3),
('0d5ba104-f569-58f5-b98b-e00d6b13290d', '99ec93a2-0245-5a86-883d-b27b950d3869', 'Change in velocity doubles; time halves', 'A', true, 0),
('c22f9f0c-7859-5b3a-b618-f8432d45508e', '99ec93a2-0245-5a86-883d-b27b950d3869', 'Change in velocity doubles; time doubles', 'B', false, 1),
('a35627c5-f2c1-51b2-b184-e74b31ff3221', '99ec93a2-0245-5a86-883d-b27b950d3869', 'Change in velocity is unchanged; time halves', 'C', false, 2),
('aed9c0db-5b6e-5b62-a53d-3b9177641af5', '99ec93a2-0245-5a86-883d-b27b950d3869', 'Change in velocity quadruples; time is unchanged', 'D', false, 3),
('cf2f2889-de58-52a8-8745-cc21997ff138', 'd4c7a604-7218-59c9-b12a-7eb248d4682b', 'It halves', 'A', false, 0),
('4176bf7a-eed4-5656-8e49-dd68227587af', 'd4c7a604-7218-59c9-b12a-7eb248d4682b', 'It stays the same', 'B', false, 1),
('5539775e-0161-5996-884f-708982d6d480', 'd4c7a604-7218-59c9-b12a-7eb248d4682b', 'It quadruples', 'C', false, 2),
('71fa262c-bf21-5d4c-9e37-92015b136e04', 'd4c7a604-7218-59c9-b12a-7eb248d4682b', 'It doubles', 'D', true, 3),
('47f250dc-b7d9-54f7-99f4-bdb33c07352a', 'b95b4ff7-7f69-5e09-9e04-bdc518a7fe9e', 'A point on the rim of a spinning bicycle wheel', 'A', false, 0),
('da91bf92-5de1-5f0e-9651-f1309a2cba36', 'b95b4ff7-7f69-5e09-9e04-bdc518a7fe9e', 'A ball rolling at a steady speed along a straight, level corridor', 'B', true, 1),
('85b8d41c-4064-5e71-85a4-38776f747973', 'b95b4ff7-7f69-5e09-9e04-bdc518a7fe9e', 'A geostationary satellite', 'C', false, 2),
('2ae7f8f6-40f4-5684-baa4-7b1c145bf86a', 'b95b4ff7-7f69-5e09-9e04-bdc518a7fe9e', 'A car going round a roundabout at a steady 10 m s⁻¹', 'D', false, 3),
('ce2baf63-d164-51ad-a51f-e6a1e2485968', 'e7cb4148-cdb7-504f-a055-c262b0e1b80d', 'Both have the same acceleration because their speeds are equal', 'A', false, 0),
('3a770a65-cc38-5149-a5c4-2c78c6a0ea18', 'e7cb4148-cdb7-504f-a055-c262b0e1b80d', 'The outer car has the larger acceleration because it travels further', 'B', false, 1),
('fe9ed31c-d782-57cf-bf10-edc62272e42f', 'e7cb4148-cdb7-504f-a055-c262b0e1b80d', 'The inner car''s velocity changes direction faster, so it has the larger acceleration', 'C', true, 2),
('81ec7f35-8ddf-5502-bed0-74a554248578', 'e7cb4148-cdb7-504f-a055-c262b0e1b80d', 'Neither car accelerates because the speeds are constant', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('5aec6f8c-761f-5813-bf10-7cb873611c72', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 9, 9, 'The Moon goes round the Earth once every 27.3 days. Calculate its angular speed.', NULL, 1, 'numeric'::answer_type, '2.664e-6', 'rad s⁻¹', false, NULL, false, NULL, 'T = 27.3 × 86400 = 2.36 × 10⁶ s. ω = 2π/T = 2π ÷ 2.36 × 10⁶ = 2.66 × 10⁻⁶ rad s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T in seconds. A1: ω = 2.66 × 10⁻⁶ rad s⁻¹.', 2),
('f8f37b37-76e7-56b4-81ef-e1f81a5972c7', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 10, 10, 'Calculate the angular speed of the second hand of a watch.', NULL, 1, 'numeric'::answer_type, '0.1047', 'rad s⁻¹', false, NULL, false, NULL, 'T = 60 s, so ω = 2π/T = 2π ÷ 60 = 0.105 rad s⁻¹. Mark scheme (1 mark). A1: ω = 0.105 rad s⁻¹.', 1),
('0021bd4d-ca25-5cf8-ba0b-b17abeadcaf9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 11, 11, 'A spinning top completes one turn every 0.050 s. What is its angular speed?', NULL, 1, 'numeric'::answer_type, '125.7', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.050 = 126 rad s⁻¹. Mark scheme (1 mark). A1: ω = 126 rad s⁻¹.', 1),
('e4747e21-fe65-526d-8dbe-2cb523cea339', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 12, 12, 'The rotor of an electricity generator turns at 50 Hz. Calculate its angular speed.', NULL, 1, 'numeric'::answer_type, '314.2', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 50 = 314 rad s⁻¹. Mark scheme (1 mark). A1: ω = 314 rad s⁻¹.', 1),
('37f3f721-7977-5803-9e4e-e035735c8a9f', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 13, 13, 'A propeller on a model boat rotates 3.5 times each second. Calculate its angular speed.', NULL, 1, 'numeric'::answer_type, '21.99', 'rad s⁻¹', false, NULL, false, NULL, 'f = 3.5 Hz, ω = 2πf = 2π × 3.5 = 22.0 rad s⁻¹. Mark scheme (1 mark). A1: ω = 22.0 rad s⁻¹.', 1),
('573e9cc0-c66d-5f53-add2-5da68f51c144', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 14, 14, 'A Ferris wheel turns with an angular speed of 0.26 rad s⁻¹. How long does one ride (one full turn) last?', NULL, 1, 'numeric'::answer_type, '24.17', 's', false, NULL, false, NULL, 'T = 2π/ω = 2π ÷ 0.26 = 24 s. Mark scheme (2 marks). C1: T = 2π/ω. A1: T = 24 s.', 2),
('34bb5d5f-a60c-5b8a-a273-dac83fa01512', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 15, 15, 'A grindstone of radius 0.25 m rotates at 8.0 rad s⁻¹. Calculate the speed of its rim.', NULL, 1, 'numeric'::answer_type, '2', 'm s⁻¹', false, NULL, false, NULL, 'v = ωr = 8.0 × 0.25 = 2.0 m s⁻¹. Mark scheme (1 mark). A1: v = 2.0 m s⁻¹.', 1),
('62f9fc82-2211-5cb5-bb33-b39e20c899ef', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 16, 16, 'The rim of a spinning wheel of radius 0.30 m moves at 1.8 m s⁻¹. Calculate the angular speed of the wheel.', NULL, 1, 'numeric'::answer_type, '6', 'rad s⁻¹', false, NULL, false, NULL, 'ω = v/r = 1.8 ÷ 0.30 = 6.00 rad s⁻¹. Mark scheme (2 marks). C1: v = ωr rearranged. A1: ω = 6.00 rad s⁻¹.', 2),
('08f1c2dc-bc15-5780-b70b-17a66991c134', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 17, 17, 'A train goes round a curve at 36 m s⁻¹, its direction changing at 0.12 rad s⁻¹. Calculate the radius of the curve.', NULL, 1, 'numeric'::answer_type, '300', 'm', false, NULL, false, NULL, 'r = v/ω = 36 ÷ 0.12 = 300 m. Mark scheme (2 marks). C1: r = v/ω. A1: r = 300 m.', 2),
('e94ce489-d2ea-5192-a4d1-da275b4bd9b5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 18, 18, 'Which equation relates the speed v of a point on a rotating body to the angular speed ω and the distance r from the axis?', NULL, 1, 'multiple_choice'::answer_type, 'v = ωr', NULL, false, NULL, false, NULL, 'In one revolution the point travels 2πr in a time T = 2π/ω, so v = 2πr ÷ (2π/ω) = ωr. Mark scheme (1 mark). B1: C (v = ωr).', 1),
('c6b6677e-d493-546c-a764-ce8bf14cbb10', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 19, 19, 'A disc rotates at a constant rate. Which quantity is the same for all points on the disc?', NULL, 1, 'multiple_choice'::answer_type, 'Angular speed', NULL, false, NULL, false, NULL, 'Every point turns through the same angle in the same time, so ω is the same. v = ωr and a = ω²r both depend on r. Mark scheme (1 mark). B1: A (Angular speed).', 1),
('501406c6-1fed-5f86-b650-495c32c79716', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 20, 20, 'A lighthouse lamp rotates at 0.50 Hz. Calculate its angular speed.', NULL, 1, 'numeric'::answer_type, '3.142', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 0.50 = 3.14 rad s⁻¹. (A ship sees one flash per revolution, every T = 1/f = 2.0 s.). Mark scheme (2 marks). C1: ω = 2πf. A1: ω = 3.14 rad s⁻¹.', 2),
('aa8e8fd0-81dd-5c39-9af0-8fed048612c4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 21, 21, 'What is the angular speed of the Earth spinning on its axis, to two significant figures?', NULL, 1, 'multiple_choice'::answer_type, '7.3 × 10⁻⁵ rad s⁻¹', NULL, false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 86400 s = 7.3 × 10⁻⁵ rad s⁻¹. 2.0 × 10⁻⁷ rad s⁻¹ is the Earth''s orbital angular speed round the Sun, and 0.26 rad is the angle turned per hour. Mark scheme (1 mark). B1: D (7.3 × 10⁻⁵ rad s⁻¹).', 1),
('b78a8cca-6a1f-5c6c-b72d-38e2faab0121', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 22, 22, 'An electric drill turns at 1500 rev min⁻¹. Calculate its angular speed.', NULL, 1, 'numeric'::answer_type, '157.1', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2π × 1500 ÷ 60 = 157 rad s⁻¹. Mark scheme (2 marks). C1: rev min⁻¹ to rad s⁻¹. A1: ω = 157 rad s⁻¹.', 2),
('419a9585-d543-561a-841c-6ac536487017', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 23, 23, 'The tip of a ceiling fan blade is 0.60 m from the axis and moves at 9.0 m s⁻¹. Calculate the fan''s angular speed.', NULL, 1, 'numeric'::answer_type, '15', 'rad s⁻¹', false, NULL, false, NULL, 'ω = v/r = 9.0 ÷ 0.60 = 15 rad s⁻¹. Mark scheme (2 marks). C1: ω = v/r. A1: ω = 15 rad s⁻¹.', 2),
('21f37847-ea6f-5ce6-8022-e6f277a07631', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 24, 24, 'A wheel turns at a frequency f. Which expression gives its angular speed?', NULL, 1, 'multiple_choice'::answer_type, '2πf', NULL, false, NULL, false, NULL, 'In each revolution the wheel turns through 2π rad and there are f revolutions per second, so ω = 2πf. Mark scheme (1 mark). B1: A (2πf).', 1),
('4731e690-c271-5647-9f08-84c8575fb43b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 25, 25, 'A small record of diameter 12 cm turns at 33 rev min⁻¹. Calculate the speed of a point on its edge.', NULL, 2, 'numeric'::answer_type, '0.2073', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2π × 33 ÷ 60 = 3.46 rad s⁻¹. r = 0.060 m. v = ωr = 3.46 × 0.060 = 0.207 m s⁻¹. Mark scheme (3 marks). C1: ω from rev min⁻¹. C1: r = d/2 in metres. A1: v = 0.207 m s⁻¹.', 3),
('6cc26789-b3ef-51e1-941e-3ff2ef157afb', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 26, 26, 'A record player''s 30 cm diameter platter is switched from 33 to 45 rev min⁻¹. Calculate the speed of the rim at 45 rev min⁻¹.', NULL, 2, 'numeric'::answer_type, '0.7069', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2π × 45 ÷ 60 = 4.71 rad s⁻¹. v = ωr = 4.71 × 0.15 = 0.707 m s⁻¹. Mark scheme (3 marks). C1: ω in rad s⁻¹. C1: radius 0.15 m. A1: v = 0.707 m s⁻¹.', 3),
('e18606f3-dcee-5bf0-8c47-1a9e30dc29f4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 27, 27, 'Two marks on a rotating disc lie on the same radius, at 2.0 cm and 8.0 cm from the axis. The disc spins at 30 rad s⁻¹. Calculate the difference in their speeds.', NULL, 2, 'numeric'::answer_type, '1.8', 'm s⁻¹', false, NULL, false, NULL, 'Both have the same ω. v₁ = ωr₁ = 30 × 0.020 = 0.600 m s⁻¹, v₂ = 30 × 0.080 = 2.40 m s⁻¹. Difference = 30 × 0.060 = 1.80 m s⁻¹. Mark scheme (3 marks). C1: same ω for both. C1: v = ωr for each. A1: Δv = 1.80 m s⁻¹.', 3),
('193a381e-4e3f-59ea-9fad-93c8b1889470', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 28, 28, 'Two children sit on a roundabout turning at 0.60 rad s⁻¹, one 1.5 m and one 4.5 m from the centre. Calculate the speed of each child and hence the factor by which the outer child is faster. Give the factor.', NULL, 2, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, 'v = ωr: inner 0.60 × 1.5 = 0.90 m s⁻¹, outer 0.60 × 4.5 = 2.7 m s⁻¹. Factor = 2.7 ÷ 0.90 = 3.0. Mark scheme (3 marks). C1: same ω for both children. C1: v = ωr for each. A1: factor = 3.0.', 3),
('55e27363-7569-5e08-9b31-00a4730e340f', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 29, 29, 'A low-orbit satellite travels at 7.66 km s⁻¹ with a period of 92.7 minutes. Calculate (a) its angular speed and (b) its orbital radius. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '6.781e6', 'm', false, NULL, false, NULL, '(a) T = 92.7 × 60 = 5560 s, ω = 2π ÷ 5560 = 0.00113 rad s⁻¹. (b) r = v/ω = 7660 ÷ 0.001130 = 6.78 × 10⁶ m. Mark scheme (3 marks). C1: ω = 2π/T with T in seconds. C1: r = v/ω. A1: r = 6.78 × 10⁶ m.', 3),
('14b9b830-90db-5195-83f6-6a3dfdff07aa', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 30, 30, 'A geostationary satellite moves at 3.07 km s⁻¹ and has the same angular speed as the rotating Earth (period 24.0 h). Calculate the radius of its orbit.', NULL, 2, 'numeric'::answer_type, '4.222e7', 'm', false, NULL, false, NULL, 'ω = 2π ÷ 86400 = 7.27 × 10⁻⁵ rad s⁻¹. r = v/ω = 3070 ÷ 7.272 × 10⁻⁵ = 4.22 × 10⁷ m. Mark scheme (3 marks). C1: ω for a 24 h period. C1: r = v/ω. A1: r = 4.22 × 10⁷ m.', 3),
('1cb03bbb-c008-5d98-9d00-76665a5675f8', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 31, 31, 'A rotating shaft turns through 18 rad in 4.0 s at a steady rate. Calculate its frequency of rotation.', NULL, 2, 'numeric'::answer_type, '0.7162', 'Hz', false, NULL, false, NULL, 'ω = θ/t = 18 ÷ 4.0 = 4.50 rad s⁻¹. f = ω/2π = 4.50 ÷ 2π = 0.716 Hz. Mark scheme (3 marks). C1: ω = θ/t. C1: f = ω/2π. A1: f = 0.716 Hz.', 3),
('a35d48e1-6abe-5630-aa45-0956bfb6fd30', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 32, 32, 'Wheel P has radius r and rotates at angular speed ω. Wheel Q has radius 2r and rotates at angular speed ω/4. What is the ratio (speed of rim of P)/(speed of rim of Q)?', NULL, 2, 'multiple_choice'::answer_type, '2', NULL, false, NULL, false, NULL, 'v_P = ωr. v_Q = (ω/4)(2r) = ωr/2. Ratio = ωr ÷ (ωr/2) = 2. Mark scheme (3 marks). C1: v = ωr for each wheel. C1: ratio calculated. A1: B (2). Common mistake: multiplying the factors the wrong way round and getting ½.', 3),
('5e2da1f0-3a2e-5ec5-8837-69b6fb19ce2a', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 33, 33, 'The Earth spins on its axis and also orbits the Sun. How does the angular speed of its spin compare with the angular speed of its orbit?', NULL, 2, 'multiple_choice'::answer_type, 'The spin is about 365 times faster', NULL, false, NULL, false, NULL, 'ω = 2π/T. Spin: T ≈ 1 day. Orbit: T ≈ 365 days. Ratio ω_spin/ω_orbit = 365 ÷ 1 ≈ 365. Mark scheme (3 marks). C1: ω ∝ 1/T. C1: periods 1 day and 365 days. A1: C (The spin is about 365 times faster).', 3),
('1af8fbec-3ede-55ac-8cb3-f712c3502bb4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 34, 34, 'A lawn sprinkler arm of length 0.40 m rotates at 2.5 Hz. Calculate the speed of the nozzle at the tip of the arm.', NULL, 2, 'numeric'::answer_type, '6.283', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 2.5 = 15.7 rad s⁻¹. v = ωr = 15.7 × 0.40 = 6.28 m s⁻¹. Mark scheme (3 marks). C1: ω = 2πf. C1: v = ωr. A1: v = 6.28 m s⁻¹.', 3),
('f1046d6a-5ca3-5efe-979c-313f937050a2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 35, 35, 'The cutting tip of a lawnmower blade moves at 44 m s⁻¹ when the blade spins at 700 rev min⁻¹. Calculate the distance from the axis to the tip.', NULL, 2, 'numeric'::answer_type, '0.6002', 'm', false, NULL, false, NULL, 'ω = 2π × 700 ÷ 60 = 73.3 rad s⁻¹. r = v/ω = 44 ÷ 73.30 = 0.600 m. Mark scheme (4 marks). C1: × 2π. C1: ÷ 60. C1: r = v/ω. A1: r = 0.600 m. Common mistake: forgetting the factor 2π when converting revolutions to radians.', 4),
('4cf08a0b-3e1f-5dba-9a85-a6dfe5a0bb7b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 36, 36, 'Two discs on the same axle start with their marks lined up. They rotate in the same direction at 40 rad s⁻¹ and 10 rad s⁻¹. How many more revolutions has the faster disc made after 6.0 s?', NULL, 2, 'numeric'::answer_type, '28.65', NULL, false, 0.02, false, NULL, 'Extra angle = (ω₁ − ω₂)t = (40 − 10) × 6.0 = 180 rad. Extra revolutions = 180 ÷ 2π = 28.6. Mark scheme (4 marks). C1: relative angular speed ω₁ − ω₂. C1: angle = ωt. C1: ÷ 2π. A1: extra revolutions = 28.6.', 4),
('940f2fce-b1f8-513b-9607-d3d7c84db8ce', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 37, 37, 'A bicycle travels at 6.0 m s⁻¹. Its wheels have radius 0.35 m. Calculate the angular speed of the wheels.', NULL, 2, 'numeric'::answer_type, '17.14', 'rad s⁻¹', false, NULL, false, NULL, 'For rolling without slipping the bicycle''s speed equals the speed of the rim relative to the axle: ω = v/r = 6.0 ÷ 0.35 = 17.1 rad s⁻¹. Mark scheme (3 marks). B1: rolling: v of bicycle = v of rim relative to axle. C1: ω = v/r. A1: ω = 17.1 rad s⁻¹.', 3),
('3b9f7410-9201-5f29-b3cb-9a0510196d69', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 38, 38, 'At exactly 12:00 the minute and second hands of a clock point the same way. Calculate the time, in seconds, until the second hand next overtakes the minute hand.', NULL, 2, 'numeric'::answer_type, '61.02', 's', false, NULL, false, NULL, 'ω_s = 2π/60, ω_m = 2π/3600. The second hand gains a full turn (2π) when (ω_s − ω_m)t = 2π, so t = 1 ÷ (1/60 − 1/3600) = 61.0 s. Mark scheme (4 marks). C1: angular speeds of both hands. C1: relative angular speed. C1: gain of 2π. A1: t = 61.0 s.', 4),
('23f37d52-9d76-5c78-b199-215e41f4895b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 39, 39, 'A centrifuge rotor 15 cm in radius reaches a rim speed of 110 m s⁻¹. Calculate its rotation rate in revolutions per second.', NULL, 2, 'numeric'::answer_type, '116.7', 'Hz', false, NULL, false, NULL, 'ω = v/r = 110 ÷ 0.15 = 733 rad s⁻¹. f = ω/2π = 733 ÷ 2π = 117 Hz. Mark scheme (3 marks). C1: ω = v/r with r in m. C1: f = ω/2π. A1: f = 117 Hz.', 3),
('8d02df64-fc19-5e61-b5b9-6bd7cf199147', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 40, 40, 'A 3.5-inch floppy disk drive (an old storage device) turned the disk at 300 rev min⁻¹. A read head 3.0 cm from the axis follows the track. Calculate the speed of the track under the head.', NULL, 2, 'numeric'::answer_type, '0.9425', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2π × 300 ÷ 60 = 31.4 rad s⁻¹. v = ωr = 31.4 × 0.030 = 0.942 m s⁻¹. Mark scheme (3 marks). C1: ω from rev min⁻¹. C1: v = ωr. A1: v = 0.942 m s⁻¹.', 3),
('3edb4992-5a2e-59f2-8903-69ecb38c9bf0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 41, 41, 'A satellite in a low orbit has period 90 min; a geostationary satellite has period 24 h. What is the ratio (angular speed of the low satellite)/(angular speed of the geostationary one)?', NULL, 2, 'multiple_choice'::answer_type, '16', NULL, false, NULL, false, NULL, 'ω = 2π/T, so the ratio = T_geo/T_low = (24 × 60) ÷ 90 = 16. Mark scheme (3 marks). C1: ω ∝ 1/T. C1: periods in the same unit. A1: D (16).', 3),
('4a0935d8-e68a-5920-9d9e-8a4892289e3a', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 42, 42, 'A cyclist rides at a steady 9.0 m s⁻¹. The bicycle wheels have diameter 0.66 m and roll without slipping. (a) Calculate the angular speed of a wheel. (b) Calculate the frequency of rotation of a wheel. (c) Calculate the time taken to ride 2.0 km and hence the number of revolutions each wheel makes. Give only the number of revolutions in (c).', NULL, 3, 'numeric'::answer_type, '964.6', NULL, false, NULL, false, NULL, '(a) r = 0.33 m, ω = v/r = 9.0 ÷ 0.33 = 27.3 rad s⁻¹. (b) f = ω/2π = 27.3 ÷ 2π = 4.34 Hz. (c) t = 2000 ÷ 9.0 = 222 s, revolutions = ft = 4.341 × 222.2 = 965. Mark scheme (6 marks). C1: r = d/2. A1: ω. A1: f = ω/2π. C1: t = s/v. C1: revolutions = ft (or s/2πr). A1: n = 965.', 6),
('18416b13-d62b-5e02-ac0b-281906189fe1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 43, 43, 'The Earth rotates once on its axis in 86 164 s (the sidereal day). Its radius is 6.37 × 10⁶ m. (a) Calculate the angular speed of the Earth. (b) Calculate the speed of a point on the Equator. (c) Calculate the speed of Oslo, at latitude 60° N, and explain why every point on the Earth has the same angular speed. Give only the speed in (c).', NULL, 3, 'numeric'::answer_type, '232.3', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π ÷ 86164 = 7.29 × 10⁻⁵ rad s⁻¹. (b) v = ωR = 7.29 × 10⁻⁵ × 6.37 × 10⁶ = 465 m s⁻¹. (c) r = R cos 60°, so v = 465 × cos 60 = 232 m s⁻¹. The Earth is rigid, so every point turns through 2π in the same time. Mark scheme (5 marks). A1: ω. C1: v = ωR. C1: r = R cos(latitude). A1: v = 232 m s⁻¹. B1: rigid body: same angle in the same time.', 5),
('49f38425-4bbb-57d5-ac1a-f2c161b330ca', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 44, 44, 'The Earth rotates once on its axis in 86 164 s (the sidereal day). Its radius is 6.37 × 10⁶ m. (a) Calculate the angular speed of the Earth. (b) Calculate the speed of a point on the Equator. (c) Calculate the speed of a town at latitude 20° S, and explain why every point on the Earth has the same angular speed. Give only the speed in (c).', NULL, 3, 'numeric'::answer_type, '436.5', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π ÷ 86164 = 7.29 × 10⁻⁵ rad s⁻¹. (b) v = ωR = 7.29 × 10⁻⁵ × 6.37 × 10⁶ = 465 m s⁻¹. (c) r = R cos 20°, so v = 465 × cos 20 = 436 m s⁻¹. The Earth is rigid, so every point turns through 2π in the same time. Mark scheme (5 marks). A1: ω. C1: v = ωR. C1: r = R cos(latitude). A1: v = 436 m s⁻¹. B1: rigid body: same angle in the same time.', 5),
('ae9f6c5c-1fc5-5148-a550-2c1e5ce0390b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 45, 45, 'The angle turned by a rotating shop sign is recorded: t = 0 s, θ = 0; t = 1.5 s, θ = 2.1 rad; t = 3.0 s, θ = 4.2 rad; t = 4.5 s, θ = 6.3 rad; t = 6.0 s, θ = 8.4 rad. (a) Show that the angular speed is constant. (b) Determine the angular speed. (c) Calculate the period. (d) Calculate the speed of the edge of the sign, 0.80 m from the axis. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '1.12', 'm s⁻¹', false, NULL, false, NULL, '(a) Each 1.5 s adds 2.1 rad, so θ ∝ t and ω is constant. (b) ω = 8.4 ÷ 6.0 = 1.40 rad s⁻¹. (c) T = 2π/ω = 2π ÷ 1.40 = 4.49 s. (d) v = ωr = 1.40 × 0.80 = 1.12 m s⁻¹. Mark scheme (6 marks). B1: equal Δθ in equal Δt. C1: gradient of θ against t. A1: ω. A1: T. C1: v = ωr. A1: v = 1.12 m s⁻¹.', 6),
('f0ba7223-abfa-504e-8989-4c383f29c5cb', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 46, 46, 'A motorway slip road curves through 90° as an arc of radius 150 m. A car takes it at a steady 22 m s⁻¹. (a) Calculate the angular speed of the car about the centre of the curve. (b) Calculate the time taken to go round the curve. (c) Calculate the length of the curve. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '10.71', 's', false, NULL, false, NULL, '(a) ω = v/r = 22 ÷ 150 = 0.147 rad s⁻¹. (b) 90° = π/2 rad, t = θ/ω = (π/2) ÷ 0.1467 = 10.7 s. (c) s = rθ = 150 × π/2 = 236 m (check: vt = 236 m). Mark scheme (5 marks). C1: ω = v/r. A1: ω. C1: θ = π/2 rad. A1: t = 10.7 s. B1: s = rθ.', 5),
('6cedd417-83d3-57c6-a25e-88001378c9b9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 47, 47, 'A geostationary satellite stays above the same point on the Equator. (a) State its period in seconds. (b) Calculate its angular speed. (c) Its orbital radius is 4.22 × 10⁷ m. Calculate its orbital speed. (d) Explain why its angular speed equals that of a person on the Equator, although their speeds are very different. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3077', 'm s⁻¹', false, NULL, false, NULL, '(a) One sidereal day, 86 164 s (≈ 24 h). (b) ω = 2π ÷ 86164 = 7.29 × 10⁻⁵ rad s⁻¹. (c) v = ωr = 7.29 × 10⁻⁵ × 4.22 × 10⁷ = 3080 m s⁻¹. (d) Both turn through 2π in the same time, so ω is equal. v = ωr and the satellite''s r is about 6.6 times larger, so it moves 6.6 times faster. Mark scheme (6 marks). B1: T = 24 h / 86 164 s. A1: ω. C1: v = ωr. A1: v = 3080 m s⁻¹. B1: same period so same ω. B1: v ∝ r.', 6),
('0dd91152-1c93-5be3-91b2-616eae76f810', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 48, 48, 'A car engine crankshaft turns at 3000 rev min⁻¹. A point on the crankshaft is 4.5 cm from the axis. (a) Calculate the angular speed of the crankshaft. (b) Calculate the speed of the point. (c) The engine speed rises to 4500 rev min⁻¹. Calculate the new speed of the point. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '14.14', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π × 3000 ÷ 60 = 314 rad s⁻¹. (b) v = ωr = 314 × 0.045 = 14.1 m s⁻¹. (c) v ∝ ω, so v = 14.1 × 4500 ÷ 3000 = 21.2 m s⁻¹. Mark scheme (5 marks). C1: × 2π. C1: ÷ 60. A1: ω = 314 rad s⁻¹. C1: v = ωr with r in metres. B1: (c) v ∝ ω.', 5),
('bf4f79fe-6cdd-53f3-86b1-41747b183746', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 49, 49, 'On a bicycle, the pedals turn a front cog with 40 teeth. The chain links it to a rear cog with 15 teeth, fixed to the back wheel of radius 0.34 m. The rider pedals at 1.2 rev s⁻¹. (a) Explain why the rear cog turns 40/15 times for each turn of the pedals. (b) Calculate the frequency and angular speed of the back wheel. (c) Calculate the speed of the bicycle. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '6.836', 'm s⁻¹', false, NULL, false, NULL, '(a) The chain moves the same number of teeth past each cog, so each pedal turn moves 40 teeth, which is 40/15 turns of the rear cog. (b) f = 1.2 × 40 ÷ 15 = 3.20 Hz, ω = 2πf = 20.1 rad s⁻¹. (c) v = ωr = 20.1 × 0.34 = 6.84 m s⁻¹. Mark scheme (6 marks). B1: same number of teeth per second at both cogs. C1: f = 1.2 × 40/15. C1: ω = 2πf. C1: v = ωr. B1: rolling without slipping. A1: v = 6.84 m s⁻¹.', 6),
('8b747ad2-7c4d-5557-a402-79967f37b209', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '744a91d7-6b75-4fd2-b3c7-17689e965446', 'a-level', '16.4', '9702 coursebook 16.4 · Angular speed', 50, 50, 'A washing machine drum of radius 0.24 m speeds up from rest. A student records the time for each complete turn: 1st turn 0.80 s, 2nd 0.40 s, 3rd 0.27 s, 4th 0.20 s. (a) Calculate the average angular speed during the 4th turn. (b) Calculate the average speed of a sock on the drum wall during the 4th turn. (c) Describe how the angular speed changes over the four turns, using the data. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '7.54', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = 2π ÷ 0.20 = 31.4 rad s⁻¹. (b) v = ωr = 31.4 × 0.24 = 7.54 m s⁻¹. (c) The time per turn falls (0.80, 0.40, 0.27, 0.20 s), so the average angular speed rises: roughly 7.9, 16, 23 and 31 rad s⁻¹, increasing by about 8 rad s⁻¹ per turn. Mark scheme (6 marks). C1: ω = 2π/t for one turn. A1: ω. C1: v = ωr. A1: v = 7.54 m s⁻¹. B1: angular speed increases. B1: quantitative use of data.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('827005b7-1514-5215-a9ad-cfbcf510a6a0', 'e94ce489-d2ea-5192-a4d1-da275b4bd9b5', 'v = ω/r', 'A', false, 0),
('2f4a5102-73ce-51ce-93bb-92ff960f0718', 'e94ce489-d2ea-5192-a4d1-da275b4bd9b5', 'v = ωr²', 'B', false, 1),
('f5bdc6d0-894f-5bf0-aaef-23af9840338d', 'e94ce489-d2ea-5192-a4d1-da275b4bd9b5', 'v = ωr', 'C', true, 2),
('a49248c3-3329-5003-b4da-2d66da8c3d7d', 'e94ce489-d2ea-5192-a4d1-da275b4bd9b5', 'v = r/ω', 'D', false, 3),
('f9e5b12b-1ea6-587e-8e3d-598c6b948588', 'c6b6677e-d493-546c-a764-ce8bf14cbb10', 'Angular speed', 'A', true, 0),
('c1b81dc7-0e6c-5870-8cc0-8843b1634051', 'c6b6677e-d493-546c-a764-ce8bf14cbb10', 'Speed', 'B', false, 1),
('c22831dd-e87a-5696-845f-4384a9099066', 'c6b6677e-d493-546c-a764-ce8bf14cbb10', 'Velocity', 'C', false, 2),
('bbc6df84-84dc-5126-b34a-bb1fddd7320d', 'c6b6677e-d493-546c-a764-ce8bf14cbb10', 'Centripetal acceleration', 'D', false, 3),
('8fd352ba-6f45-594a-914e-6cdd452f7f94', 'aa8e8fd0-81dd-5c39-9af0-8fed048612c4', '7.3 × 10⁻⁵ rad min⁻¹', 'A', false, 0),
('6f7a975d-9866-5996-9394-0b82a63609a1', 'aa8e8fd0-81dd-5c39-9af0-8fed048612c4', '2.0 × 10⁻⁷ rad s⁻¹', 'B', false, 1),
('05e82965-98b1-5e6c-b201-afbd9863fb1b', 'aa8e8fd0-81dd-5c39-9af0-8fed048612c4', '0.26 rad s⁻¹', 'C', false, 2),
('ea980dc2-8bcc-518c-a801-6124774084af', 'aa8e8fd0-81dd-5c39-9af0-8fed048612c4', '7.3 × 10⁻⁵ rad s⁻¹', 'D', true, 3),
('f39c38f5-af76-5a02-b201-ae6950f864ce', '21f37847-ea6f-5ce6-8022-e6f277a07631', '2πf', 'A', true, 0),
('ea7fc5c7-b015-5edf-ba9f-8e5bc9f2beaf', '21f37847-ea6f-5ce6-8022-e6f277a07631', 'f/2π', 'B', false, 1),
('9e875e9b-8776-5949-a0af-7a6455666a3c', '21f37847-ea6f-5ce6-8022-e6f277a07631', 'πf', 'C', false, 2),
('ec8f4f27-d66f-5121-bdb7-e42ba7cf9c17', '21f37847-ea6f-5ce6-8022-e6f277a07631', '2π/f', 'D', false, 3),
('415a62d5-82fa-5811-8319-f99d1f09e228', 'a35d48e1-6abe-5630-aa45-0956bfb6fd30', '½', 'A', false, 0),
('6da09e6c-707d-5d03-8cdc-643782e9ef4b', 'a35d48e1-6abe-5630-aa45-0956bfb6fd30', '2', 'B', true, 1),
('8b7c9d8f-d96b-548a-bd44-28e8c92f0eb4', 'a35d48e1-6abe-5630-aa45-0956bfb6fd30', '8', 'C', false, 2),
('d7ba9f86-5e8a-564a-90a4-449ef20650bd', 'a35d48e1-6abe-5630-aa45-0956bfb6fd30', '4', 'D', false, 3),
('f9c15b02-4d95-559c-8023-9d31160083e6', '5e2da1f0-3a2e-5ec5-8837-69b6fb19ce2a', 'The orbit is about 365 times faster', 'A', false, 0),
('94d05976-6848-5075-9377-07bcf8e2e670', '5e2da1f0-3a2e-5ec5-8837-69b6fb19ce2a', 'They are equal', 'B', false, 1),
('dae769bf-bdf7-59bc-9b38-53432d983b5b', '5e2da1f0-3a2e-5ec5-8837-69b6fb19ce2a', 'The spin is about 365 times faster', 'C', true, 2),
('31855d36-7b7c-5d5a-a05c-d8f63a0d246d', '5e2da1f0-3a2e-5ec5-8837-69b6fb19ce2a', 'The spin is about 24 times faster', 'D', false, 3),
('d2446ed8-b5cb-554e-a4ac-b103cdb8546d', '3edb4992-5a2e-59f2-8903-69ecb38c9bf0', '1/16', 'A', false, 0),
('db2bd056-3cbe-5448-a270-a12042a75178', '3edb4992-5a2e-59f2-8903-69ecb38c9bf0', '4', 'B', false, 1),
('2c66716e-1cc1-57b3-9fee-83d56c360b85', '3edb4992-5a2e-59f2-8903-69ecb38c9bf0', '24', 'C', false, 2),
('12c1a7d7-7036-520c-b1d5-4bf5c971edba', '3edb4992-5a2e-59f2-8903-69ecb38c9bf0', '16', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('22ba7082-49e2-5bb7-a24f-1f0e2479d7c9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 10, 10, 'What provides the centripetal force on a car driving round a flat, unbanked bend?', NULL, 1, 'multiple_choice'::answer_type, 'Friction between the tyres and the road', NULL, false, NULL, false, NULL, 'On a flat road the weight and the normal force are vertical and cancel. The only horizontal force towards the centre is the sideways friction of the road on the tyres. Mark scheme (1 mark). B1: C (Friction between the tyres and the road).', 1),
('627fc06d-7e09-5967-ac75-cfeef3f8e716', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 11, 11, 'What provides the centripetal force on the Moon as it orbits the Earth?', NULL, 1, 'multiple_choice'::answer_type, 'The gravitational pull of the Earth', NULL, false, NULL, false, NULL, 'The Earth''s gravitational force on the Moon acts towards the Earth (the centre of the orbit) and provides the centripetal force. Mark scheme (1 mark). B1: A (The gravitational pull of the Earth).', 1),
('7df8c064-9d24-5bd8-8ed2-5a3ac839ce9d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 12, 12, 'A ball on a string is whirled in a horizontal circle. In which direction is the resultant force on the ball?', NULL, 1, 'multiple_choice'::answer_type, 'Towards the centre of the circle', NULL, false, NULL, false, NULL, 'For uniform circular motion the resultant force is centripetal: always directed towards the centre of the circle. Mark scheme (1 mark). B1: D (Towards the centre of the circle).', 1),
('1c22182f-69ae-5d85-95ff-427ce44b568c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 13, 13, 'In a simple model of a hydrogen atom, an electron moves in a circle around the proton. What provides the centripetal force?', NULL, 1, 'multiple_choice'::answer_type, 'The electric attraction between the electron and the proton', NULL, false, NULL, false, NULL, 'The electrostatic attraction between the opposite charges is about 10³⁹ times larger than the gravitational attraction, and acts towards the proton. Mark scheme (1 mark). B1: B (The electric attraction between the electron and the proton).', 1),
('ab7e2a69-7f34-5aa6-87f1-44512bd320e5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 14, 14, 'Which statement about centripetal force is correct?', NULL, 1, 'multiple_choice'::answer_type, 'It is the name for the resultant force needed to keep a body moving in a circle', NULL, false, NULL, false, NULL, 'Centripetal force is not a new type of force: it is the resultant of the real forces (tension, friction, gravity, normal contact…) and it acts towards the centre. Mark scheme (1 mark). B1: C (It is the name for the resultant force needed to keep a body moving in a circle).', 1),
('82ffcec8-d830-5ff6-b340-e474701146f9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 15, 15, 'A 0.20 kg ball is swung on a cord at 4.0 m s⁻¹ in a horizontal circle of radius 0.80 m. Calculate the centripetal force on it.', NULL, 1, 'numeric'::answer_type, '4', 'N', false, NULL, false, NULL, 'F = mv²/r = 0.20 × 4.0² ÷ 0.80 = 4.0 N. Mark scheme (2 marks). C1: F = mv²/r. A1: F = 4.0 N.', 2),
('aff4d0a1-d5fc-5fcf-8aec-6500ecb280d4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 16, 16, 'What resultant force is needed to keep a 1200 kg car moving at 15 m s⁻¹ round a bend of radius 45 m?', NULL, 1, 'numeric'::answer_type, '6000', 'N', false, NULL, false, NULL, 'F = mv²/r = 1200 × 15² ÷ 45 = 6000 N. Mark scheme (2 marks). C1: F = mv²/r. A1: F = 6000 N.', 2),
('645796d2-aca9-5526-8d25-b85f63417826', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 17, 17, 'A 0.050 kg toy on the end of a rotating arm of length 0.30 m turns at 12 rad s⁻¹. Calculate the centripetal force on the toy.', NULL, 1, 'numeric'::answer_type, '2.16', 'N', false, 0.05, false, NULL, 'F = mω²r = 0.050 × 12² × 0.30 = 2.2 N. Mark scheme (2 marks). C1: F = mω²r. A1: F = 2.2 N.', 2),
('10e9b9b1-87e9-5ebd-89a8-6a92458978f4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 18, 18, 'A tension of 36 N keeps a stone moving at 6.0 m s⁻¹ in a horizontal circle of radius 0.50 m. Calculate the mass of the stone.', NULL, 1, 'numeric'::answer_type, '0.5', 'kg', false, NULL, false, NULL, 'm = Fr/v² = 36 × 0.50 ÷ 6.0² = 0.50 kg. Mark scheme (2 marks). C1: F = mv²/r rearranged. A1: m = 0.50 kg.', 2),
('5d5e6cfa-0817-589e-8cee-458904d626af', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 19, 19, 'Friction can provide a centripetal force of up to 5000 N on an 800 kg car on a bend of radius 80 m. What is the highest speed the car can have on the bend?', NULL, 1, 'numeric'::answer_type, '22.36', 'm s⁻¹', false, NULL, false, NULL, 'v = √(Fr/m) = √(5000 × 80 ÷ 800) = 22 m s⁻¹. Mark scheme (2 marks). C1: v² = Fr/m. A1: v = 22 m s⁻¹.', 2),
('02d31682-7268-5a0c-bb76-24b1d8b200e2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 20, 20, 'The speed of a body moving in a circle of fixed radius is doubled. By what factor does the centripetal force needed change?', NULL, 1, 'multiple_choice'::answer_type, '4', NULL, false, NULL, false, NULL, 'F = mv²/r, so F ∝ v². Doubling v multiplies F by 2² = 4. Mark scheme (1 mark). B1: A (4).', 1),
('1b9bb6b9-f767-5e08-b3a6-a66ad729fa97', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 21, 21, 'A car goes round a bend of radius r at speed v. The same car goes round a bend of radius 2r at the same speed. What is the ratio (centripetal force on the second bend)/(centripetal force on the first)?', NULL, 1, 'multiple_choice'::answer_type, '½', NULL, false, NULL, false, NULL, 'F = mv²/r, so with m and v fixed F ∝ 1/r. Doubling r halves F. Mark scheme (1 mark). B1: D (½).', 1),
('9290361b-0857-5f9f-ae9f-4f7b3d06b8cf', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 22, 22, 'A 2.0 kg sack hangs from the end of a rotating crane arm, 1.5 m from the axis. The arm rotates at 3.0 rad s⁻¹. Calculate the horizontal force on the sack needed for this motion.', NULL, 1, 'numeric'::answer_type, '27', 'N', false, NULL, false, NULL, 'F = mω²r = 2.0 × 3.0² × 1.5 = 27 N. Mark scheme (2 marks). C1: F = mω²r. A1: F = 27 N.', 2),
('8684a0e9-675b-5fb0-85b7-cd6ed3ec2f2c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 23, 23, 'A 0.15 kg ball on a string of length 0.60 m moves in a horizontal circle with a string tension of 9.6 N. Ignore gravity. Calculate the speed of the ball.', NULL, 1, 'numeric'::answer_type, '6.197', 'm s⁻¹', false, NULL, false, NULL, 'v = √(Fr/m) = √(9.6 × 0.60 ÷ 0.15) = 6.2 m s⁻¹. Mark scheme (2 marks). C1: v² = Fr/m. A1: v = 6.2 m s⁻¹.', 2),
('3d1b3577-26ef-5a03-b8d7-14ed46b98ede', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 24, 24, 'A 65 kg skater moving round a circle has a centripetal acceleration of 5.3 m s⁻². Calculate the resultant force on her.', NULL, 1, 'numeric'::answer_type, '344.5', 'N', false, NULL, false, NULL, 'F = ma = 65 × 5.3 = 340 N. Mark scheme (1 mark). A1: F = 340 N.', 1),
('b66de096-9fb3-5477-a9e0-61643383e7e3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 25, 25, 'A 1500 kg car drives round a bend of radius 60 m at 20 m s⁻¹. Calculate the centripetal force on the car.', NULL, 1, 'numeric'::answer_type, '10000', 'N', false, NULL, false, NULL, 'F = mv²/r = 1500 × 20² ÷ 60 = 10 000 N. Mark scheme (2 marks). C1: F = mv²/r. A1: F = 1.0 × 10⁴ N.', 2),
('ab7b3cb4-14a8-5c1b-9f0a-fc96964b869e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 26, 26, 'A planet moves in a circular orbit around a star. If the star had no gravity, how would the planet move?', NULL, 1, 'multiple_choice'::answer_type, 'In a straight line at constant speed', NULL, false, NULL, false, NULL, 'With no centripetal force there is no resultant force, so by Newton''s first law the planet would continue in a straight line at constant velocity. Mark scheme (1 mark). B1: B (In a straight line at constant speed).', 1),
('aef9a4ee-82cc-5036-9b65-423ef6dcdc0f', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 27, 27, 'A mass of 0.25 kg on a string is whirled in a horizontal circle of radius 0.60 m, making one revolution every 0.50 s. Ignoring gravity, calculate the tension in the string.', NULL, 2, 'numeric'::answer_type, '23.69', 'N', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.50 = 12.6 rad s⁻¹. Tension = mω²r = 0.25 × 12.6² × 0.60 = 23.7 N. Mark scheme (3 marks). C1: ω = 2π/T. C1: tension provides the centripetal force, F = mω²r. A1: tension = 23.7 N.', 3),
('627ac301-14ff-5e57-8478-9a766850994c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 28, 28, 'An athlete practising with a light training hammer (mass 0.080 kg) swings it round a horizontal circle of radius 1.2 m, completing a turn every 0.80 s. What tension does the wire carry?', NULL, 2, 'numeric'::answer_type, '5.922', 'N', false, NULL, false, NULL, 'ω = 2π ÷ 0.80 = 7.85 rad s⁻¹. T = mω²r = 0.080 × 7.85² × 1.2 = 5.92 N. Mark scheme (3 marks). C1: ω from the period. C1: tension = mω²r. A1: tension = 5.92 N.', 3),
('3480e390-0195-5534-9bfb-d72a9d7bd416', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 29, 29, 'A car of mass 1100 kg drives round a flat circular bend of radius 60 m at 18 m s⁻¹. Calculate the friction force the road must exert on the car, and state its direction.', NULL, 2, 'numeric'::answer_type, '5940', 'N', false, NULL, false, NULL, 'Friction is the only horizontal force, so it provides the centripetal force: F = mv²/r = 1100 × 18² ÷ 60 = 5940 N, directed towards the centre of the bend. Mark scheme (3 marks). C1: friction provides the centripetal force. C1: F = mv²/r. A1: F = 5940 N.', 3),
('4f4c8a5d-95cf-5b45-9e44-fc7efb0244e0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 30, 30, 'A cyclist and bicycle (total mass 75 kg) lean into a flat bend of radius 20 m. The tyres can grip with a sideways friction force of at most 480 N. Calculate the greatest speed at which the cyclist can take the bend.', NULL, 2, 'numeric'::answer_type, '11.31', 'm s⁻¹', false, NULL, false, NULL, 'At the limit, maximum friction = mv²/r, so v = √(Fr/m) = √(480 × 20 ÷ 75) = 11.3 m s⁻¹. Mark scheme (3 marks). C1: maximum friction = mv²/r. C1: rearranged for v. A1: v_max = 11.3 m s⁻¹.', 3),
('552f40d6-bf1a-5320-ab29-4a682070498d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 31, 31, 'A coin is placed on a turntable that rotates at a steady rate. The coin is moved further from the centre and the turntable runs at the same rate. What happens to the friction force needed to stop the coin sliding?', NULL, 2, 'multiple_choice'::answer_type, 'It increases in proportion to the distance from the centre', NULL, false, NULL, false, NULL, 'F = mω²r with ω fixed, so F ∝ r. This is why a coin near the rim slides off first. Mark scheme (3 marks). C1: ω the same. C1: F = mω²r ∝ r. A1: B (It increases in proportion to the distance from the centre). Common mistake: using F = mv²/r and saying F ∝ 1/r — v is not constant here, ω is.', 3),
('af6aaef3-7f30-5881-9417-b68302f773f4', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 32, 32, 'A child of mass 35 kg on a swing passes through the lowest point at 3.0 m s⁻¹. The swing''s chains are 2.5 m long. Calculate the total tension in the chains at the lowest point. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '469.4', 'N', false, NULL, false, NULL, 'At the lowest point the resultant upward force provides the centripetal force: T − mg = mv²/r. T = mg + mv²/r = 35 × 9.81 + 35 × 3.0² ÷ 2.5 = 469 N. Mark scheme (4 marks). C1: T − mg = mv²/r. C1: mg. C1: mv²/r. A1: T = 469 N. Common mistake: setting T = mv²/r and forgetting the weight.', 4),
('d4fa01da-4f4a-5572-85bb-e0a0748b9363', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 33, 33, 'A bucket and water of total mass 0.40 kg is swung in a vertical circle of radius 0.75 m. At the bottom of the circle it moves at 5.0 m s⁻¹. What force does the person''s hand exert on the handle at that point? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '17.26', 'N', false, NULL, false, NULL, 'T − mg = mv²/r, so T = 0.40 × 9.81 + 0.40 × 5.0² ÷ 0.75 = 17.3 N, upwards. Mark scheme (4 marks). C1: T − mg = mv²/r. C1: mg. C1: mv²/r. A1: T = 17.3 N.', 4),
('f1fc2b97-1d70-5b8f-97a8-f13013019763', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 34, 34, 'A rider on a fairground loop moves at 25 m s⁻¹ round a circle of radius 80 m. Calculate the centripetal acceleration as a multiple of g. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.7964', NULL, false, NULL, false, NULL, 'a = v²/r = 25² ÷ 80 = 7.81 m s⁻². In units of g: 7.81 ÷ 9.81 = 0.796. Mark scheme (3 marks). C1: a = v²/r. C1: divide by g. A1: a/g = 0.796.', 3),
('16b7127e-c271-55f9-b20c-dd90f373981c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 35, 35, 'The Moon (mass 7.35 × 10²² kg) moves in a circular orbit of radius 3.84 × 10⁸ m with a period of 27.3 days. Calculate the gravitational force the Earth exerts on it.', NULL, 2, 'numeric'::answer_type, '2.003e20', 'N', false, NULL, false, NULL, 'T = 2.36 × 10⁶ s. ω = 2π/T = 2.66 × 10⁻⁶ rad s⁻¹. F = mω²r = 7.35 × 10²² × (2.66 × 10⁻⁶)² × 3.84 × 10⁸ = 2.00 × 10²⁰ N. Mark scheme (4 marks). C1: T in seconds. C1: ω = 2π/T. B1: gravity provides the centripetal force: F = mω²r. A1: F = 2.00 × 10²⁰ N.', 4),
('952c971a-0b36-50fd-bc59-04a1cca24b55', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 36, 36, 'A student says that a passenger in a car going round a bend is "thrown outwards by centrifugal force". Which is the correct explanation of what the passenger feels?', NULL, 2, 'multiple_choice'::answer_type, 'The passenger tends to continue in a straight line; the door pushes inwards on the passenger to provide the centripetal force', NULL, false, NULL, false, NULL, 'In the ground frame there is no outward force. The passenger''s inertia keeps them moving in a straight line until the door (or seat friction) supplies the inward, centripetal force. The push of the door is what they feel. Mark scheme (3 marks). C1: inertia / tendency to move along tangent. C1: inward force from the door is the centripetal force. A1: C (The passenger tends to continue in a straight line; the door pushes inwards on the passenger to provide the centripetal force).', 3),
('044074dd-3342-510e-922c-4a149bc8a7ec', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 37, 37, 'A string breaks if its tension exceeds 60 N. It is used to whirl a 0.30 kg mass in a horizontal circle of radius 0.50 m (ignore gravity). Calculate the maximum rate of rotation in rev min⁻¹.', NULL, 2, 'numeric'::answer_type, '191', 'rev min⁻¹', false, NULL, false, NULL, 'F = mω²r, so ω_max = √(F/mr) = √(60 ÷ (0.30 × 0.50)) = 20.0 rad s⁻¹. In rev min⁻¹: 20.00 × 60 ÷ (2π) = 191. Mark scheme (4 marks). C1: F = mω²r. C1: ω_max. C1: convert to rev min⁻¹. A1: maximum rate = 191 rev min⁻¹.', 4),
('d1582a34-2aac-5699-bd2a-62c433d687a5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 38, 38, 'A mass on a string moves in a horizontal circle. The speed is kept constant and the string is lengthened from 0.5 m to 1.0 m. What happens to the tension?', NULL, 2, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'At constant speed, T = mv²/r ∝ 1/r. Doubling the radius halves the tension. Mark scheme (3 marks). C1: v constant. C1: T ∝ 1/r. A1: A (It halves).', 3),
('1e1ff6a2-cdbf-528d-9086-6a68ec967426', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 39, 39, 'Two identical cars go round the same circular bend. Car A goes at 10 m s⁻¹, car B at 20 m s⁻¹. Car A needs a friction force of 2.0 kN. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Car B needs 8.0 kN of friction, so it is more likely to skid', NULL, false, NULL, false, NULL, 'F = mv²/r ∝ v². Doubling the speed needs 2² = 4 times the force: 4 × 2.0 = 8.0 kN. If the maximum friction is less than this, car B skids. Mark scheme (4 marks). C1: F ∝ v². C1: factor 4. C1: 8.0 kN. A1: D (Car B needs 8.0 kN of friction, so it is more likely to skid).', 4),
('9e8f6c3e-2aaf-5577-841d-aa05128e507b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 40, 40, 'A 60 kg astronaut on a training centrifuge moves in a circle of radius 8.0 m at 14 m s⁻¹. Calculate the force the seat must exert towards the centre, and express it as a multiple of her weight. Give the multiple. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '2.497', NULL, false, NULL, false, NULL, 'F = mv²/r = 60 × 14² ÷ 8.0 = 1470 N. Weight = 60 × 9.81 = 589 N. Multiple = 1470 ÷ 589 = 2.50. Mark scheme (3 marks). C1: F = mv²/r. C1: ratio to mg. A1: multiple = 2.50.', 3),
('005c2bff-6524-5de6-9b47-3e7d23c063f5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 41, 41, 'A student whirls a rubber bung on a string in a horizontal circle and lets go of the string when the bung is at the north side of the circle, moving east. Which describes the bung''s horizontal motion afterwards?', NULL, 2, 'multiple_choice'::answer_type, 'It travels east in a straight line', NULL, false, NULL, false, NULL, 'With no tension there is no horizontal force, so the bung keeps the velocity it had: east, along the tangent. Mark scheme (3 marks). C1: no centripetal force after release. C1: continues along the tangent. A1: C (It travels east in a straight line).', 3),
('699dcd3e-8b59-5f28-891e-6a229a7e0477', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 42, 42, 'A 0.20 kg mass is attached to a spring of natural length 0.30 m and stiffness 80 N m⁻¹ and whirled in a horizontal circle on a smooth table, so that the spring stretches to 0.35 m. Calculate the speed of the mass.', NULL, 2, 'numeric'::answer_type, '2.646', 'm s⁻¹', false, NULL, false, NULL, 'Spring tension = kx = 80 × 0.05 = 4.0 N. This provides mv²/r with r = 0.35 m, so v = √(Tr/m) = √(4.0 × 0.35 ÷ 0.20) = 2.65 m s⁻¹. Mark scheme (4 marks). C1: T = kx with x = 0.05 m. C1: T = mv²/r. C1: r = stretched length. A1: v = 2.65 m s⁻¹. Common mistake: using the natural length 0.30 m as the radius.', 4),
('f1f54126-86fc-5d22-a803-4eec2b86f291', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 43, 43, 'A car of mass 900 kg travels round a flat bend of radius 40 m at 14 m s⁻¹. (a) Calculate the centripetal force required. (b) This force is provided by friction. Calculate the ratio (friction force)/(weight). (c) On a dry day the maximum friction is 0.80 times the weight. Calculate the maximum safe speed round this bend. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '17.72', 'm s⁻¹', false, NULL, false, NULL, '(a) F = mv²/r = 900 × 14² ÷ 40 = 4410 N. (b) ratio = 4410 ÷ (900 × 9.81) = 0.499. (c) 0.80mg = mv²/r, so v = √(0.80gr) = √(0.80 × 9.81 × 40) = 17.7 m s⁻¹ — the mass cancels. Mark scheme (6 marks). C1: F = mv²/r. A1: F. A1: ratio. C1: 0.80 mg = mv²/r. M1: mass cancels. A1: v_max = 17.7 m s⁻¹.', 6),
('af5dca37-aed3-5f31-9da3-c4dd710cda3e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 44, 44, 'Road engineers check a tight bend of radius 25 m. The maximum sideways friction on a car is 0.80 of its weight on a dry road but only 0.35 of its weight on ice. (a) Show that the maximum speed does not depend on the car''s mass. (b) Calculate the maximum speed on the dry road. (c) Calculate the maximum speed on ice, and the percentage reduction. Give only the maximum speed on ice. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '9.265', 'm s⁻¹', false, NULL, false, NULL, '(a) kmg = mv²/r gives v = √(kgr): m cancels. (b) v = √(0.80 × 9.81 × 25) = 14.0 m s⁻¹. (c) v = √(0.35 × 9.81 × 25) = 9.26 m s⁻¹, a reduction of 34 %. Mark scheme (6 marks). M1: friction = kmg equated to mv²/r. A1: mass cancels. A1: dry speed. C1: same method with 0.35. A1: v_ice = 9.26 m s⁻¹. B1: percentage reduction.', 6),
('a430612b-af34-5873-bf84-96468dd48b2d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 45, 45, 'A ball of mass 0.50 kg on a string of length 0.80 m is swung in a vertical circle. At the bottom its speed is 7.0 m s⁻¹. Air resistance is negligible. (a) Calculate the tension at the bottom. (b) Use energy conservation to find the speed at the top. (c) Calculate the tension at the top. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '6.1', 'N', false, NULL, false, NULL, '(a) T − mg = mv²/r: T = 0.50 × 7.0² ÷ 0.80 + 0.50 × 9.81 = 35.5 N. (b) ½mv_top² = ½mv² − mg(2L): v_top = √(7.0² − 4 × 9.81 × 0.80) = 4.20 m s⁻¹. (c) At the top, T + mg = mv²/r: T = 0.50 × 4.20² ÷ 0.80 − 0.50 × 9.81 = 6.10 N. Mark scheme (7 marks). C1: T − mg = mv²/r at bottom. A1: T bottom. C1: energy: height gain 2L. A1: v at top. C1: T + mg = mv²/r at top. A1: T_top = 6.10 N. B1: tension greatest at the bottom.', 7),
('92ea1af1-2958-53b5-947e-097bf24b4d3c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 46, 46, 'A roller-coaster car goes round a vertical loop of radius 8.0 m. (a) State the forces on the car at the top of the loop and their directions. (b) Show that the minimum speed at the top for the car to stay in contact with the track is √(gr). (c) Calculate this minimum speed. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '8.859', 'm s⁻¹', false, NULL, false, NULL, '(a) Weight mg downwards and the normal contact force N from the track, also downwards (the track is above the car). (b) N + mg = mv²/r. The car only just stays in contact when N = 0, so mg = mv²/r and v = √(gr). (c) v = √(9.81 × 8.0) = 8.86 m s⁻¹. Mark scheme (5 marks). B1: both forces downwards at the top. M1: N + mg = mv²/r. M1: N = 0 at the minimum speed. C1: v = √(gr). A1: v_min = 8.86 m s⁻¹.', 5),
('52cc1c79-b094-563e-92a2-9306e391e7ee', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 47, 47, 'A designer wants a frictionless toy car to coast round a vertical loop of radius 15 cm after rolling from rest down a slope. (a) Write an expression for the minimum speed at the top of the loop. (b) Use energy conservation to show that the start of the slope must be at least 2.5r above the bottom of the loop. (c) Calculate this minimum height in cm. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '37.5 cm', 'cm', false, NULL, false, NULL, '(a) mg = mv²/r at the top, so v_min² = gr. (b) mgh = mg(2r) + ½m(gr), so h = 2r + r/2 = 2.5r. (c) h = 2.5 × 15 = 37.5 cm. Mark scheme (5 marks). C1: mg = mv²/r. A1: v² = gr. M1: energy equation including 2r. M1: h = 2.5r shown. A1: h = 37.5 cm.', 5),
('0d78a38c-85d7-58cf-9bde-ea5e66a04d10', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 48, 48, 'A "rotor" fairground ride is a vertical cylinder of radius 3.0 m. Riders stand against the wall, the cylinder spins at 24 rev min⁻¹, and the floor drops away. A rider has mass 60 kg. (a) Calculate the angular speed. (b) Calculate the normal contact force of the wall on the rider. (c) State which force stops the rider sliding down, and calculate its size. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '1137', 'N', false, NULL, false, NULL, '(a) ω = 2π × 24 ÷ 60 = 2.51 rad s⁻¹. (b) The wall''s normal force is the only horizontal force, so it provides the centripetal force: N = mω²r = 60 × 2.51² × 3.0 = 1140 N. (c) Upward friction from the wall balances the weight: 60 × 9.81 = 589 N. Mark scheme (6 marks). C1: ω from rev min⁻¹. A1: ω. B1: normal force provides centripetal force. C1: N = mω²r. A1: N = 1140 N. B1: friction = weight.', 6),
('02149e97-5cb7-5b59-bb94-380f4c12bab1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 49, 49, 'A weather satellite of mass 420 kg moves in a circular orbit of radius 7.0 × 10⁶ m with period 97 min. (a) Calculate its angular speed. (b) Calculate the centripetal force on it. (c) Deduce the gravitational field strength at this distance from the Earth''s centre. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '8.159', 'N kg⁻¹', false, NULL, false, NULL, '(a) T = 97 × 60 = 5820 s, ω = 2π/T = 0.00108 rad s⁻¹. (b) F = mω²r = 420 × (0.00108)² × 7.0 × 10⁶ = 3430 N. (c) Gravity provides this force, so g = F/m = ω²r = (0.00108)² × 7.0 × 10⁶ = 8.16 N kg⁻¹. Mark scheme (5 marks). C1: T in s. A1: ω. C1: F = mω²r. A1: g = 8.16 N kg⁻¹. B1: g = F/m = ω²r.', 5),
('eb8f4374-5048-5ee3-9690-da8f7656b8d9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '9b374880-4182-4886-b234-d78a4ea3ad26', 'a-level', '16.5', '9702 coursebook 16.5 · Centripetal forces', 50, 50, 'A small block of mass 0.15 kg sits on a horizontal turntable 0.12 m from the axis. The maximum friction force between the block and the turntable is 0.45 N. The turntable is slowly speeded up from rest. (a) State what provides the centripetal force on the block. (b) Calculate the angular speed at which the block starts to slide. (c) The block is moved to 0.24 m from the axis. Deduce the new angular speed at which it slides. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '5', 'rad s⁻¹', false, NULL, false, NULL, '(a) Static friction from the turntable, towards the axis. (b) Sliding starts when mω²r = F_max: ω = √(F/mr) = √(0.45 ÷ (0.15 × 0.12)) = 5.00 rad s⁻¹. (c) ω ∝ 1/√r, so ω = 5.00 ÷ √2 = 3.54 rad s⁻¹. Mark scheme (6 marks). B1: friction towards the centre. C1: F_max = mω²r. C1: rearrangement. A1: ω. M1: ω ∝ 1/√r. A1: ω = 5.00 rad s⁻¹.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('50808187-2fc5-578c-8300-4f078678f7d6', '22ba7082-49e2-5bb7-a24f-1f0e2479d7c9', 'The weight of the car', 'A', false, 0),
('78a88afd-687d-50ee-b876-3f7af365f9f6', '22ba7082-49e2-5bb7-a24f-1f0e2479d7c9', 'The normal contact force from the road', 'B', false, 1),
('cb59a3ac-6d5a-5496-bc2e-6ebbfd094611', '22ba7082-49e2-5bb7-a24f-1f0e2479d7c9', 'Friction between the tyres and the road', 'C', true, 2),
('026d5213-aef0-57bb-8963-1d3f1e3553c1', '22ba7082-49e2-5bb7-a24f-1f0e2479d7c9', 'The driving force of the engine', 'D', false, 3),
('adc80a8d-47f5-5e5a-a742-f152f541b926', '627fc06d-7e09-5967-ac75-cfeef3f8e716', 'The gravitational pull of the Earth', 'A', true, 0),
('23b61b64-ebaa-5e4f-bf49-d1a33235fc73', '627fc06d-7e09-5967-ac75-cfeef3f8e716', 'The gravitational pull of the Sun', 'B', false, 1),
('a3a8ac60-41ac-5a6c-a949-f1ac862343f3', '627fc06d-7e09-5967-ac75-cfeef3f8e716', 'The Moon''s own weight acting outwards', 'C', false, 2),
('c8ca3ac1-9bf9-5fd8-beb6-f33569661422', '627fc06d-7e09-5967-ac75-cfeef3f8e716', 'The Moon''s orbital speed', 'D', false, 3),
('43e00541-a6c9-5427-9a27-4f9bd6873ea7', '7df8c064-9d24-5bd8-8ed2-5a3ac839ce9d', 'Along the direction of motion', 'A', false, 0),
('5f52b9e6-33e2-51b8-b2f1-9069b8b9a51d', '7df8c064-9d24-5bd8-8ed2-5a3ac839ce9d', 'Away from the centre of the circle', 'B', false, 1),
('14a5b1dc-f5b6-5ac3-a719-7acf2a2d1819', '7df8c064-9d24-5bd8-8ed2-5a3ac839ce9d', 'Vertically downwards', 'C', false, 2),
('2d790964-a930-58f9-b0a9-36afe71d514f', '7df8c064-9d24-5bd8-8ed2-5a3ac839ce9d', 'Towards the centre of the circle', 'D', true, 3),
('d0c5f7fc-940c-55bf-84dc-2accc142c3be', '1c22182f-69ae-5d85-95ff-427ce44b568c', 'The gravitational attraction between the electron and the proton', 'A', false, 0),
('575bd0a8-7139-5551-bbd4-0047632a6b03', '1c22182f-69ae-5d85-95ff-427ce44b568c', 'The electric attraction between the electron and the proton', 'B', true, 1),
('9761bce8-231d-5e15-98e7-77bceb73ca2d', '1c22182f-69ae-5d85-95ff-427ce44b568c', 'The strong nuclear force', 'C', false, 2),
('59840af8-1781-54a5-ae36-f5e38760644f', '1c22182f-69ae-5d85-95ff-427ce44b568c', 'The magnetic field of the proton', 'D', false, 3),
('7e4256ae-7154-5fe0-beb4-2ec190ff313c', 'ab7e2a69-7f34-5aa6-87f1-44512bd320e5', 'It is an extra force that appears whenever a body moves in a circle', 'A', false, 0),
('fe6130ec-f175-5c37-871c-1055d091d757', 'ab7e2a69-7f34-5aa6-87f1-44512bd320e5', 'It acts outwards from the centre', 'B', false, 1),
('c911e30b-064c-5cd5-b1b2-526702deeec0', 'ab7e2a69-7f34-5aa6-87f1-44512bd320e5', 'It is the name for the resultant force needed to keep a body moving in a circle', 'C', true, 2),
('2c1b5514-8094-5025-a53f-6463715b8f62', 'ab7e2a69-7f34-5aa6-87f1-44512bd320e5', 'It is always provided by gravity', 'D', false, 3),
('0bb9b4c1-abe2-5bc0-add4-4626e1cea04f', '02d31682-7268-5a0c-bb76-24b1d8b200e2', '4', 'A', true, 0),
('86c9705b-c0e7-5fcc-93ca-f99378ad5f6d', '02d31682-7268-5a0c-bb76-24b1d8b200e2', '2', 'B', false, 1),
('320da2a4-4abb-5a70-82bd-6701e78d79f4', '02d31682-7268-5a0c-bb76-24b1d8b200e2', '½', 'C', false, 2),
('d8c45166-209b-5fbd-a432-7de11e187559', '02d31682-7268-5a0c-bb76-24b1d8b200e2', '8', 'D', false, 3),
('226d5b52-f0d5-5046-be84-f8322375a9dc', '1b9bb6b9-f767-5e08-b3a6-a66ad729fa97', '2', 'A', false, 0),
('b5f65514-c9ba-5806-8c56-a9a739bd71fd', '1b9bb6b9-f767-5e08-b3a6-a66ad729fa97', '¼', 'B', false, 1),
('51b5081b-3ab7-5fa5-98e1-2f3771f7e364', '1b9bb6b9-f767-5e08-b3a6-a66ad729fa97', '1', 'C', false, 2),
('4120efeb-5f69-5a45-9c83-2628c19fac1f', '1b9bb6b9-f767-5e08-b3a6-a66ad729fa97', '½', 'D', true, 3),
('b552424b-6b3e-5c92-886b-6e61988836a4', 'ab7b3cb4-14a8-5c1b-9f0a-fc96964b869e', 'In the same circle', 'A', false, 0),
('b628bc78-34e4-5a99-beb0-0523d4ecbffd', 'ab7b3cb4-14a8-5c1b-9f0a-fc96964b869e', 'In a straight line at constant speed', 'B', true, 1),
('0773b8d9-0b8f-582f-a138-a766e3bec154', 'ab7b3cb4-14a8-5c1b-9f0a-fc96964b869e', 'Spiralling outwards', 'C', false, 2),
('de82cbe3-ddbf-5b2c-a463-e9895fd034ab', 'ab7b3cb4-14a8-5c1b-9f0a-fc96964b869e', 'Directly away from the star', 'D', false, 3),
('c27f808b-91e2-5e22-aae2-2e12fb688eff', '552f40d6-bf1a-5320-ab29-4a682070498d', 'It decreases', 'A', false, 0),
('93fa307b-4a51-56a6-b652-a7c451262502', '552f40d6-bf1a-5320-ab29-4a682070498d', 'It increases in proportion to the distance from the centre', 'B', true, 1),
('592f3cfd-b8c4-5ea8-91b9-51872d19314f', '552f40d6-bf1a-5320-ab29-4a682070498d', 'It stays the same', 'C', false, 2),
('46abb023-d850-55a1-9bcf-059d4f6386fa', '552f40d6-bf1a-5320-ab29-4a682070498d', 'It increases in proportion to the square of the distance', 'D', false, 3),
('29ccf175-bf34-5256-96e6-8d384e4194f7', '952c971a-0b36-50fd-bc59-04a1cca24b55', 'An outward centrifugal force acts on the passenger and is balanced by the door', 'A', false, 0),
('6a2b98ed-8f4b-5a2a-9ac3-ca4a7dd7c250', '952c971a-0b36-50fd-bc59-04a1cca24b55', 'The car pushes outwards on the passenger', 'B', false, 1),
('eb276869-f3d7-5be4-8110-d81df86797bb', '952c971a-0b36-50fd-bc59-04a1cca24b55', 'The passenger tends to continue in a straight line; the door pushes inwards on the passenger to provide the centripetal force', 'C', true, 2),
('c19ca9f0-e360-5ae1-8202-7da69461b52a', '952c971a-0b36-50fd-bc59-04a1cca24b55', 'Gravity acts outwards on a bend', 'D', false, 3),
('4392b780-110b-5ea4-984e-b27391ce0165', 'd1582a34-2aac-5699-bd2a-62c433d687a5', 'It halves', 'A', true, 0),
('6671370b-376a-52eb-8d92-33c959e7f1c9', 'd1582a34-2aac-5699-bd2a-62c433d687a5', 'It doubles', 'B', false, 1),
('82ea265a-9f43-5b71-91a8-2dc852c79084', 'd1582a34-2aac-5699-bd2a-62c433d687a5', 'It is unchanged', 'C', false, 2),
('dc839504-abb4-501a-a377-9de2275c3d74', 'd1582a34-2aac-5699-bd2a-62c433d687a5', 'It quarters', 'D', false, 3),
('4fcf07f1-7c38-570d-948c-7e1fa0dfaf70', '1e1ff6a2-cdbf-528d-9086-6a68ec967426', 'Car B needs 4.0 kN of friction', 'A', false, 0),
('0f52b2e0-61e9-521d-bac0-3ccfc5bcd55c', '1e1ff6a2-cdbf-528d-9086-6a68ec967426', 'Car B needs 2.0 kN of friction because the bend is the same', 'B', false, 1),
('5791c0e8-1e98-5c4e-a2ef-3e245b171d99', '1e1ff6a2-cdbf-528d-9086-6a68ec967426', 'Car B needs 1.0 kN of friction because it spends less time on the bend', 'C', false, 2),
('4c620ee5-6cfd-5e82-8bbc-352242a742fd', '1e1ff6a2-cdbf-528d-9086-6a68ec967426', 'Car B needs 8.0 kN of friction, so it is more likely to skid', 'D', true, 3),
('926310cc-09fd-57a7-8932-a9f3b7ca4f8b', '005c2bff-6524-5de6-9b47-3e7d23c063f5', 'It travels north, away from the centre', 'A', false, 0),
('a484dae8-0933-5035-925a-6374d5138a69', '005c2bff-6524-5de6-9b47-3e7d23c063f5', 'It continues in the same circle', 'B', false, 1),
('1858d1a4-ffd2-52e6-9476-716d048002f2', '005c2bff-6524-5de6-9b47-3e7d23c063f5', 'It travels east in a straight line', 'C', true, 2),
('10f9d8f5-51f4-54b0-9d3a-51a0cfa9da86', '005c2bff-6524-5de6-9b47-3e7d23c063f5', 'It travels south towards the centre', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('191ed77d-448b-5bed-961d-194190ff2f8b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 9, 9, 'A go-kart takes a bend of radius 30 m at 12 m s⁻¹. Calculate its centripetal acceleration.', NULL, 1, 'numeric'::answer_type, '4.8', 'm s⁻²', false, NULL, false, NULL, 'a = v²/r = 12² ÷ 30 = 4.8 m s⁻². Mark scheme (2 marks). C1: a = v²/r. A1: a = 4.8 m s⁻².', 2),
('144b5bab-f0e8-552a-81fe-27a3046d4f28', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 10, 10, 'What is the centripetal acceleration of a satellite orbiting at 7.7 × 10³ m s⁻¹ at a distance of 6.8 × 10⁶ m from the Earth''s centre?', NULL, 1, 'numeric'::answer_type, '8.719', 'm s⁻²', false, NULL, false, NULL, 'a = v²/r = (7.7 × 10³)² ÷ 6.8 × 10⁶ = 8.7 m s⁻². Mark scheme (2 marks). C1: a = v²/r. A1: a = 8.7 m s⁻².', 2),
('0f0e2ec4-cc29-5f65-8263-be36c77c6908', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 11, 11, 'A paint mixer stirs at 4.0 rad s⁻¹. A blob of paint is 0.25 m from the axis. Calculate its centripetal acceleration.', NULL, 1, 'numeric'::answer_type, '4', 'm s⁻²', false, NULL, false, NULL, 'a = ω²r = 4.0² × 0.25 = 4.0 m s⁻². Mark scheme (2 marks). C1: a = ω²r. A1: a = 4.0 m s⁻².', 2),
('7b5e7d03-2a3f-506b-8a4a-f0013b1f86b0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 12, 12, 'An astronaut-training centrifuge arm of radius 4.0 m gives the trainee a centripetal acceleration of 9.0 m s⁻². How fast is the trainee moving?', NULL, 1, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'v = √(ar) = √(9.0 × 4.0) = 6.0 m s⁻¹. Mark scheme (2 marks). C1: a = v²/r rearranged. A1: v = 6.0 m s⁻¹.', 2),
('16ff1750-ea08-5de7-b33d-cd4b98d66951', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 13, 13, 'A rotating fairground arm turns at 2.0 rad s⁻¹. A seat at its end has centripetal acceleration 16 m s⁻². How far is the seat from the axis?', NULL, 1, 'numeric'::answer_type, '4', 'm', false, NULL, false, NULL, 'r = a/ω² = 16 ÷ 2.0² = 4.0 m. Mark scheme (2 marks). C1: a = ω²r rearranged. A1: r = 4.0 m.', 2),
('4e5321bc-2e4e-55a2-9131-308124d8da6a', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 14, 14, 'A conker moves in a circle with speed 3.0 m s⁻¹ and angular speed 5.0 rad s⁻¹. Calculate its centripetal acceleration without first finding the radius.', NULL, 1, 'numeric'::answer_type, '15', 'm s⁻²', false, NULL, false, NULL, 'a = v²/r and v = ωr give a = vω = 3.0 × 5.0 = 15 m s⁻². Mark scheme (2 marks). C1: a = vω. A1: a = 15 m s⁻².', 2),
('0b63d98b-fdd7-55d6-8f49-db21e9620ff9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 15, 15, 'Which expression is NOT equal to the centripetal acceleration of a body moving in a circle?', NULL, 1, 'multiple_choice'::answer_type, 'ω/r', NULL, false, NULL, false, NULL, 'a = v²/r = ω²r = vω (using v = ωr). ω/r has units of rad s⁻¹ m⁻¹, not m s⁻². Mark scheme (1 mark). B1: C (ω/r).', 1),
('63357889-4ef1-5e52-818c-44e1e5ae3838', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 16, 16, 'What is the SI unit of centripetal acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'm s⁻²', NULL, false, NULL, false, NULL, 'Like any acceleration, centripetal acceleration is a rate of change of velocity, measured in m s⁻² (equivalent to N kg⁻¹). Mark scheme (1 mark). B1: A (m s⁻²).', 1),
('5f762dd6-ff34-5a78-bc54-656de634bac6', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 17, 17, 'The angular speed of a body moving in a circle of fixed radius is tripled. By what factor does its centripetal acceleration change?', NULL, 1, 'multiple_choice'::answer_type, '9', NULL, false, NULL, false, NULL, 'a = ω²r, so a ∝ ω². Tripling ω multiplies a by 3² = 9. Mark scheme (1 mark). B1: D (9).', 1),
('f94e546e-c220-582f-89c9-a693f90edfc2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 18, 18, 'A 2.5 kg parcel on a rotating carousel conveyor has a centripetal acceleration of 8.0 m s⁻². Calculate the resultant force on it.', NULL, 1, 'numeric'::answer_type, '20', 'N', false, NULL, false, NULL, 'F = ma = 2.5 × 8.0 = 20 N. Mark scheme (1 mark). A1: F = 20 N.', 1),
('89d5e624-9af3-5db4-a232-9ccfdded0f04', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 19, 19, 'A body moves in a circle with constant speed. In which direction is its acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'Along the radius, towards the centre', NULL, false, NULL, false, NULL, 'Centripetal acceleration a = v²/r is always directed along the radius towards the centre. Mark scheme (1 mark). B1: B (Along the radius, towards the centre).', 1),
('d67ee660-f255-5b34-8a5a-b30ec6ce3ac1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 20, 20, 'An ant clings to the edge of a turntable of radius 0.40 m. The edge moves at 0.80 m s⁻¹. Calculate the ant''s centripetal acceleration.', NULL, 1, 'numeric'::answer_type, '1.6', 'm s⁻²', false, NULL, false, NULL, 'a = v²/r = 0.80² ÷ 0.40 = 1.6 m s⁻². Mark scheme (2 marks). C1: a = v²/r. A1: a = 1.6 m s⁻².', 2),
('d6f68c82-e5df-5d20-b2f7-c7134cfb969d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 21, 21, 'A capsule on a slowly turning observation wheel is 20 m from the axle. The wheel turns at 0.50 rad s⁻¹. Find the centripetal acceleration of the capsule.', NULL, 1, 'numeric'::answer_type, '5', 'm s⁻²', false, NULL, false, NULL, 'a = ω²r = 0.50² × 20 = 5.0 m s⁻². Mark scheme (2 marks). C1: a = ω²r. A1: a = 5.0 m s⁻².', 2),
('424172cd-4a34-5b46-9e4c-525e7af542c0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 22, 22, 'The tip of a helicopter rotor blade moves at 200 m s⁻¹ in a circle of radius 5.0 m. Calculate its centripetal acceleration.', NULL, 1, 'numeric'::answer_type, '8000', 'm s⁻²', false, NULL, false, NULL, 'a = v²/r = 200² ÷ 5.0 = 8000 m s⁻². Mark scheme (2 marks). C1: a = v²/r. A1: a = 8000 m s⁻².', 2),
('b60d7bce-a22d-50b2-b1aa-5a5b97dbcdfe', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 23, 23, 'A spinning sycamore seed turns at 15 rad s⁻¹. The tip of its wing is 3.0 cm from the axis. Calculate the centripetal acceleration of the tip.', NULL, 1, 'numeric'::answer_type, '6.75', 'm s⁻²', false, NULL, false, NULL, 'a = ω²r = 15² × 0.030 = 6.8 m s⁻². Mark scheme (2 marks). C1: a = ω²r with r in m. A1: a = 6.8 m s⁻².', 2),
('7ea24078-ae55-5d01-a6bc-f4e9d0b76cec', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 24, 24, 'Two points on a rotating turntable are at distances r and 3r from the axis. What is the ratio (centripetal acceleration of the outer point)/(that of the inner point)?', NULL, 1, 'multiple_choice'::answer_type, '3', NULL, false, NULL, false, NULL, 'Both have the same ω and a = ω²r ∝ r, so the ratio is 3. Mark scheme (1 mark). B1: D (3).', 1),
('3099b6bd-ec5d-53d6-89cb-8d78cc702cd5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 25, 25, 'A car goes round a bend at constant speed. Which change would halve its centripetal acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'Doubling the radius of the bend at the same speed', NULL, false, NULL, false, NULL, 'a = v²/r. Doubling r halves a. Halving v quarters a, mass has no effect on a, and doubling both v and r doubles a. Mark scheme (1 mark). B1: B (Doubling the radius of the bend at the same speed).', 1),
('2f2f6c70-9802-5c0a-929a-c8dfe336a639', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 26, 26, 'A conker on a string moves in a circle of radius 0.50 m, making one revolution every 2.0 s. Calculate its centripetal acceleration.', NULL, 2, 'numeric'::answer_type, '4.935', 'm s⁻²', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 2.0 = 3.14 rad s⁻¹. a = ω²r = 3.14² × 0.50 = 4.93 m s⁻². Mark scheme (3 marks). C1: ω = 2π/T. C1: a = ω²r. A1: a = 4.93 m s⁻².', 3),
('8a33976a-d2bc-5b40-a7ee-10893a326ed3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 27, 27, 'A large park roundabout of radius 4.5 m takes 6.0 s per turn. What centripetal acceleration does a child at its edge experience?', NULL, 2, 'numeric'::answer_type, '4.935', 'm s⁻²', false, NULL, false, NULL, 'a = 4π²r/T² = 4π² × 4.5 ÷ 6.0² = 4.93 m s⁻². Mark scheme (3 marks). C1: ω = 2π/T. C1: a = ω²r = 4π²r/T². A1: a = 4.93 m s⁻².', 3),
('9620ff2d-c7b3-51f4-8669-d81c5831d080', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 28, 28, 'The drum of a washing machine has radius 0.25 m and spins at 1200 rev min⁻¹. Calculate the centripetal acceleration of the clothes against the drum, as a multiple of g. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '402.4', NULL, false, NULL, false, NULL, 'ω = 2π × 1200 ÷ 60 = 126 rad s⁻¹. a = ω²r = (126)² × 0.25 = 3950 m s⁻². Multiple of g = 3950 ÷ 9.81 = 402. Mark scheme (4 marks). C1: ω from rev min⁻¹. C1: a = ω²r. C1: ÷ g. A1: a/g = 402.', 4),
('4274a84e-24f6-545e-b944-61324004283d', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 29, 29, 'A blood centrifuge must give a sample an acceleration of 2.0 × 10⁴ g when it spins at 5000 rev min⁻¹. How far from the axis must the sample tube be? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.7157', 'm', false, NULL, false, NULL, 'ω = 2π × 5000 ÷ 60 = 524 rad s⁻¹. a = 2.0 × 10⁴ × 9.81 = 1.96 × 10⁵ m s⁻². r = a/ω² = 1.96 × 10⁵ ÷ (524)² = 0.716 m. Mark scheme (4 marks). C1: ω from rev min⁻¹. C1: a in m s⁻². C1: r = a/ω². A1: r = 0.716 m.', 4),
('45d478f3-fa36-571d-b0cf-95b6e4645727', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 30, 30, 'Calculate the centripetal acceleration of the Moon in its orbit (radius 3.84 × 10⁸ m, period 27.3 days).', NULL, 2, 'numeric'::answer_type, '0.002725', 'm s⁻²', false, NULL, false, NULL, 'T = 2.36 × 10⁶ s. a = 4π²r/T² = 4π² × 3.84 × 10⁸ ÷ (2.36 × 10⁶)² = 0.00272 m s⁻². Mark scheme (3 marks). C1: T in seconds. C1: a = 4π²r/T². A1: a = 0.00272 m s⁻².', 3),
('9df7f805-de90-5214-a337-659fb4aa6a19', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 31, 31, 'The Earth (mass 5.97 × 10²⁴ kg) orbits the Sun at 1.50 × 10¹¹ m once every 365 days. Find the gravitational force of the Sun on the Earth from its orbital motion.', NULL, 2, 'numeric'::answer_type, '3.555e22', 'N', false, NULL, false, NULL, 'T = 3.15 × 10⁷ s. a = 4π²r/T² = 0.00595 m s⁻². F = ma = 5.97 × 10²⁴ × 0.00595 = 3.55 × 10²² N. Mark scheme (4 marks). C1: T in seconds. C1: a = 4π²r/T². C1: F = ma. A1: F = 3.55 × 10²² N.', 4),
('2dbadde9-f734-5534-9a64-7faed2992e3e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 32, 32, 'A 0.40 kg ball is whirled in a horizontal circle of radius 1.2 m. Its speed is increased from 3.0 m s⁻¹ to 6.0 m s⁻¹. By how much must the tension increase?', NULL, 2, 'numeric'::answer_type, '9', 'N', false, NULL, false, NULL, 'F = mv²/r. F₁ = 0.40 × 3.0² ÷ 1.2 = 3.00 N, F₂ = 0.40 × 6.0² ÷ 1.2 = 12.0 N. Increase = 12.0 − 3.00 = 9.00 N. Mark scheme (3 marks). C1: F = mv²/r. C1: both forces calculated. A1: ΔF = 9.00 N. Common mistake: doubling the force when the speed doubles — F depends on v².', 3),
('b511a180-a0b9-5fc2-a692-a34324f7c42e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 33, 33, 'Two cars of equal mass go round the same circular track. Car X takes 20 s per lap and car Y takes 40 s per lap. What is the ratio (centripetal force on X)/(centripetal force on Y)?', NULL, 2, 'multiple_choice'::answer_type, '4', NULL, false, NULL, false, NULL, 'F = mω²r = 4π²mr/T². With m and r the same, F ∝ 1/T². T_Y = 2T_X, so F_X/F_Y = (40/20)² = 4. Mark scheme (3 marks). C1: F ∝ ω² ∝ 1/T². C1: ratio squared. A1: C (4).', 3),
('8b20c8da-79a6-5566-9374-1d1e98e90999', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 34, 34, 'A pilot-training rig spins a 70 kg pilot in a circle of radius 6.0 m so that the centripetal acceleration is 15 m s⁻². Calculate the period of rotation.', NULL, 2, 'numeric'::answer_type, '3.974', 's', false, NULL, false, NULL, 'a = ω²r so ω = √(a/r) = √(15 ÷ 6.0) = 1.58 rad s⁻¹. T = 2π/ω = 2π ÷ 1.581 = 3.97 s. Mark scheme (3 marks). C1: ω = √(a/r). C1: T = 2π/ω. A1: T = 3.97 s.', 3),
('6fc15718-89f8-527b-b040-badfadb9787e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 35, 35, 'A stone tied to a string is whirled in a horizontal circle. The string is shortened to half its length while the period stays the same. What happens to the tension?', NULL, 2, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'With the period (and so ω) fixed, F = mω²r ∝ r. Halving r halves the tension. Mark scheme (3 marks). C1: ω constant. C1: F ∝ r. A1: A (It halves). Common mistake: using F = mv²/r with v fixed — but v changes when r changes at constant period.', 3),
('96a1044f-d0a4-5c1e-9db7-a58952f9a832', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 36, 36, 'A 80 kg motorcyclist rides at 10 m s⁻¹ round a circle of radius 20 m. Calculate (a) the angular speed and (b) the centripetal force, using F = mω²r. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '400', 'N', false, NULL, false, NULL, '(a) ω = v/r = 10 ÷ 20 = 0.500 rad s⁻¹. (b) F = mω²r = 80 × 0.500² × 20 = 400 N (the same as mv²/r). Mark scheme (3 marks). C1: ω = v/r. C1: F = mω²r. A1: F = 400 N.', 3),
('cb2d6d21-0305-55d1-a18c-a95c52c37026', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 37, 37, 'A child spins a toy wheel of diameter 22 cm at 0.75 Hz. Calculate the centripetal acceleration of a point on the rim.', NULL, 2, 'numeric'::answer_type, '2.443', 'm s⁻²', false, NULL, false, NULL, 'r = 0.11 m. ω = 2πf = 2π × 0.75 = 4.71 rad s⁻¹. a = ω²r = (4.71)² × 0.11 = 2.44 m s⁻². Mark scheme (4 marks). C1: r = d/2 in m. C1: ω = 2πf. C1: a = ω²r. A1: a = 2.44 m s⁻².', 4),
('d874d6ea-de35-51a1-8513-dc6c9fcb2f91', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 38, 38, 'Phobos orbits Mars in a circle of radius 9.38 × 10⁶ m, taking 7.66 hours per orbit. Calculate the centripetal acceleration of Phobos.', NULL, 2, 'numeric'::answer_type, '0.487', 'm s⁻²', false, NULL, false, NULL, 'T = 7.66 × 3600 = 2.76 × 10⁴ s. a = 4π²r/T² = 4π² × 9.38 × 10⁶ ÷ (2.76 × 10⁴)² = 0.487 m s⁻². Mark scheme (3 marks). C1: T in seconds. C1: a = 4π²r/T². A1: a = 0.487 m s⁻².', 3),
('e24a76f6-cd64-5160-97c1-550eeab08a93', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 39, 39, 'A dancer spins with her arms out at 1.5 revolutions per second. Her fingertips are 0.75 m from the axis. Calculate the centripetal acceleration of her fingertips.', NULL, 2, 'numeric'::answer_type, '66.62', 'm s⁻²', false, NULL, false, NULL, 'ω = 2πf = 2π × 1.5 = 9.42 rad s⁻¹. a = ω²r = (9.42)² × 0.75 = 66.6 m s⁻². Mark scheme (3 marks). C1: ω = 2πf. C1: a = ω²r. A1: a = 66.6 m s⁻².', 3),
('87a40386-73da-568a-a7e9-f005650f29e2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 40, 40, 'A car rounds a bend with a centripetal acceleration of 4.5 m s⁻². The bend has radius 50 m. (a) Calculate the speed of the car. (b) Calculate the time it takes to go round a quarter of a full circle of this radius. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '5.236', 's', false, NULL, false, NULL, '(a) v = √(ar) = √(4.5 × 50) = 15.0 m s⁻¹. (b) quarter circle = πr/2 = 78.5 m, t = 78.5 ÷ 15 = 5.24 s. Mark scheme (4 marks). C1: v = √(ar). C1: arc length πr/2. C1: t = s/v. A1: t = 5.24 s.', 4),
('630d1656-5a10-572f-938c-ff7878768e78', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 41, 41, 'The International Space Station has a centripetal acceleration of 8.7 m s⁻² and orbits at a radius of 6.77 × 10⁶ m. Calculate its period.', NULL, 2, 'numeric'::answer_type, '5543', 's', false, NULL, false, NULL, 'a = 4π²r/T², so T = 2π√(r/a) = 2π × √(6.77 × 10⁶ ÷ 8.7) = 5540 s. Mark scheme (3 marks). C1: a = 4π²r/T². C1: rearranged for T. A1: T = 5540 s.', 3),
('917e8343-fe80-5c6d-ace0-b8e27b6c00d0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 42, 42, 'A crewed space station orbits 400 km above the Earth''s surface. The Earth''s radius is 6.37 × 10⁶ m and g at the surface is 9.81 m s⁻². (a) Show that the gravitational field strength at the orbit is 8.7 N kg⁻¹ (g ∝ 1/r²). (b) Explain why the centripetal acceleration equals this field strength. (c) Calculate the orbital speed. (d) Calculate the period. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '5547', 's', false, NULL, false, NULL, '(a) r = 6.37 × 10⁶ + 400000 = 6.77 × 10⁶ m. g = 9.81 × (6.37 × 10⁶ ÷ 6.770 × 10⁶)² = 8.69 N kg⁻¹. (b) Gravity is the only force, so a = F/m = g. (c) v = √(gr) = √(8.685 × 6.770 × 10⁶) = 7670 m s⁻¹. (d) T = 2πr/v = 2π × 6.770 × 10⁶ ÷ 7668 = 5550 s. Mark scheme (6 marks). M1: r = R + h. M1: inverse-square scaling. B1: gravity provides the centripetal force. C1: v = √(gr). C1: T = 2πr/v. A1: T = 5550 s.', 6),
('e2408316-fea0-5e07-bc5d-e06b360d9a35', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 43, 43, 'Mission planners place a navigation satellite in a circular orbit at an altitude of 2000 km. They know only that g = 9.81 N kg⁻¹ at the surface of the Earth (radius 6.37 × 10⁶ m) and that g falls off as 1/r². (a) Find g at the satellite''s orbit. (b) State why this is the satellite''s centripetal acceleration. (c) Find its orbital speed. (d) Find how long one orbit takes. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '7626', 's', false, NULL, false, NULL, '(a) r = 6.37 × 10⁶ + 2000000 = 8.37 × 10⁶ m. g = 9.81 × (6.37 × 10⁶ ÷ 8.370 × 10⁶)² = 5.68 N kg⁻¹. (b) Gravity is the only force, so a = F/m = g. (c) v = √(gr) = √(5.682 × 8.370 × 10⁶) = 6900 m s⁻¹. (d) T = 2πr/v = 2π × 8.370 × 10⁶ ÷ 6896 = 7630 s. Mark scheme (6 marks). M1: r = R + h. M1: inverse-square scaling. B1: gravity provides the centripetal force. C1: v = √(gr). C1: T = 2πr/v. A1: T = 7630 s.', 6),
('4645b4f0-42da-5f24-9de5-9c52f9e5da1c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 44, 44, 'A marble of mass 0.050 kg rolls round the inside of a horizontal circular ring of radius 0.20 m at 1.5 m s⁻¹. (a) Calculate its centripetal acceleration. (b) Calculate the force from the ring on the marble. (c) The speed is doubled. Calculate the new force. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.25', 'N', false, NULL, false, NULL, '(a) a = v²/r = 1.5² ÷ 0.20 = 11.2 m s⁻². (b) F = ma = 0.050 × 11.2 = 0.562 N, horizontal and towards the centre. (c) F ∝ v², so F = 0.562 × 2² = 2.25 N. Mark scheme (5 marks). C1: a = v²/r. A1: F = 2.25 N. C1: F = ma. B1: towards the centre. B1: F ∝ v².', 5),
('8142ad55-a8ed-5332-87c5-dfdae4ce9c19', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 45, 45, 'A science-fiction space station is a ring of radius 1.8 km that rotates to give "artificial gravity". Astronauts stand on the inside of the outer wall. (a) Explain how rotation makes the astronauts feel a weight. (b) Calculate the angular speed needed for the floor to push on them with a force equal to their weight on Earth. (c) Calculate the period of rotation. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '85.11', 's', false, NULL, false, NULL, '(a) The floor must push inwards on each astronaut to provide the centripetal force. They feel this contact force as weight. (b) a = ω²r = 9.81, so ω = √(9.81 ÷ 1800) = 0.0738 rad s⁻¹. (c) T = 2π/ω = 2π ÷ 0.07382 = 85.1 s. Mark scheme (5 marks). B1: floor provides centripetal force, felt as weight. C1: a = ω²r. A1: ω. C1: T = 2π/ω. A1: T = 85.1 s.', 5),
('0242b862-0efb-52ba-9db6-04b864c9c605', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 46, 46, 'A Mars-mission habitat is spun so that astronauts experience 0.38 g, the gravity on Mars. Engineers want a period of 30 s so that the spin does not cause motion sickness. (a) Calculate the angular speed. (b) Calculate the radius needed. (c) Explain why a larger radius makes the "gravity" more uniform from head to foot. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '84.98', 'm', false, NULL, false, NULL, '(a) ω = 2π ÷ 30 = 0.209 rad s⁻¹. (b) r = a/ω² = 0.38 × 9.81 ÷ (0.209)² = 85.0 m. (c) a = ω²r, so a person of height h feels a fractional difference h/r between head and feet: a large r makes this small. Mark scheme (5 marks). C1: ω = 2π/T. A1: ω. C1: r = a/ω². A1: r = 85.0 m. B1: a ∝ r, fractional change h/r.', 5),
('fca51744-0865-5934-b8d0-6b63f8d01137', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 47, 47, 'A mass of 0.40 kg on a string of length 1.2 m moves in a horizontal circle as a conical pendulum, the string making 30° with the vertical. (a) Resolve vertically to find the tension. (b) Find the radius of the circle. (c) Resolve horizontally and calculate the speed of the mass. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '1.843', 'm s⁻¹', false, NULL, false, NULL, '(a) T cos 30° = mg, so T = 0.40 × 9.81 ÷ cos 30 = 4.53 N. (b) r = L sin 30° = 1.2 × sin 30 = 0.600 m. (c) T sin θ = mv²/r. Dividing by the vertical equation: tan θ = v²/(rg), so v = √(rg tan θ) = √(0.600 × 9.81 × tan 30) = 1.84 m s⁻¹. Mark scheme (7 marks). C1: T cos θ = mg. A1: T. B1: r = L sin θ. C1: T sin θ = mv²/r. M1: combine: tan θ = v²/rg. A1: v = 1.84 m s⁻¹. B1: horizontal component provides centripetal force.', 7),
('d8ee2745-7607-5fe7-be1f-b59acac09bbc', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 48, 48, 'An electron moves in a circular orbit of radius 5.3 × 10⁻¹¹ m around a proton. The electric force on it is 8.2 × 10⁻⁸ N. (a) State the direction of the force. (b) Calculate the centripetal acceleration of the electron. (c) Calculate its speed. (d) Calculate the time for one orbit. Give only the answer to (c). Take mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '2.184e6', 'm s⁻¹', false, NULL, false, NULL, '(a) Towards the proton (attraction). (b) a = F/m = 8.2 × 10⁻⁸ ÷ 9.11 × 10⁻³¹ = 9.00 × 10²² m s⁻². (c) v = √(ar) = √(9.00 × 10²² × 5.3 × 10⁻¹¹) = 2.18 × 10⁶ m s⁻¹. (d) T = 2πr/v = 2π × 5.3 × 10⁻¹¹ ÷ 2.18 × 10⁶ = 1.52 × 10⁻¹⁶ s. Mark scheme (6 marks). B1: towards the proton. C1: a = F/m. A1: a. C1: v = √(ar). A1: v = 2.18 × 10⁶ m s⁻¹. B1: (d) T = 2πr/v.', 6),
('201bdde2-0488-5612-98f6-b654851dff0c', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 49, 49, 'An athlete spins a 7.26 kg hammer in a horizontal circle of radius 1.5 m. The wire can take a maximum tension of 1800 N. Ignore the hammer''s weight. (a) State the relationship between the tension and the speed. (b) Calculate the maximum speed of the hammer. (c) Calculate the maximum angular speed. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '19.28', 'm s⁻¹', false, NULL, false, NULL, '(a) The tension provides the centripetal force: T = mv²/r. (b) v = √(Tr/m) = √(1800 × 1.5 ÷ 7.26) = 19.3 m s⁻¹. (c) ω = v/r = 19.28 ÷ 1.5 = 12.9 rad s⁻¹. Mark scheme (5 marks). B1: T = mv²/r. C1: rearranged for v. A1: v_max. C1: ω = v/r. A1: v_max = 19.3 m s⁻¹.', 5),
('b608528c-a2d5-5a59-bcc4-2f330044bde0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '396985e8-749f-49c7-8368-5612a2941d72', 'a-level', '16.6', '9702 coursebook 16.6 · Calculating acceleration and force', 50, 50, 'A student whirls a bung on a string in a horizontal circle of radius 0.60 m and measures the tension F for different speeds v: v = 1.0, 2.0, 3.0, 4.0 m s⁻¹ gives F = 0.42, 1.66, 3.76, 6.70 N. (a) State what graph should be plotted to give a straight line through the origin. (b) Explain how the gradient is related to the mass of the bung. (c) Use the last data point to estimate the gradient, and calculate the mass of the bung. Give only the mass in (c).', NULL, 3, 'numeric'::answer_type, '0.2512', 'kg', false, NULL, false, NULL, '(a) F against v². (b) F = (m/r)v², so gradient = m/r and m = gradient × r. (c) gradient ≈ 6.70 ÷ 16.0 = 0.419 N s² m⁻², m = 0.419 × 0.60 = 0.25 kg (the first point agrees: 0.42 ÷ 1.0 × 0.60 = 0.25 kg). Mark scheme (6 marks). B1: F against v². M1: F = (m/r)v². A1: gradient = m/r. C1: gradient from data. C1: m = gradient × r. A1: m = 0.25 kg.', 6)
