INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('668906af-4cda-54cc-8dc5-e484e021acf1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 12, 12, 'A weather satellite orbiting the Earth moves in a circular path. What provides its centripetal force?', NULL, 1, 'multiple_choice'::answer_type, 'The gravitational force of the Earth', NULL, false, NULL, false, NULL, 'Gravity is the only significant force on an orbiting satellite and it points towards the Earth''s centre. Mark scheme (1 mark). B1: C (The gravitational force of the Earth).', 1),
('39891d97-90a8-52ce-bd1c-1bf09add015a', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 13, 13, 'Which force keeps a racing car on its curved path as it takes a flat, unbanked hairpin bend?', NULL, 1, 'multiple_choice'::answer_type, 'Friction between the tyres and the road', NULL, false, NULL, false, NULL, 'The weight and the normal force are vertical. The sideways friction of the road on the tyres is horizontal and towards the centre. Mark scheme (1 mark). B1: A (Friction between the tyres and the road).', 1),
('da3c9d50-d1bf-56e3-b48c-a3f4695f996f', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 14, 14, 'A conker is whirled on a string in a horizontal circle; the string slopes down slightly from the hand. What is the origin of the centripetal force on the conker?', NULL, 1, 'multiple_choice'::answer_type, 'The horizontal component of the tension in the string', NULL, false, NULL, false, NULL, 'The tension acts along the string. Its horizontal component points towards the centre of the circle; its vertical component balances the weight. Mark scheme (1 mark). B1: D (The horizontal component of the tension in the string).', 1),
('abd4ea60-84ca-5203-93f8-537ff6bcb45a', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 15, 15, 'Wet towels go round pressed against the wall of a spin-drier drum. What force on the towels acts towards the axis of the drum?', NULL, 1, 'multiple_choice'::answer_type, 'The normal contact force of the drum wall', NULL, false, NULL, false, NULL, 'The drum wall pushes inwards (normal to its surface) on the towels. Water escapes through the holes because nothing pushes it inwards. Mark scheme (1 mark). B1: B (The normal contact force of the drum wall).', 1),
('5b767703-5ee8-53cf-b9ac-aca664cf6412', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 16, 16, 'An aircraft banks its wings to turn in a horizontal circle. What provides the centripetal force?', NULL, 1, 'multiple_choice'::answer_type, 'The horizontal component of the lift force', NULL, false, NULL, false, NULL, 'Banking tilts the lift force. Its vertical component balances the weight and its horizontal component points towards the centre of the turn. Mark scheme (1 mark). B1: C (The horizontal component of the lift force).', 1),
('ac8d6cb7-0b70-5929-8916-fd1fcf53fb36', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 17, 17, 'A train rounds a curve on level track. Where does the centripetal force on the train come from?', NULL, 1, 'multiple_choice'::answer_type, 'The sideways push of the outer rail on the wheel flanges', NULL, false, NULL, false, NULL, 'The outer rail pushes inwards on the flanges of the wheels, providing the centripetal force. Mark scheme (1 mark). B1: A (The sideways push of the outer rail on the wheel flanges).', 1),
('6338fde6-85eb-5a93-96b6-d126e5e196d1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 18, 18, 'A 0.30 kg puck on an air table is tethered to a central peg and glides at 3.0 m s⁻¹ in a circle of radius 0.60 m. Calculate the tension in the tether.', NULL, 1, 'numeric'::answer_type, '4.5', 'N', false, NULL, false, NULL, 'The tether tension provides the centripetal force: T = mv²/r = 0.30 × 3.0² ÷ 0.60 = 4.5 N. Mark scheme (2 marks). C1: tension = mv²/r. A1: T = 4.5 N.', 2),
('34e323b4-e1ed-5fc1-aa3f-d54d23d89884', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 19, 19, 'A car is driven at a steady speed over the top of a hump-backed bridge. At the top, how does the normal contact force N on the car compare with its weight W?', NULL, 1, 'multiple_choice'::answer_type, 'N is less than W', NULL, false, NULL, false, NULL, 'At the top the resultant force must point down, towards the centre of the curve: W − N = mv²/r, so N < W. Mark scheme (1 mark). B1: D (N is less than W).', 1),
('0b022775-b563-54ec-af57-738027d3f183', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 20, 20, 'A passenger sits in a car going round a bend at constant speed. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The seat and door push the passenger towards the centre of the bend', NULL, false, NULL, false, NULL, 'To move in a circle the passenger needs a resultant force towards the centre. It is provided by friction from the seat and the push of the door. Mark scheme (1 mark). B1: B (The seat and door push the passenger towards the centre of the bend).', 1),
('dbe1aa28-6980-5a8c-877c-48797112e90e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 21, 21, 'A road is banked on a bend. Which force has a horizontal component that helps to provide the centripetal force, even with no friction?', NULL, 1, 'multiple_choice'::answer_type, 'The normal contact force from the road', NULL, false, NULL, false, NULL, 'On a banked road the normal force is tilted towards the centre. Its horizontal component provides some or all of the centripetal force. Mark scheme (1 mark). B1: C (The normal contact force from the road).', 1),
('3ca1b213-0812-5367-bb98-425c4f6aabbe', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 22, 22, 'A cyclist rides at 12 m s⁻¹ round a circular velodrome turn of radius 25 m. Calculate the resultant force needed towards the centre for each kilogram of the cyclist''s mass.', NULL, 1, 'numeric'::answer_type, '5.76', 'N kg⁻¹', false, NULL, false, NULL, 'F/m = v²/r = 12² ÷ 25 = 5.8 N kg⁻¹. Mark scheme (2 marks). C1: F/m = v²/r. A1: F/m = 5.8 N kg⁻¹.', 2),
('7fbc1cf6-ea88-538a-b894-a7d29bdc47b2', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 23, 23, 'A 0.60 kg pendulum bob on a string of length 0.50 m swings through its lowest point at 2.0 m s⁻¹. Calculate the tension in the string there. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '10.69', 'N', false, NULL, false, NULL, 'T − mg = mv²/r, so T = 0.60 × 9.81 + 0.60 × 2.0² ÷ 0.50 = 10.7 N. Mark scheme (2 marks). C1: T − mg = mv²/r. A1: T = 10.7 N.', 2),
('69910461-0b30-5e53-808d-293e779160ab', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 24, 24, 'Which force provides the centripetal force on a person standing on the Equator as the Earth rotates?', NULL, 1, 'multiple_choice'::answer_type, 'A small part of the gravitational pull of the Earth (the rest is balanced by the normal force)', NULL, false, NULL, false, NULL, 'The person moves in a circle, so the resultant force must point to the centre. The normal force is slightly less than the full gravitational pull; the difference, mω²R, is the centripetal force. Mark scheme (1 mark). B1: A (A small part of the gravitational pull of the Earth (the rest is balanced by the normal force)).', 1),
('5c4a38da-5e73-5aad-adbd-0bc5fc3df235', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 25, 25, 'A 1200 kg car goes over the top of a hump-backed bridge, a circular arc of radius 40 m, at 12 m s⁻¹. Calculate the normal contact force of the road on the car at the top. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '7452', 'N', false, NULL, false, NULL, 'At the top the resultant force is downwards towards the centre: mg − N = mv²/r. N = 1200 × 9.81 − 1200 × 12² ÷ 40 = 7450 N. Mark scheme (3 marks). C1: mg − N = mv²/r. C1: correct substitution. A1: N = 7450 N. Common mistake: adding mv²/r to the weight, which is the case at the bottom of a dip, not the top of a hump.', 3),
('747b4f43-fd00-5279-9594-71e9aa6a5934', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 26, 26, 'A loaded truck crests a rise in the road at 8.0 m s⁻¹. The top of the rise is a circular arc of radius 30 m. By what fraction is the force of the road on the truck reduced compared with when the road is level? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.2175', NULL, false, NULL, false, NULL, 'On the level N = mg. At the crest N = mg − mv²/r, so the fractional reduction = (mv²/r)/(mg) = v²/(rg) = 8.0² ÷ (30 × 9.81) = 0.217. Mark scheme (3 marks). C1: mg − N = mv²/r. C1: fraction = v²/rg. A1: fraction = 0.217.', 3),
('0d6a2d16-39d3-54e6-8470-5b10198a24ef', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 27, 27, 'A rally car approaches a crest whose top is a circular arc of radius 20 m. Calculate the speed at which the car would just leave the ground at the top. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '14.01', 'm s⁻¹', false, NULL, false, NULL, 'The car loses contact when N = 0, so mg = mv²/r and v = √(gr) = √(9.81 × 20) = 14.0 m s⁻¹. Mark scheme (3 marks). C1: N = 0 at loss of contact. C1: v = √(gr). A1: v = 14.0 m s⁻¹.', 3),
('7ec04b24-d79d-5b48-ac13-b445920091e6', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 28, 28, 'A bend of radius 120 m is banked at 15° to the horizontal. Calculate the speed at which a car can go round it with no sideways friction. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '17.76', 'm s⁻¹', false, NULL, false, NULL, 'Vertically: N cos θ = mg. Horizontally: N sin θ = mv²/r. Dividing: tan θ = v²/(rg), so v = √(rg tan θ) = √(120 × 9.81 × tan 15) = 17.8 m s⁻¹. Mark scheme (4 marks). C1: N cos θ = mg. C1: N sin θ = mv²/r. C1: tan θ = v²/rg. A1: v = 17.8 m s⁻¹.', 4),
('fa71a626-cbed-56c1-8e6d-566fb54a0b69', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 29, 29, 'A motorway engineer wants cars to take a curve of radius 250 m at 25 m s⁻¹ with no sideways friction. What angle of banking is needed? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '14.3', '°', false, NULL, false, NULL, 'N cos θ = mg and N sin θ = mv²/r, so tan θ = v²/(rg) = 25² ÷ (250 × 9.81) = 0.255. θ = tan⁻¹ 0.255 = 14.3°. Mark scheme (4 marks). C1: vertical: N cos θ = mg. C1: horizontal: N sin θ = mv²/r. C1: tan θ = v²/rg. A1: θ = 14.3°.', 4),
('480b58a8-161d-5217-b5eb-8947cba16285', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 30, 30, 'A light aircraft flies at 20 m s⁻¹ in a horizontal circle of radius 150 m. At what angle must it bank its wings so that the lift alone provides the centripetal force? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '15.21', '°', false, NULL, false, NULL, 'L cos θ = mg and L sin θ = mv²/r, so tan θ = v²/(rg) = 20² ÷ (150 × 9.81) = 0.272. θ = tan⁻¹ 0.272 = 15.2°. Mark scheme (4 marks). C1: vertical component of lift balances weight. C1: horizontal component = mv²/r. C1: tan θ = v²/rg. A1: θ = 15.2°.', 4),
('9b8b9977-5a00-566f-8538-de08214841a9', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 31, 31, 'Wet clothing of mass 0.80 kg rotates in a spin drier drum of radius 0.25 m at 120 rev min⁻¹. Calculate the normal contact force of the drum on the clothing.', NULL, 2, 'numeric'::answer_type, '31.58', 'N', false, NULL, false, NULL, 'ω = 2π × 120 ÷ 60 = 12.6 rad s⁻¹. The drum''s push provides the centripetal force: F = mω²r = 0.80 × 12.6² × 0.25 = 31.6 N. Mark scheme (4 marks). C1: ω in rad s⁻¹. B1: normal force provides centripetal force. C1: F = mω²r. A1: F = 31.6 N.', 4),
('acd9bd93-434d-5808-8138-9710694de5f0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 32, 32, 'A bucket of water is swung in a vertical circle. Why does the water stay in the bucket at the top, even though the bucket is upside down?', NULL, 2, 'multiple_choice'::answer_type, 'Its weight (plus the push of the bucket base) is just what is needed to provide the centripetal force, so the water moves round the circle with the bucket', NULL, false, NULL, false, NULL, 'At the top the water needs a downward resultant force mv²/r. If v² ≥ gr its weight alone is not enough, so the bucket base pushes down on it too. The water follows the circle and does not fall out. Mark scheme (3 marks). C1: centripetal force needed downwards at top. C1: weight + contact force provides it (v² ≥ gr). A1: D (Its weight (plus the push of the bucket base) is just what is needed to provide the centripetal force, so the water moves round the circle with the bucket).', 3),
('74e2aa7d-138d-5005-8958-eea86428ff7b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 33, 33, 'A 55 kg roller-coaster rider passes through the bottom of a dip, a circular arc of radius 8.0 m, at 6.0 m s⁻¹. Calculate the force of the seat on the rider. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '787.1', 'N', false, NULL, false, NULL, 'At the bottom, N − mg = mv²/r. N = 55 × 9.81 + 55 × 6.0² ÷ 8.0 = 787 N (the rider feels heavier). Mark scheme (3 marks). C1: N − mg = mv²/r. C1: substitution. A1: N = 787 N.', 3),
('6964acab-69b6-5181-8ed4-c365387f5110', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 34, 34, 'A car goes round a banked bend faster than the speed for which the bend was designed. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Friction must act down the slope to provide the extra centripetal force', NULL, false, NULL, false, NULL, 'At the design speed the horizontal component of N alone provides mv²/r. At a higher speed more inward force is needed: the car tends to slide up the slope, so friction acts down the slope and adds an inward component. Mark scheme (4 marks). C1: more centripetal force needed at higher speed. C1: car tends to slide up/out. C1: friction down the slope adds inward component. A1: B (Friction must act down the slope to provide the extra centripetal force).', 4),
('911b9c90-2b6e-59a1-8ba3-1d20068cb977', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 35, 35, 'A pendulum bob of mass 0.25 kg on a string of length 0.50 m is released from rest at a height 0.30 m above its lowest point. Calculate the tension in the string at the lowest point. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '5.396', 'N', false, NULL, false, NULL, 'Energy: v² = 2gh = 2 × 9.81 × 0.30 = 5.89 m² s⁻². At the bottom T − mg = mv²/L: T = 0.25 × 9.81 + 0.25 × 5.89 ÷ 0.50 = 5.40 N. Mark scheme (4 marks). C1: v² = 2gh. C1: T − mg = mv²/L. C1: substitution. A1: T = 5.40 N.', 4),
('08bfb084-7dd4-5f2c-b0e8-874aed0b07e0', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 36, 36, 'A cyclist rides round a flat circular path of radius 3.0 m at 5.0 m s⁻¹. To stay balanced the cyclist leans inwards so that the resultant of the friction and normal forces passes through the centre of mass. Calculate the angle of lean from the vertical. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '40.35', '°', false, NULL, false, NULL, 'N = mg (vertical) and friction F = mv²/r (horizontal, inwards). tan θ = F/N = v²/(rg) = 5.0² ÷ (3.0 × 9.81) = 0.849, so θ = tan⁻¹ 0.849 = 40.3°. Mark scheme (4 marks). C1: N = mg. C1: friction = mv²/r. C1: tan θ = v²/rg. A1: θ = 40.3°.', 4),
('ea404a2a-b363-5bbc-905b-0c5b977b93bd', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 37, 37, 'A satellite in a low circular orbit and a ball on a string whirled in a horizontal circle both move in circles. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Gravity provides the centripetal force on the satellite; tension provides it for the ball', NULL, false, NULL, false, NULL, 'The centripetal force is always provided by a real force: gravity for the satellite, the string tension (horizontal component) for the ball. Mark scheme (3 marks). C1: identifies gravity for satellite. C1: identifies tension for ball. A1: C (Gravity provides the centripetal force on the satellite; tension provides it for the ball).', 3),
('0175d5c5-b555-513d-abae-b20c2f6dcdb8', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 38, 38, 'A 45 kg child on a playground swing (chains 2.0 m long) has a speed of 4.0 m s⁻¹ at the lowest point. Calculate the force of the seat on the child there. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '801.5', 'N', false, NULL, false, NULL, 'N − mg = mv²/r, so N = 45 × 9.81 + 45 × 4.0² ÷ 2.0 = 801 N. Mark scheme (3 marks). C1: N − mg = mv²/r. C1: substitution. A1: N = 801 N.', 3),
('c9a9c93b-dd5e-526c-9234-8000e54911d3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 39, 39, 'A railway engineer wants trains to take a curve of radius 800 m at 40 m s⁻¹ so that the outer rail does not have to push sideways on the flanges. At what angle should the track be banked? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '11.52', '°', false, NULL, false, NULL, 'tan θ = v²/(rg) = 40² ÷ (800 × 9.81) = 0.204. θ = tan⁻¹ 0.204 = 11.5°. Mark scheme (3 marks). C1: banking provides centripetal force. C1: tan θ = v²/rg. A1: θ = 11.5°.', 3),
('3af2f55e-bc97-55c1-9fc5-b47614cf839b', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 40, 40, 'A car crosses a hump-backed bridge faster and faster on successive trips. Which statement describes what happens to the normal contact force at the top?', NULL, 2, 'multiple_choice'::answer_type, 'It decreases, and becomes zero at v = √(gr)', NULL, false, NULL, false, NULL, 'mg − N = mv²/r, so N = m(g − v²/r) falls as v rises and reaches zero when v² = gr. Faster than that the car leaves the road. Mark scheme (3 marks). C1: N = m(g − v²/r). C1: N = 0 at v = √(gr). A1: A (It decreases, and becomes zero at v = √(gr)).', 3),
('de273b97-dbb4-5129-aa23-b48a2128bcf5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 41, 41, 'A pilot pulls out of a dive at the bottom of a vertical circle of radius 400 m at 120 m s⁻¹. The pilot''s mass is 75 kg. Calculate the force of the seat on the pilot, as a multiple of the pilot''s weight. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '4.67', NULL, false, NULL, false, NULL, 'N − mg = mv²/r, so N/mg = 1 + v²/(rg) = 1 + 120² ÷ (400 × 9.81) = 4.67. Mark scheme (4 marks). C1: N − mg = mv²/r. C1: divide by mg. C1: substitution. A1: N/mg = 4.67.', 4),
('34e46587-8fdd-5e35-85dc-15a83e0d25f5', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 42, 42, 'An Olympic cyclist rides round a velodrome bend of radius 25 m banked at 42°. At what speed is no sideways friction needed? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '14.86', 'm s⁻¹', false, NULL, false, NULL, 'v = √(rg tan θ) = √(25 × 9.81 × tan 42) = 14.9 m s⁻¹. Mark scheme (4 marks). C1: N cos θ = mg. C1: N sin θ = mv²/r. C1: v = √(rg tan θ). A1: v = 14.9 m s⁻¹.', 4),
('e87700eb-7314-5f03-9962-ea6293a771c1', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 43, 43, 'A coin sits on a horizontal turntable that is slowly speeded up. Which statement explains why the coin eventually slides off?', NULL, 2, 'multiple_choice'::answer_type, 'The friction force needed, mω²r, rises above the maximum friction the surface can provide', NULL, false, NULL, false, NULL, 'Friction provides the centripetal force mω²r. As ω rises, the required friction rises. When it exceeds the maximum available, the coin cannot follow the circle and slides off (along the tangent at first). Mark scheme (3 marks). C1: friction provides mω²r. C1: exceeds maximum friction. A1: D (The friction force needed, mω²r, rises above the maximum friction the surface can provide).', 3),
('b8e0069f-fb68-59c9-9838-438056d69615', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 44, 44, 'A stone of mass 0.15 kg is whirled in a vertical circle of radius 0.70 m on a string. At the top it moves at 4.0 m s⁻¹. Calculate the tension in the string at the top. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '1.957', 'N', false, NULL, false, NULL, 'At the top, T + mg = mv²/r, so T = 0.15 × 4.0² ÷ 0.70 − 0.15 × 9.81 = 1.96 N. Mark scheme (3 marks). C1: T + mg = mv²/r at the top. C1: substitution. A1: T = 1.96 N.', 3),
('c2f610a5-8030-5637-be8e-66e1ebd81bd7', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 45, 45, 'A bend of radius 90 m is banked at 12°. A car of mass 1500 kg goes round it at 20 m s⁻¹. (a) Calculate the design speed, at which no friction is needed. (b) Explain why friction is needed at 20 m s⁻¹ and state its direction. (c) By resolving parallel to the slope, calculate the friction force needed. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '3462', 'N', false, NULL, false, NULL, '(a) v₀ = √(rg tan θ) = √(90 × 9.81 × tan 12) = 13.7 m s⁻¹. (b) 20 m s⁻¹ is faster than the design speed, so more centripetal force is needed than N sin θ can give: friction acts down the slope. (c) Along the slope: F + mg sin θ = m(v²/r) cos θ, so F = 1500 × (4.44 × cos 12 − 9.81 × sin 12) = 3460 N. Mark scheme (7 marks). C1: tan θ = v²/rg. A1: design speed. B1: faster than design speed. B1: friction down the slope. C1: resolving along the slope. C1: centripetal acceleration v²/r. A1: F = 3460 N.', 7),
('54f80d6c-7037-5338-8b3a-8b1d818d0d51', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 46, 46, 'A car of mass 1000 kg drives at a constant 20 m s⁻¹ over a hump and then through a dip. Both are circular arcs of radius 60 m. (a) Calculate the normal force at the top of the hump. (b) Calculate the normal force at the bottom of the dip. (c) Explain why the driver feels lighter over the hump. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '16477', 'N', false, NULL, false, NULL, '(a) mg − N = mv²/r: N = 1000 × 9.81 − 1000 × 20² ÷ 60 = 3140 N. (b) N − mg = mv²/r: N = 1000 × 9.81 + 1000 × 20² ÷ 60 = 1.65 × 10⁴ N. (c) At the top the seat pushes up on the driver with less than their weight, because part of their weight is used as the centripetal force. The contact force is what we feel as weight. Mark scheme (6 marks). C1: top: mg − N = mv²/r. A1: N top. C1: bottom: N − mg = mv²/r. A1: N bottom. B1: contact force less than weight at top. A1: N = 1.65 × 10⁴ N.', 6),
('d2dad083-2776-5ef0-b8e8-51ad2683caf3', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 47, 47, 'A ball of mass 0.15 kg hangs from a string of length 0.80 m and moves in a horizontal circle so that the string makes 40° with the vertical (a conical pendulum). (a) Identify the forces on the ball and the origin of the centripetal force. (b) Calculate the tension. (c) Show that ω² = g/(L cos θ). (d) Calculate the period. Give only the answer to (d). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '1.57', 's', false, NULL, false, NULL, '(a) Weight mg down and tension T along the string. The horizontal component T sin θ is the centripetal force. (b) T cos θ = mg: T = 0.15 × 9.81 ÷ cos 40 = 1.92 N. (c) T sin θ = mω²r = mω²L sin θ, so T = mω²L. With T = mg/cos θ: ω² = g/(L cos θ). (d) ω = √(9.81 ÷ (0.80 × cos 40)) = 4.00 rad s⁻¹, period = 2π/ω = 2π ÷ 4.001 = 1.57 s. Mark scheme (7 marks). B1: T sin θ is the centripetal force. C1: T cos θ = mg. A1: T. M1: T sin θ = mω²L sin θ. M1: combine to ω² = g/(L cos θ). C1: period = 2π/ω. A1: period = 1.57 s.', 7),
('7ec95146-00b2-57bc-a056-20e01ba1b632', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 48, 48, 'In the Bohr model of hydrogen, the electron moves round the proton in a circle of radius 5.29 × 10⁻¹¹ m. (a) State the origin of the centripetal force. (b) The force is 8.24 × 10⁻⁸ N. Calculate the speed of the electron. (c) Calculate the gravitational force between the electron and proton and use it to explain why gravity is ignored. Give only the answer to (b). Take mₑ = 9.11 × 10⁻³¹ kg, mₚ = 1.67 × 10⁻²⁷ kg and G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 3, 'numeric'::answer_type, '2.187e6', 'm s⁻¹', false, NULL, false, NULL, '(a) The electric (Coulomb) attraction between the electron and the proton. (b) F = mv²/r so v = √(Fr/m) = √(8.24 × 10⁻⁸ × 5.29 × 10⁻¹¹ ÷ 9.11 × 10⁻³¹) = 2.19 × 10⁶ m s⁻¹. (c) F_g = Gm_em_p/r² = 6.67 × 10⁻¹¹ × 9.11 × 10⁻³¹ × 1.67 × 10⁻²⁷ ÷ (5.29 × 10⁻¹¹)² = 3.63 × 10⁻⁴⁷ N, about 10³⁹ times smaller than the electric force. Mark scheme (6 marks). B1: electric attraction. C1: F = mv²/r. A1: v. C1: gravitational force formula. B1: comparison: negligible. A1: v = 2.19 × 10⁶ m s⁻¹.', 6),
('c8235204-b6b2-50ff-af64-e3a84f3e0092', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 49, 49, 'A 70 kg person stands on bathroom scales on the Equator. (a) Explain why the scales read slightly less than the person''s true weight mg. (b) Calculate the angular speed of the Earth (rotation period 86 164 s). (c) Calculate by how much the scale reading is reduced. Earth''s radius = 6.37 × 10⁶ m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.371', 'N', false, NULL, false, NULL, '(a) The person moves in a circle, so the resultant force (mg − N) must equal mω²R towards the centre: N is less than mg. (b) ω = 2π ÷ 86164 = 7.29 × 10⁻⁵ rad s⁻¹. (c) mg − N = mω²R = 70 × (7.29 × 10⁻⁵)² × 6.37 × 10⁶ = 2.37 N. Mark scheme (5 marks). B1: resultant force towards centre needed. M1: mg − N = mω²R. A1: ω. C1: substitution. A1: mg − N = 2.37 N.', 5),
('6abab21b-a3c0-5126-b7fe-fc30144bf98e', '801c5055-fda8-4ba9-91e0-37babe0c2bad', '685c0bf9-07df-4a2a-bfb1-3c4b387bc137', 'a-level', '16.7', '9702 coursebook 16.7 · The origins of centripetal forces', 50, 50, 'A stunt rider takes a curve of radius 12 m on a track banked at 30°. Friction can be up to 0.40 times the normal force. (a) Explain why there is a maximum speed. (b) For the maximum speed, friction acts down the slope with F = 0.40N. Write the vertical and horizontal force equations. (c) Show that v² = rg(tan θ + 0.40)/(1 − 0.40 tan θ) and calculate the maximum speed. Give only the speed in (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '12.23', 'm s⁻¹', false, NULL, false, NULL, '(a) Above the design speed the rider tends to slide up the slope, and friction can only supply a limited extra inward force. (b) Vertical: N cos θ − F sin θ = mg. Horizontal: N sin θ + F cos θ = mv²/r. (c) With F = 0.40N, dividing: v²/(rg) = (sin θ + 0.40 cos θ)/(cos θ − 0.40 sin θ) = (tan θ + 0.40)/(1 − 0.40 tan θ). v = √(12 × 9.81 × (tan 30 + 0.40) ÷ (1 − 0.40 × tan 30)) = 12.2 m s⁻¹. Mark scheme (7 marks). B1: friction limited. C1: vertical equation. C1: horizontal equation. M1: substitute F = 0.40N. M1: divide equations. C1: substitution. A1: v_max = 12.2 m s⁻¹.', 7)
