('7db77b2c-9ba7-57dc-a93f-b60e807b880a', 'abd4ea60-84ca-5203-93f8-537ff6bcb45a', 'The normal contact force of the drum wall', 'B', true, 1),
('c09c9d3c-7af0-5b84-a4f4-420b8ac91463', 'abd4ea60-84ca-5203-93f8-537ff6bcb45a', 'The weight of the towels', 'C', false, 2),
('ce35b284-3f04-551f-99f7-d0e7bbd682aa', 'abd4ea60-84ca-5203-93f8-537ff6bcb45a', 'Air pressure in the drum', 'D', false, 3),
