('31d939d9-4b2e-5399-bcdc-048ab206fae6', '34e323b4-e1ed-5fc1-aa3f-d54d23d89884', 'N is zero at any speed', 'C', false, 2),
('1b687ddc-c8c4-55e1-b259-1512b2f6f9e9', '34e323b4-e1ed-5fc1-aa3f-d54d23d89884', 'N is less than W', 'D', true, 3),
('179e30ef-a069-53d3-a0bb-663f9334f486', '0b022775-b563-54ec-af57-738027d3f183', 'An outward centrifugal force acts on the passenger', 'A', false, 0),
('14ac8a8e-7dab-58dd-9619-c9749cf8d38a', '0b022775-b563-54ec-af57-738027d3f183', 'The seat and door push the passenger towards the centre of the bend', 'B', true, 1),
('c91057d9-ecc8-52c9-a304-a6b46ba51ff2', '0b022775-b563-54ec-af57-738027d3f183', 'No resultant force acts on the passenger', 'C', false, 2),
('b939ab48-114f-5a33-85f1-59b5d4d1938c', '0b022775-b563-54ec-af57-738027d3f183', 'The passenger accelerates away from the centre', 'D', false, 3),
('6866329d-b337-5668-8c04-a791ab9810c8', 'dbe1aa28-6980-5a8c-877c-48797112e90e', 'The weight of the car', 'A', false, 0),
('cb53c3b9-2a5a-5f8a-ad0f-ba963f4e85bf', 'dbe1aa28-6980-5a8c-877c-48797112e90e', 'The driving force', 'B', false, 1),
('154881ae-07ff-5b21-84fd-0cedb2c3d2d8', 'dbe1aa28-6980-5a8c-877c-48797112e90e', 'The normal contact force from the road', 'C', true, 2),
('dc1c50dd-3af7-5379-bb0b-465589add356', 'dbe1aa28-6980-5a8c-877c-48797112e90e', 'Air resistance', 'D', false, 3),
('ba119a77-10c4-5b27-9681-8694001479bc', '69910461-0b30-5e53-808d-293e779160ab', 'A small part of the gravitational pull of the Earth (the rest is balanced by the normal force)', 'A', true, 0),
('d77b38a6-0ee6-5607-9350-57da91c6c755', '69910461-0b30-5e53-808d-293e779160ab', 'The normal contact force of the ground, which pushes outwards', 'B', false, 1),
('a7ce49b1-623b-5d65-a509-2fe9dc471244', '69910461-0b30-5e53-808d-293e779160ab', 'A centrifugal force due to the rotation', 'C', false, 2),
('01e0ad1c-e4d4-5fbe-8008-fc5da127c88a', '69910461-0b30-5e53-808d-293e779160ab', 'Air resistance', 'D', false, 3),
('ea9b6bb7-04a5-5400-895f-38f21f94c542', 'acd9bd93-434d-5808-8138-9710694de5f0', 'A centrifugal force pushes the water up into the bucket', 'A', false, 0),
('3d065ef8-f3da-5b09-8b7f-8430696cabdb', 'acd9bd93-434d-5808-8138-9710694de5f0', 'There is no gravity acting on the water while it moves', 'B', false, 1),
('705c3130-b2e2-5c21-820d-9b2fe1ac0533', 'acd9bd93-434d-5808-8138-9710694de5f0', 'Air pressure holds the water in', 'C', false, 2),
('af137da5-4700-5e16-847c-e2a418aad857', 'acd9bd93-434d-5808-8138-9710694de5f0', 'Its weight (plus the push of the bucket base) is just what is needed to provide the centripetal force, so the water moves round the circle with the bucket', 'D', true, 3),
('a1eae7db-df81-5090-bfab-26f4178a1b88', '6964acab-69b6-5181-8ed4-c365387f5110', 'Friction must act up the slope', 'A', false, 0),
('00be29e8-0627-532b-9b27-4dd54e5292a4', '6964acab-69b6-5181-8ed4-c365387f5110', 'Friction must act down the slope to provide the extra centripetal force', 'B', true, 1),
('89a0f4e1-9bf7-5327-bf80-7e81ad148d96', '6964acab-69b6-5181-8ed4-c365387f5110', 'No friction is needed at any speed on a banked bend', 'C', false, 2),
('1696d0c1-9507-5134-ab79-694e8649809a', '6964acab-69b6-5181-8ed4-c365387f5110', 'The normal force alone provides more force at higher speed', 'D', false, 3),
('3c496653-752a-5cd8-9efd-7efe54193892', 'ea404a2a-b363-5bbc-905b-0c5b977b93bd', 'Both are kept in orbit by centrifugal force', 'A', false, 0),
('a6924280-b560-5faa-bb14-9a287e302b90', 'ea404a2a-b363-5bbc-905b-0c5b977b93bd', 'Gravity provides the centripetal force in both cases', 'B', false, 1),
